// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/artist/IStreamArtistArchiveV2.sol";
import "../../libraries/SSTORE2.sol";

/// @notice Append-only evidence archive for the proposed artist-authority successor.
/// @dev This contract owns no semantic record or decision. It never authenticates an artist,
///      consumes replay, answers current/latest state, calls a semantic owner, or exposes a
///      mutable binding. Exact evidence must be joined to authoritative owner state elsewhere.
contract StreamArtistArchiveV2 is IStreamArtistArchiveV2 {
    bytes32 private constant _MARKER = keccak256("6529STREAM_ARTIST_ARCHIVE_V2");
    bytes32 private constant _BINDING_DOMAIN = keccak256("6529STREAM_ARTIST_ARCHIVE_BINDING_V2");
    uint16 private constant _SCHEMA_VERSION = 2;

    struct EvidenceRecord {
        address pointer;
        uint32 payloadSize;
        uint64 appendedAtBlock;
        bytes32 contentHash;
    }

    address public immutable override artistRegistry;
    address public immutable override operationCoordinator;
    bytes32 public immutable override artistArchiveBindingHashV2;

    mapping(bytes32 evidenceId => mapping(uint64 evidenceVersion => EvidenceRecord)) private
        _evidence;

    constructor(address artistRegistry_, address operationCoordinator_) {
        if (artistRegistry_ == address(0) || operationCoordinator_ == address(0)) {
            revert ArtistArchiveInvalidBinding(artistRegistry_, operationCoordinator_);
        }
        artistRegistry = artistRegistry_;
        operationCoordinator = operationCoordinator_;
        artistArchiveBindingHashV2 = keccak256(
            abi.encode(
                _BINDING_DOMAIN,
                block.chainid,
                artistRegistry_,
                operationCoordinator_,
                type(IStreamArtistArchiveV2).interfaceId,
                _MARKER,
                _SCHEMA_VERSION,
                SSTORE2.MAX_DATA_LENGTH
            )
        );
    }

    function supportsInterface(bytes4 interfaceId) external pure returns (bool) {
        return interfaceId == type(IStreamArtistArchiveV2).interfaceId
            || interfaceId == type(IERC165).interfaceId;
    }

    function artistArchiveMarkerV2() external pure returns (bytes32) {
        return _MARKER;
    }

    function artistArchiveSchemaV2() external pure returns (uint16) {
        return _SCHEMA_VERSION;
    }

    function artistArchiveMaxEvidenceBytesV2() external pure returns (uint256) {
        return SSTORE2.MAX_DATA_LENGTH;
    }

    function appendArtistEvidenceV2(
        bytes32 evidenceId,
        uint64 evidenceVersion,
        bytes calldata evidence
    ) external returns (bytes32 contentHash, address pointer, bool appended) {
        if (msg.sender != operationCoordinator) {
            revert ArtistArchiveUnauthorizedWriter(msg.sender);
        }
        _requireValidKey(evidenceId, evidenceVersion);
        uint256 payloadSize = evidence.length;
        if (payloadSize == 0) {
            revert ArtistArchiveEmptyEvidence(evidenceId, evidenceVersion);
        }
        if (payloadSize > SSTORE2.MAX_DATA_LENGTH) {
            revert ArtistArchiveEvidenceTooLarge(payloadSize, SSTORE2.MAX_DATA_LENGTH);
        }
        if (block.number > type(uint64).max) {
            revert ArtistArchiveBlockNumberOverflow(block.number);
        }

        contentHash = keccak256(evidence);
        EvidenceRecord storage record = _evidence[evidenceId][evidenceVersion];
        if (record.pointer != address(0)) {
            if (record.contentHash != contentHash || record.payloadSize != payloadSize) {
                revert ArtistArchiveEvidenceConflict(
                    evidenceId, evidenceVersion, record.contentHash, contentHash
                );
            }
            return (record.contentHash, record.pointer, false);
        }

        pointer = SSTORE2.write(evidence);
        record.pointer = pointer;
        // `payloadSize <= SSTORE2.MAX_DATA_LENGTH`, so this narrowing is exact.
        // forge-lint: disable-next-line(unsafe-typecast)
        record.payloadSize = uint32(payloadSize);
        // The explicit bound above makes the frozen uint64 receipt field exact.
        // forge-lint: disable-next-line(unsafe-typecast)
        record.appendedAtBlock = uint64(block.number);
        record.contentHash = contentHash;
        emit ArtistArchiveEvidenceAppendedV2(
            evidenceId, evidenceVersion, contentHash, pointer, payloadSize
        );
        return (contentHash, pointer, true);
    }

    function artistEvidenceMetadataV2(bytes32 evidenceId, uint64 evidenceVersion)
        external
        view
        returns (bytes32 contentHash, address pointer, uint32 payloadSize, uint64 appendedAtBlock)
    {
        _requireValidKey(evidenceId, evidenceVersion);
        EvidenceRecord storage record = _evidence[evidenceId][evidenceVersion];
        if (record.pointer == address(0)) {
            revert ArtistArchiveEvidenceUnavailable(evidenceId, evidenceVersion);
        }
        return (record.contentHash, record.pointer, record.payloadSize, record.appendedAtBlock);
    }

    function artistEvidenceBytesV2(bytes32 evidenceId, uint64 evidenceVersion)
        external
        view
        returns (bytes memory evidence)
    {
        _requireValidKey(evidenceId, evidenceVersion);
        EvidenceRecord storage record = _evidence[evidenceId][evidenceVersion];
        if (record.pointer == address(0)) {
            revert ArtistArchiveEvidenceUnavailable(evidenceId, evidenceVersion);
        }
        evidence = SSTORE2.read(record.pointer);
        bytes32 observedHash = keccak256(evidence);
        if (evidence.length != record.payloadSize || observedHash != record.contentHash) {
            revert ArtistArchiveEvidenceCorrupted(
                evidenceId, evidenceVersion, record.contentHash, observedHash
            );
        }
    }

    function _requireValidKey(bytes32 evidenceId, uint64 evidenceVersion) private pure {
        if (evidenceId == bytes32(0) || evidenceVersion == 0) {
            revert ArtistArchiveInvalidEvidenceKey(evidenceId, evidenceVersion);
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/artist/IStreamArtistRegistryV2.sol";

/// @notice Constructor-fixed typed directory for the proposed artist-authority successor.
/// @dev This contract performs no dependency calls and has no runtime storage-write path. Its
///      private storage is configuration only, not artist semantic state. It does not authorize,
///      route, coordinate, consume replay, own records, or answer current/latest artist state.
contract StreamArtistRegistryV2 is IStreamArtistRegistryV2 {
    bytes32 private constant _MARKER = keccak256("6529STREAM_ARTIST_REGISTRY_V2");
    bytes32 private constant _BINDING_DOMAIN = keccak256("6529STREAM_ARTIST_REGISTRY_BINDING_V2");
    bytes32 private constant _EXTERNAL_PROVIDER_BINDING_DOMAIN =
        keccak256("6529STREAM_ARTIST_EXTERNAL_PROVIDER_BINDING_V2");
    bytes32 private constant _SCHEMA_HASH = keccak256("6529stream.artist-registry-directory.v2");
    bytes32 private constant _EMPTY_CODE_HASH = keccak256("");
    uint16 private constant _SCHEMA_VERSION = 2;
    uint8 private constant _COORDINATOR_PIN_CLASS = 0;
    uint8 private constant _ARCHIVE_PIN_CLASS = 1;
    uint8 private constant _OWNER_PIN_CLASS = 2;
    uint8 private constant _PROVIDER_PIN_CLASS = 3;
    uint256 private constant _COMPONENT_COUNT = 14;

    ArtistDirectoryPinV2 private _operationCoordinator;
    ArtistDirectoryPinV2 private _archive;
    ArtistDirectoryPinV2[7] private _semanticOwners;
    ArtistDirectoryPinV2[5] private _externalProviders;
    // Constructor-only storage deliberately keeps the runtime codehash configuration-independent.
    // slither-disable-next-line immutable-states
    bytes32 private _recipeSetHash;
    // Constructor-only storage deliberately keeps the runtime codehash configuration-independent.
    // slither-disable-next-line immutable-states
    bytes32 private _registryBindingHash;

    constructor(ArtistRegistryConfigurationV2 memory configuration) {
        if (configuration.recipeSetHash == bytes32(0)) {
            revert ArtistRegistryInvalidRecipeSetHash(configuration.recipeSetHash);
        }

        address[] memory seenAddresses = new address[](_COMPONENT_COUNT);
        uint256 seenCount = 0;
        _validatePin(configuration.operationCoordinator, _COORDINATOR_PIN_CLASS, 0);
        seenCount = _requireUniqueAddress(
            seenAddresses, seenCount, configuration.operationCoordinator.expectedAddress
        );
        _validatePin(configuration.archive, _ARCHIVE_PIN_CLASS, 0);
        seenCount =
            _requireUniqueAddress(seenAddresses, seenCount, configuration.archive.expectedAddress);

        for (uint8 i = 0; i < configuration.semanticOwners.length; i++) {
            ArtistDirectoryPinV2 memory pin = configuration.semanticOwners[i];
            _validatePin(pin, _OWNER_PIN_CLASS, i);
            seenCount = _requireUniqueAddress(seenAddresses, seenCount, pin.expectedAddress);
        }
        for (uint8 i = 0; i < configuration.externalProviders.length; i++) {
            ArtistDirectoryPinV2 memory pin = configuration.externalProviders[i];
            _validatePin(pin, _PROVIDER_PIN_CLASS, i);
            bytes32 expectedBindingHash =
                _externalProviderBindingHash(ArtistExternalProviderV2(i), pin);
            if (pin.expectedBindingHash != expectedBindingHash) {
                revert ArtistRegistryExternalProviderBindingMismatch(
                    ArtistExternalProviderV2(i), expectedBindingHash, pin.expectedBindingHash
                );
            }
            seenCount = _requireUniqueAddress(seenAddresses, seenCount, pin.expectedAddress);
        }

        _storePin(_operationCoordinator, configuration.operationCoordinator);
        _storePin(_archive, configuration.archive);
        for (uint256 i = 0; i < configuration.semanticOwners.length; i++) {
            _storePin(_semanticOwners[i], configuration.semanticOwners[i]);
        }
        for (uint256 i = 0; i < configuration.externalProviders.length; i++) {
            _storePin(_externalProviders[i], configuration.externalProviders[i]);
        }
        _recipeSetHash = configuration.recipeSetHash;
        _registryBindingHash = keccak256(
            abi.encode(
                _BINDING_DOMAIN,
                block.chainid,
                address(this),
                type(IStreamArtistRegistryV2).interfaceId,
                _MARKER,
                _SCHEMA_VERSION,
                _SCHEMA_HASH,
                configuration.recipeSetHash,
                _pinHash(configuration.operationCoordinator),
                _pinHash(configuration.archive),
                keccak256(abi.encode(configuration.semanticOwners)),
                keccak256(abi.encode(configuration.externalProviders))
            )
        );
    }

    function supportsInterface(bytes4 interfaceId) external pure returns (bool) {
        return interfaceId == type(IStreamArtistRegistryV2).interfaceId
            || interfaceId == type(IERC165).interfaceId;
    }

    function artistRegistryMarkerV2() external pure returns (bytes32) {
        return _MARKER;
    }

    function artistRegistrySchemaV2() external pure returns (uint16) {
        return _SCHEMA_VERSION;
    }

    function artistRegistrySchemaHashV2() external pure returns (bytes32) {
        return _SCHEMA_HASH;
    }

    function artistRecipeSetHashV2() external view returns (bytes32) {
        return _recipeSetHash;
    }

    function artistRegistryBindingHashV2() external view returns (bytes32) {
        return _registryBindingHash;
    }

    function artistCoordinatorPinV2() external view returns (ArtistDirectoryPinV2 memory) {
        return _operationCoordinator;
    }

    function artistArchivePinV2() external view returns (ArtistDirectoryPinV2 memory) {
        return _archive;
    }

    function artistSemanticOwnerPinV2(ArtistSemanticDomainV2 domain)
        external
        view
        returns (ArtistDirectoryPinV2 memory)
    {
        return _semanticOwners[uint8(domain)];
    }

    function artistExternalProviderPinV2(ArtistExternalProviderV2 provider)
        external
        view
        returns (ArtistDirectoryPinV2 memory)
    {
        return _externalProviders[uint8(provider)];
    }

    function _validatePin(ArtistDirectoryPinV2 memory pin, uint8 pinClass, uint8 pinIndex)
        private
        pure
    {
        if (
            pin.expectedAddress == address(0) || pin.expectedRuntimeCodeHash == bytes32(0)
                || pin.expectedRuntimeCodeHash == _EMPTY_CODE_HASH
                || pin.expectedInterfaceId == bytes4(0)
                || pin.expectedInterfaceId == bytes4(0xffffffff)
                || pin.expectedMarkerHash == bytes32(0) || pin.expectedSchemaHash == bytes32(0)
                || pin.expectedBindingHash == bytes32(0)
        ) {
            revert ArtistRegistryInvalidPin(pinClass, pinIndex);
        }
    }

    function _requireUniqueAddress(
        address[] memory seenAddresses,
        uint256 seenCount,
        address expectedAddress
    ) private view returns (uint256) {
        if (expectedAddress == address(this)) {
            revert ArtistRegistryPinAddressAlias(expectedAddress);
        }
        for (uint256 i = 0; i < seenCount; i++) {
            if (seenAddresses[i] == expectedAddress) {
                revert ArtistRegistryPinAddressAlias(expectedAddress);
            }
        }
        seenAddresses[seenCount] = expectedAddress;
        return seenCount + 1;
    }

    function _externalProviderBindingHash(
        ArtistExternalProviderV2 provider,
        ArtistDirectoryPinV2 memory pin
    ) private view returns (bytes32) {
        return keccak256(
            abi.encode(
                _EXTERNAL_PROVIDER_BINDING_DOMAIN,
                block.chainid,
                _providerId(provider),
                pin.expectedAddress,
                pin.expectedRuntimeCodeHash,
                pin.expectedInterfaceId,
                pin.expectedMarkerHash,
                pin.expectedSchemaHash
            )
        );
    }

    function _providerId(ArtistExternalProviderV2 provider) private pure returns (bytes32) {
        if (provider == ArtistExternalProviderV2.RoleRegistry) {
            return keccak256("provider:role_registry");
        }
        if (provider == ArtistExternalProviderV2.Core) {
            return keccak256("provider:core");
        }
        if (provider == ArtistExternalProviderV2.GovernanceV2) {
            return keccak256("provider:governance_v2");
        }
        if (provider == ArtistExternalProviderV2.FinalityRegistry) {
            return keccak256("provider:finality_registry");
        }
        return keccak256("provider:import_continuity");
    }

    function _pinHash(ArtistDirectoryPinV2 memory pin) private pure returns (bytes32) {
        return keccak256(
            abi.encode(
                pin.expectedAddress,
                pin.expectedRuntimeCodeHash,
                pin.expectedInterfaceId,
                pin.expectedMarkerHash,
                pin.expectedSchemaHash,
                pin.expectedBindingHash
            )
        );
    }

    function _storePin(ArtistDirectoryPinV2 storage target, ArtistDirectoryPinV2 memory source)
        private
    {
        target.expectedAddress = source.expectedAddress;
        target.expectedRuntimeCodeHash = source.expectedRuntimeCodeHash;
        target.expectedInterfaceId = source.expectedInterfaceId;
        target.expectedMarkerHash = source.expectedMarkerHash;
        target.expectedSchemaHash = source.expectedSchemaHash;
        target.expectedBindingHash = source.expectedBindingHash;
    }
}

smart-contracts/domains/artist/StreamCol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/artist/IStreamCollectionArtistRegistry.sol";
import "../../interfaces/stream/core/IStreamCore.sol";
import "../../vendor/openzeppelin/ReentrancyGuard.sol";
import "../modules/StreamModuleBase.sol";
import "../mint/StreamSaleSignatures.sol";

/// @notice A collection's nominated artist accepts its attribution before the first mint.
/// @dev Acceptance is immutable. Each sale/auction separately authenticates the artist's exact
/// transaction terms; this registry does not claim collaborator, recovery, or estate capabilities.
contract StreamCollectionArtistRegistry is
    StreamModuleBase,
    ReentrancyGuard,
    IStreamCollectionArtistRegistry
{
    bytes32 public constant ACCEPTANCE_TYPEHASH = keccak256(
        "CollectionArtistAcceptance(address core,uint256 collectionId,bytes32 nominationHash,uint256 nonce,uint64 deadline)"
    );
    bytes32 private constant _DOMAIN_TYPEHASH = keccak256(
        "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
    );
    bytes32 private constant _NOMINATION_DOMAIN =
        keccak256("6529STREAM_COLLECTION_ARTIST_NOMINATION_V1");
    address public immutable override core;
    address public immutable authority;
    mapping(uint256 => Attribution) private _attributions;
    mapping(address => uint256) public override acceptanceNonces;

    constructor(
        address core_,
        address authority_,
        bytes32 deploymentManifestHash,
        string memory manifestURI,
        bytes32 manifestHash
    )
        StreamModuleBase(
            keccak256("6529stream.collection-artist.schema.v1"),
            address(0),
            deploymentManifestHash,
            manifestURI,
            manifestHash
        )
    {
        if (
            core_.code.length == 0 || authority_ == address(0) || deploymentManifestHash == 0
                || manifestHash == 0 || !IERC165(core_).supportsInterface(0x80ac58cd)
        ) {
            revert ArtistRegistryInvalidConfiguration();
        }
        core = core_;
        authority = authority_;
    }

    function streamModuleType() public pure override returns (bytes32) {
        return keccak256("ARTIST_REGISTRY");
    }

    function streamModuleVersion() public pure override returns (bytes32) {
        return keccak256("6529stream.collection-artist.v1");
    }

    function streamModuleInterfaceId() public pure override returns (bytes4) {
        return type(IStreamCollectionArtistRegistry).interfaceId;
    }

    function supportsInterface(bytes4 id)
        public
        view
        override(StreamModuleBase, IERC165)
        returns (bool)
    {
        return id == type(IStreamCollectionArtistRegistry).interfaceId
            || super.supportsInterface(id);
    }

    function nominateArtist(uint256 collectionId, address artist, bytes32 identityHash)
        external
        override
        nonReentrant
    {
        if (msg.sender != authority) revert ArtistRegistryUnauthorized(msg.sender);
        _requireUnstarted(collectionId);
        if (artist == address(0) || identityHash == 0) {
            revert ArtistRegistryInvalidNomination(collectionId);
        }
        Attribution storage item = _attributions[collectionId];
        if (item.artist != address(0)) revert ArtistRegistryAttributionImmutable(collectionId);
        ++item.nominationRevision;
        item.nominatedArtist = artist;
        item.identityHash = identityHash;
        item.nominationHash = keccak256(
            abi.encode(
                _NOMINATION_DOMAIN,
                block.chainid,
                address(this),
                core,
                collectionId,
                artist,
                identityHash,
                item.nominationRevision
            )
        );
        emit CollectionArtistNominated(
            1, collectionId, artist, item.nominationHash, identityHash, item.nominationRevision
        );
    }

    function acceptedArtist(uint256 collectionId) external view override returns (address) {
        return _attributions[collectionId].artist;
    }

    function attribution(uint256 collectionId) external view override returns (Attribution memory) {
        return _attributions[collectionId];
    }

    function domainSeparator() public view returns (bytes32) {
        return keccak256(
            abi.encode(
                _DOMAIN_TYPEHASH,
                keccak256("6529StreamCollectionArtist"),
                keccak256("1"),
                block.chainid,
                address(this)
            )
        );
    }

    function acceptanceDigest(
        uint256 collectionId,
        bytes32 nominationHash,
        uint256 nonce,
        uint64 deadline
    ) public view override returns (bytes32) {
        return keccak256(
            abi.encodePacked(
                hex"1901",
                domainSeparator(),
                keccak256(
                    abi.encode(
                        ACCEPTANCE_TYPEHASH, core, collectionId, nominationHash, nonce, deadline
                    )
                )
            )
        );
    }

    /// @notice Anyone can relay an EOA/ERC1271 signature; the artist needs no funded transaction.
    /// @dev An artist may also accept directly with an empty signature. A nominated address is
    /// never presented as accepted, and a replaced nomination invalidates its previous signatures.
    function acceptArtist(
        uint256 collectionId,
        bytes32 nominationHash,
        uint256 nonce,
        uint64 deadline,
        bytes calldata signature
    ) external override nonReentrant {
        _requireUnstarted(collectionId);
        Attribution storage item = _attributions[collectionId];
        if (item.artist != address(0)) revert ArtistRegistryAttributionImmutable(collectionId);
        address artist = item.nominatedArtist;
        if (
            artist == address(0) || nominationHash == 0 || nominationHash != item.nominationHash
                || nonce != acceptanceNonces[artist]
        ) revert ArtistRegistryInvalidAcceptance();
        if (block.timestamp > deadline) revert ArtistRegistryAcceptanceExpired(deadline);
        bytes32 digest = acceptanceDigest(collectionId, nominationHash, nonce, deadline);
        if (
            !(msg.sender == artist && signature.length == 0)
                && !StreamSaleSignatures.isValid(artist, digest, signature)
        ) {
            revert ArtistRegistryInvalidSignature(artist);
        }
        acceptanceNonces[artist] = nonce + 1;
        item.artist = artist;
        item.acceptanceHash = digest;
        item.acceptedAt = uint64(block.timestamp);
        emit CollectionArtistAccepted(1, collectionId, artist, digest, nominationHash, nonce);
    }

    function invalidateAcceptanceNonce(uint256 newNonce) external override nonReentrant {
        uint256 oldNonce = acceptanceNonces[msg.sender];
        if (newNonce <= oldNonce) revert ArtistRegistryInvalidAcceptance();
        acceptanceNonces[msg.sender] = newNonce;
        emit ArtistAcceptanceNonceInvalidated(1, msg.sender, oldNonce, newNonce);
    }

    function requireArtist(uint256 collectionId, address artist) external view override {
        address accepted = _attributions[collectionId].artist;
        if (accepted == address(0) || artist != accepted) {
            revert ArtistRegistryArtistMismatch(collectionId, accepted, artist);
        }
    }

    function _requireUnstarted(uint256 collectionId) private view {
        IStreamCore source = IStreamCore(core);
        if (!source.collectionExists(collectionId)) {
            revert ArtistRegistryInvalidNomination(collectionId);
        }
        if (
            source.collectionMintedEver(collectionId) != 0
                || source.collectionFreezeStatus(collectionId)
        ) {
            revert ArtistRegistryCollectionStarted(collectionId);
        }
    }
}

smart-contracts/domains/auctions/StreamE.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/mint/IStreamMintReads.sol";

import "../../interfaces/stream/auctions/IStreamEnglishAuctionHouse.sol";
import "../../interfaces/stream/core/IStreamCore.sol";
import "../../interfaces/stream/mint/IStreamMintManager.sol";
import "../../interfaces/stream/revenue/IStreamSplitFactory.sol";
import "../../interfaces/stream/artist/IStreamCollectionArtistRegistry.sol";
import "../../vendor/openzeppelin/ERC165.sol";
import "../../vendor/openzeppelin/IERC721Receiver.sol";
import "../../vendor/openzeppelin/Math.sol";
import "../../vendor/openzeppelin/Ownable.sol";
import "../../vendor/openzeppelin/ReentrancyGuard.sol";
import "../mint/StreamSaleSignatures.sol";

/// @notice Current-Core English auctions with NFT custody, pull refunds and immutable sale splits.
contract StreamEnglishAuctionHouse is
    IStreamEnglishAuctionHouse,
    IERC721Receiver,
    ERC165,
    Ownable,
    ReentrancyGuard
{
    bytes32 public constant AUCTION_AUTHORIZATION_TYPEHASH = keccak256(
        "AuctionAuthorization(uint256 collectionId,bytes32 phaseId,address artist,bytes32 profileId,bytes32 tokenDataHash,bytes32 mintCommitment,bytes32 mintPolicyHash,uint256 reservePrice,uint64 startTime,uint64 endTime,uint32 extensionWindow,uint16 minBidIncrementBps,bytes32 nonce,uint64 deadline,uint64 signerEpoch)"
    );
    bytes32 private constant DOMAIN_TYPEHASH = keccak256(
        "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
    );
    bytes32 private constant NONCE_DOMAIN = keccak256("6529STREAM_ENGLISH_AUCTION_NONCE_V1");
    IStreamCore public immutable core;
    IStreamMintManager public immutable mintManager;
    IStreamSplitFactory public immutable splitFactory;
    IStreamCollectionArtistRegistry public immutable artistRegistry;
    address public platformSigner;
    uint64 public signerEpoch = 1;
    bool public paused;
    bool private _acceptingMint;
    mapping(uint256 => Auction) private _auctions;
    mapping(address => mapping(bytes32 => bool)) public authorizationUsed;
    mapping(address => uint256) public refundCredit;
    mapping(bytes32 => uint256) public nativeProceeds;
    uint256 public totalBidEscrow;
    uint256 public totalRefundOwed;
    uint256 public totalNativeProceeds;

    constructor(
        IStreamCore core_,
        IStreamMintManager mintManager_,
        IStreamSplitFactory splitFactory_,
        address platformSigner_,
        IStreamCollectionArtistRegistry artistRegistry_
    ) {
        if (
            address(core_).code.length == 0 || address(mintManager_).code.length == 0
                || address(splitFactory_).code.length == 0 || platformSigner_ == address(0)
        ) revert InvalidAuctionConfiguration();
        if (
            address(artistRegistry_).code.length == 0 || artistRegistry_.core() != address(core_)
                || !artistRegistry_.supportsInterface(
                    type(IStreamCollectionArtistRegistry).interfaceId
                ) || artistRegistry_.supportsInterface(0xffffffff)
        ) revert InvalidAuctionConfiguration();
        if (address(IStreamMintReads(address(mintManager_)).core()) != address(core_)) {
            revert InvalidAuctionConfiguration();
        }
        core = core_;
        mintManager = mintManager_;
        splitFactory = splitFactory_;
        platformSigner = platformSigner_;
        artistRegistry = artistRegistry_;
    }

    function supportsInterface(bytes4 id) public view override(ERC165, IERC165) returns (bool) {
        return id == type(IStreamEnglishAuctionHouse).interfaceId || super.supportsInterface(id);
    }

    function setPlatformSigner(address signer) external onlyOwner nonReentrant {
        if (signer == address(0)) revert InvalidAuctionConfiguration();
        platformSigner = signer;
        signerEpoch += 1;
        emit AuctionPlatformSignerChanged(signer, signerEpoch);
    }

    /// @notice Pausing stops new exposure. Existing settlement and refund exits remain available.
    function setPaused(bool paused_) external onlyOwner nonReentrant {
        paused = paused_;
        emit AuctionsPauseChanged(paused_);
    }

    function cancelAuthorization(bytes32 nonce) external nonReentrant {
        if (nonce == bytes32(0)) revert InvalidAuctionAuthorization();
        if (authorizationUsed[msg.sender][nonce]) {
            revert AuctionAuthorizationUsed(msg.sender, nonce);
        }
        authorizationUsed[msg.sender][nonce] = true;
        emit AuctionAuthorizationCancelled(msg.sender, nonce);
    }

    function domainSeparator() public view returns (bytes32) {
        return keccak256(
            abi.encode(
                DOMAIN_TYPEHASH,
                keccak256("6529StreamEnglishAuction"),
                keccak256("1"),
                block.chainid,
                address(this)
            )
        );
    }

    function authorizationDigest(AuctionAuthorization calldata authorization)
        public
        view
        override
        returns (bytes32)
    {
        return keccak256(
            abi.encodePacked(
                hex"1901",
                domainSeparator(),
                keccak256(abi.encode(AUCTION_AUTHORIZATION_TYPEHASH, authorization))
            )
        );
    }

    function authorizationId(address artist, bytes32 nonce) public view returns (bytes32) {
        return keccak256(abi.encode(NONCE_DOMAIN, block.chainid, address(this), artist, nonce));
    }

    function createAuction(
        AuctionAuthorization calldata authorization,
        bytes calldata tokenData,
        bytes calldata platformSignature,
        bytes calldata artistSignature
    ) external override nonReentrant returns (uint256 tokenId) {
        if (paused) revert AuctionsPaused();
        _validateAuthorization(authorization, tokenData);
        artistRegistry.requireArtist(authorization.collectionId, authorization.artist);
        bytes32 digest = authorizationDigest(authorization);
        _requireSignature(platformSigner, digest, platformSignature);
        _requireSignature(authorization.artist, digest, artistSignature);
        if (!splitFactory.splitWalletExists(authorization.profileId)) {
            revert InvalidAuctionSplitProfile(authorization.profileId);
        }
        address wallet = splitFactory.walletFor(authorization.profileId);
        bytes32 id = authorizationId(authorization.artist, authorization.nonce);
        authorizationUsed[authorization.artist][authorization.nonce] = true;
        bytes32 operationRoot;
        (tokenId, operationRoot) = _mintAuctionToken(authorization, tokenData, digest, id);
        _storeAuction(tokenId, authorization, wallet);
        _emitAuctionCreated(tokenId, authorization, id, operationRoot, digest, wallet);
    }

    function _emitAuctionCreated(
        uint256 tokenId,
        AuctionAuthorization calldata authorization,
        bytes32 id,
        bytes32 operationRoot,
        bytes32 digest,
        address wallet
    ) private {
        emit AuctionCreated(
            tokenId,
            authorization.artist,
            id,
            operationRoot,
            digest,
            authorization.profileId,
            wallet
        );
        emit AuctionTerms(
            tokenId,
            authorization.reservePrice,
            authorization.startTime,
            authorization.endTime,
            authorization.extensionWindow,
            authorization.minBidIncrementBps
        );
    }

    function _mintAuctionToken(
        AuctionAuthorization calldata authorization,
        bytes calldata tokenData,
        bytes32 digest,
        bytes32 id
    ) private returns (uint256 tokenId, bytes32 operationRoot) {
        IStreamMintManager.MintBatch memory batch = _mintBatch(authorization, tokenData, digest, id);
        _acceptingMint = true;
        uint256[] memory tokenIds;
        bytes32[] memory operationIds;
        (tokenIds, operationRoot, operationIds) = mintManager.executeSingleStepMint(batch, "");
        _acceptingMint = false;
        if (
            tokenIds.length != 1 || tokenIds[0] == 0 || operationRoot == bytes32(0)
                || operationIds.length != 1 || operationIds[0] == bytes32(0)
        ) revert AuctionMintResultInvalid();
        tokenId = tokenIds[0];
        if (core.ownerOf(tokenId) != address(this) || _auctions[tokenId].artist != address(0)) {
            revert AuctionMintResultInvalid();
        }
    }

    function auction(uint256 tokenId) external view override returns (Auction memory) {
        return _requireAuction(tokenId);
    }

    function auctionStatus(uint256 tokenId) external view override returns (AuctionStatus) {
        Auction storage item = _auctions[tokenId];
        if (item.artist == address(0)) return AuctionStatus.None;
        if (item.cancelled) return AuctionStatus.Cancelled;
        if (item.settled) {
            return item.highestBid == 0 ? AuctionStatus.SettledNoBid : AuctionStatus.SettledWithBid;
        }
        if (block.timestamp < item.startTime) return AuctionStatus.Created;
        if (block.timestamp < item.endTime) return AuctionStatus.Active;
        return item.highestBid == 0 ? AuctionStatus.EndedNoBid : AuctionStatus.EndedWithBid;
    }

    function minimumBid(uint256 tokenId) public view override returns (uint256) {
        Auction storage item = _requireAuction(tokenId);
        if (item.highestBid == 0) return item.reservePrice == 0 ? 1 : item.reservePrice;
        return item.highestBid
            + Math.mulDiv(item.highestBid, item.minBidIncrementBps, 10_000, Math.Rounding.Up);
    }

    function bid(uint256 tokenId, address recipient) external payable override nonReentrant {
        if (paused) revert AuctionsPaused();
        Auction storage item = _requireAuction(tokenId);
        if (item.settled || block.timestamp < item.startTime || block.timestamp >= item.endTime) {
            revert AuctionNotActive(tokenId);
        }
        if (recipient == address(0)) revert InvalidAuctionRecipient();
        uint256 required = minimumBid(tokenId);
        if (msg.value < required) revert BidTooLow(required, msg.value);
        uint256 previousBid = item.highestBid;
        if (previousBid != 0) {
            refundCredit[item.highestBidder] += previousBid;
            totalRefundOwed += previousBid;
            emit AuctionRefundCredited(item.highestBidder, tokenId, previousBid);
        }
        totalBidEscrow = totalBidEscrow - previousBid + msg.value;
        item.highestBid = msg.value;
        item.highestBidder = msg.sender;
        item.deliveryRecipient = recipient;
        if (uint256(item.endTime) - block.timestamp < item.extensionWindow) {
            uint256 extended = block.timestamp + item.extensionWindow;
            if (extended > type(uint64).max) revert InvalidAuctionConfiguration();
            item.endTime = uint64(extended);
        }
        emit AuctionBidPlaced(tokenId, msg.sender, recipient, msg.value, item.endTime);
    }

    function setDeliveryRecipient(uint256 tokenId, address recipient)
        external
        override
        nonReentrant
    {
        Auction storage item = _requireAuction(tokenId);
        if (item.settled) revert AuctionAlreadySettled(tokenId);
        address claimant = item.highestBidder == address(0) ? item.artist : item.highestBidder;
        if (msg.sender != claimant) revert UnauthorizedAuctionClaimant(msg.sender);
        if (recipient == address(0)) revert InvalidAuctionRecipient();
        item.deliveryRecipient = recipient;
        emit AuctionRecipientChanged(tokenId, recipient);
    }

    function settle(uint256 tokenId) external override nonReentrant {
        Auction storage item = _requireAuction(tokenId);
        if (item.settled) revert AuctionAlreadySettled(tokenId);
        if (block.timestamp < item.endTime) revert AuctionNotEnded(tokenId);
        if (item.highestBid == 0 && item.deliveryRecipient.code.length != 0) {
            if (item.pendingNoBidNftClaimant == address(0)) {
                item.pendingNoBidNftClaimant = item.artist;
                emit NoBidAuctionNFTClaimPending(tokenId, item.artist);
            }
            return;
        }
        item.settled = true;
        item.pendingNoBidNftClaimant = address(0);
        uint256 amount = item.highestBid;
        if (amount != 0) {
            totalBidEscrow -= amount;
            totalNativeProceeds += amount;
            nativeProceeds[item.profileId] += amount;
            _sendNative(payable(item.wallet), amount);
        }
        core.safeTransferFrom(address(this), item.deliveryRecipient, tokenId);
        emit AuctionSettled(
            tokenId, item.highestBidder, item.deliveryRecipient, item.wallet, amount
        );
    }

    /// @notice A signed artist controls delivery when an unsold NFT needs a contract receiver.
    function claimNoBidNFT(uint256 tokenId, address recipient) external override nonReentrant {
        Auction storage item = _requireAuction(tokenId);
        if (item.settled || item.pendingNoBidNftClaimant == address(0)) {
            revert NoPendingAuctionNFTClaim(tokenId);
        }
        if (msg.sender != item.pendingNoBidNftClaimant) {
            revert UnauthorizedAuctionClaimant(msg.sender);
        }
        if (recipient == address(0)) revert InvalidAuctionRecipient();
        item.settled = true;
        item.pendingNoBidNftClaimant = address(0);
        item.deliveryRecipient = recipient;
        core.safeTransferFrom(address(this), recipient, tokenId);
        emit AuctionSettled(tokenId, address(0), recipient, item.wallet, 0);
    }

    function cancel(uint256 tokenId) external override nonReentrant {
        Auction storage item = _requireAuction(tokenId);
        if (msg.sender != item.artist) revert UnauthorizedAuctionClaimant(msg.sender);
        if (item.settled || item.highestBid != 0 || block.timestamp >= item.endTime) {
            revert AuctionNotCancellable(tokenId);
        }
        item.settled = true;
        item.cancelled = true;
        core.safeTransferFrom(address(this), item.deliveryRecipient, tokenId);
        emit AuctionCancelled(tokenId, item.deliveryRecipient);
    }

    function withdrawRefund(address payable recipient) external override nonReentrant {
        if (recipient == address(0)) revert InvalidAuctionRecipient();
        uint256 amount = refundCredit[msg.sender];
        if (amount == 0) revert NoAuctionRefund();
        refundCredit[msg.sender] = 0;
        totalRefundOwed -= amount;
        _sendNative(recipient, amount);
        emit AuctionRefundWithdrawn(msg.sender, recipient, amount);
    }

    function totalOwed() public view returns (uint256) {
        return totalBidEscrow + totalRefundOwed;
    }

    function surplus() external view returns (uint256) {
        return address(this).balance - totalOwed();
    }

    function onERC721Received(address, address from, uint256, bytes calldata)
        external
        view
        override
        returns (bytes4)
    {
        if (msg.sender != address(core) || from != address(0) || !_acceptingMint) {
            revert UnexpectedAuctionNFT();
        }
        return IERC721Receiver.onERC721Received.selector;
    }

    function _validateAuthorization(AuctionAuthorization calldata item, bytes calldata tokenData)
        private
        view
    {
        if (
            item.collectionId == 0 || item.phaseId == bytes32(0) || item.artist == address(0)
                || item.profileId == bytes32(0) || item.tokenDataHash != keccak256(tokenData)
                || item.mintCommitment == bytes32(0) || item.mintPolicyHash == bytes32(0)
                || item.nonce == bytes32(0) || item.signerEpoch != signerEpoch
                || block.timestamp > item.deadline || item.endTime <= item.startTime
                || item.endTime <= block.timestamp || item.endTime > block.timestamp + 365 days
                || item.extensionWindow > 1 days || item.minBidIncrementBps == 0
                || item.minBidIncrementBps > 10_000
        ) revert InvalidAuctionAuthorization();
        if (authorizationUsed[item.artist][item.nonce]) {
            revert AuctionAuthorizationUsed(item.artist, item.nonce);
        }
    }

    function _mintBatch(
        AuctionAuthorization calldata item,
        bytes calldata tokenData,
        bytes32 digest,
        bytes32 id
    ) private view returns (IStreamMintManager.MintBatch memory batch) {
        batch.collectionId = item.collectionId;
        batch.phaseId = item.phaseId;
        batch.initialRecipients = new address[](1);
        batch.beneficiaries = new address[](1);
        batch.tokenData = new bytes[](1);
        batch.mintCommitments = new bytes32[](1);
        batch.initialRecipients[0] = address(this);
        batch.beneficiaries[0] = item.artist;
        batch.tokenData[0] = tokenData;
        batch.mintCommitments[0] = item.mintCommitment;
        batch.expectedPolicyHash = item.mintPolicyHash;
        batch.authorizationId = id;
        batch.contextHash = digest;
    }

    function _storeAuction(uint256 tokenId, AuctionAuthorization calldata item, address wallet)
        private
    {
        Auction storage created = _auctions[tokenId];
        created.artist = item.artist;
        created.wallet = wallet;
        created.profileId = item.profileId;
        created.reservePrice = item.reservePrice;
        created.startTime = item.startTime;
        created.endTime = item.endTime;
        created.extensionWindow = item.extensionWindow;
        created.minBidIncrementBps = item.minBidIncrementBps;
        created.deliveryRecipient = item.artist;
    }

    function _requireAuction(uint256 tokenId) private view returns (Auction storage item) {
        item = _auctions[tokenId];
        if (item.artist == address(0)) revert AuctionUnknown(tokenId);
    }

    function _requireSignature(address signer, bytes32 digest, bytes calldata signature)
        private
        view
    {
        if (!StreamSaleSignatures.isValid(signer, digest, signature)) {
            revert InvalidAuctionSignature(signer);
        }
    }

    function _sendNative(address payable recipient, uint256 amount) private {
        (bool ok,) = recipient.call{ value: amount }("");
        if (!ok) revert AuctionNativeTransferFailed(recipient);
    }
}

