// SPDX-License-Identifier: MIT

/**
 *
 *  @title NextGen 6529 - Dependency Registry Contract
 *  @custom:date 29-January-2023
 *  @custom:version 1.1
 *  @author 6529 team
 */

pragma solidity ^0.8.19;

import "../../interfaces/stream/access/IStreamAdmins.sol";
import "../metadata/StreamMetadataRenderer.sol";

contract DependencyRegistry {
    bytes32 public constant DEPENDENCY_SCRIPT_CONTENT_TYPEHASH = keccak256(
        "6529StreamDependencyScript(bytes32 dependencyNameAndVersion,uint256 chunkCount,bytes32 chunksHash)"
    );
    bytes32 public constant DEPENDENCY_SCRIPT_CHUNK_TYPEHASH = keccak256(
        "6529StreamDependencyScriptChunk(uint256 index,bytes32 chunkHash,uint256 byteLength)"
    );
    uint256 public constant MAX_DEPENDENCY_SCRIPT_CHUNK_BYTES = 8_192;
    uint256 public constant MAX_DEPENDENCY_SCRIPT_CHUNKS = 32;
    uint256 public constant MAX_DEPENDENCY_PROVENANCE_BYTES = 2_048;
    bytes32 private constant _FIELD_DEPENDENCY_SCRIPT = "dependency.script";
    bytes32 private constant _FIELD_DEPENDENCY_SCRIPT_COUNT = "dependency.scriptCount";
    bytes32 private constant _FIELD_DEPENDENCY_PROVENANCE = "dependency.provenance";

    error DependencyChunkIndexOutOfBounds(
        bytes32 dependencyNameAndVersion, uint256 version, uint256 index
    );
    error DependencyVersionMissing(bytes32 dependencyNameAndVersion, uint256 version);
    error DependencyKeyReserved(bytes32 dependencyNameAndVersion);
    error DependencyFieldTooLarge(bytes32 field, uint256 actual, uint256 maximum);
    error DependencyFieldInvalidUTF8(bytes32 field);

    event DependencyVersionCreated(
        bytes32 indexed dependencyNameAndVersion,
        uint256 indexed version,
        bytes32 indexed contentHash,
        address admin
    );
    event DependencyVersionDeprecated(
        bytes32 indexed dependencyNameAndVersion, uint256 indexed version, address indexed admin
    );

    struct dependencyInfoStructure {
        bytes32 _collectionDependencyName;
        string[] libraryScript;
        bytes32 contentHash;
        string provenance;
        address creator;
        uint256 createdBlock;
        uint256 createdTimestamp;
        bool deprecated;
        bool exists;
    }

    mapping(bytes32 => mapping(uint256 => dependencyInfoStructure)) private dependencyInfo;
    mapping(bytes32 => uint256) private latestDependencyVersions;

    IStreamAdmins private adminsContract;

    // certain functions can only be called by a global or function admin

    modifier FunctionAdminRequired(bytes4 _selector) {
        require(
            adminsContract.retrieveFunctionAdmin(msg.sender, address(this), _selector) == true
                || adminsContract.retrieveGlobalAdmin(msg.sender) == true,
            "Not allowed"
        );
        _;
    }

    // constructor
    constructor(address _adminsContract) {
        adminsContract = IStreamAdmins(_adminsContract);
    }

    function addDependency(bytes32 _collectionDependencyName, string[] memory _libraryScript)
        public
        FunctionAdminRequired(this.addDependency.selector)
    {
        _createDependencyVersion(_collectionDependencyName, _libraryScript, "");
    }

    function addDependencyWithProvenance(
        bytes32 _collectionDependencyName,
        string[] memory _libraryScript,
        string memory _provenance
    ) public FunctionAdminRequired(this.addDependencyWithProvenance.selector) {
        _createDependencyVersion(_collectionDependencyName, _libraryScript, _provenance);
    }

    function addDependencyScriptIndex(
        bytes32 _collectionDependencyName,
        uint256 index,
        string memory _libraryScript
    ) public FunctionAdminRequired(this.addDependencyScriptIndex.selector) {
        _requireDependencyKeyNotReserved(_collectionDependencyName);
        uint256 latestVersion = latestDependencyVersions[_collectionDependencyName];
        dependencyInfoStructure storage current =
            _dependencyVersionRecord(_collectionDependencyName, latestVersion);
        if (index >= current.libraryScript.length) {
            revert DependencyChunkIndexOutOfBounds(_collectionDependencyName, latestVersion, index);
        }

        string[] memory nextScript = new string[](current.libraryScript.length);
        for (uint256 i = 0; i < current.libraryScript.length; i++) {
            nextScript[i] = current.libraryScript[i];
        }
        nextScript[index] = _libraryScript;
        _createDependencyVersion(_collectionDependencyName, nextScript, current.provenance);
    }

    function deprecateDependencyVersion(bytes32 _collectionDependencyName, uint256 version)
        public
        FunctionAdminRequired(this.deprecateDependencyVersion.selector)
    {
        _requireDependencyKeyNotReserved(_collectionDependencyName);
        dependencyInfoStructure storage record =
            _dependencyVersionRecord(_collectionDependencyName, version);
        record.deprecated = true;
        emit DependencyVersionDeprecated(_collectionDependencyName, version, msg.sender);
    }

    // function to update admin contract

    function updateAdminContract(address _newadminsContract)
        public
        FunctionAdminRequired(this.updateAdminContract.selector)
    {
        require(
            IStreamAdmins(_newadminsContract).isAdminContract() == true, "Contract is not Admin"
        );
        adminsContract = IStreamAdmins(_newadminsContract);
    }

    function latestDependencyVersion(bytes32 dependencyNameAndVersion)
        external
        view
        returns (uint256)
    {
        return latestDependencyVersions[dependencyNameAndVersion];
    }

    function getDependencyVersionRecord(bytes32 dependencyNameAndVersion, uint256 version)
        external
        view
        returns (bytes32, uint256, uint256, bytes32, string memory, address, uint256, uint256, bool)
    {
        dependencyInfoStructure storage record =
            _dependencyVersionRecord(dependencyNameAndVersion, version);
        return (
            record._collectionDependencyName,
            version,
            record.libraryScript.length,
            record.contentHash,
            record.provenance,
            record.creator,
            record.createdBlock,
            record.createdTimestamp,
            record.deprecated
        );
    }

    function getDependencyVersionProvenance(bytes32 dependencyNameAndVersion, uint256 version)
        external
        view
        returns (string memory)
    {
        return _dependencyVersionRecord(dependencyNameAndVersion, version).provenance;
    }

    function getDependencyVersionCreator(bytes32 dependencyNameAndVersion, uint256 version)
        external
        view
        returns (address)
    {
        return _dependencyVersionRecord(dependencyNameAndVersion, version).creator;
    }

    function getDependencyVersionCreatedBlock(bytes32 dependencyNameAndVersion, uint256 version)
        external
        view
        returns (uint256)
    {
        return _dependencyVersionRecord(dependencyNameAndVersion, version).createdBlock;
    }

    function getDependencyVersionCreatedTimestamp(bytes32 dependencyNameAndVersion, uint256 version)
        external
        view
        returns (uint256)
    {
        return _dependencyVersionRecord(dependencyNameAndVersion, version).createdTimestamp;
    }

    function isDependencyVersionDeprecated(bytes32 dependencyNameAndVersion, uint256 version)
        external
        view
        returns (bool)
    {
        return _dependencyVersionRecord(dependencyNameAndVersion, version).deprecated;
    }

    function getDependencyScriptCount(bytes32 dependencyNameAndVersion)
        external
        view
        returns (uint256)
    {
        return getDependencyScriptCountAtVersion(
            dependencyNameAndVersion, latestDependencyVersions[dependencyNameAndVersion]
        );
    }

    function getDependencyScriptCountAtVersion(bytes32 dependencyNameAndVersion, uint256 version)
        public
        view
        returns (uint256)
    {
        if (version == 0) {
            return 0;
        }
        return _dependencyVersionRecord(dependencyNameAndVersion, version).libraryScript.length;
    }

    function getDependencyScript(bytes32 dependencyNameAndVersion, uint256 index)
        external
        view
        returns (string memory)
    {
        return getDependencyScriptAtVersion(
            dependencyNameAndVersion, latestDependencyVersions[dependencyNameAndVersion], index
        );
    }

    function getDependencyScriptAtVersion(
        bytes32 dependencyNameAndVersion,
        uint256 version,
        uint256 index
    ) public view returns (string memory) {
        dependencyInfoStructure storage record =
            _dependencyVersionRecord(dependencyNameAndVersion, version);
        if (index >= record.libraryScript.length) {
            revert DependencyChunkIndexOutOfBounds(dependencyNameAndVersion, version, index);
        }
        return record.libraryScript[index];
    }

    /// @notice Returns the typed hash of one dependency script chunk.
    /// @param dependencyNameAndVersion Dependency key currently stored in the registry.
    /// @param index Chunk index inside the latest dependency script version.
    /// @return The chunk hash, bound to chunk index, chunk byte length, and chunk contents.
    function getDependencyScriptChunkHash(bytes32 dependencyNameAndVersion, uint256 index)
        public
        view
        returns (bytes32)
    {
        return getDependencyScriptChunkHashAtVersion(
            dependencyNameAndVersion, latestDependencyVersions[dependencyNameAndVersion], index
        );
    }

    function getDependencyScriptChunkHashAtVersion(
        bytes32 dependencyNameAndVersion,
        uint256 version,
        uint256 index
    ) public view returns (bytes32) {
        return _hashDependencyScriptChunk(
            index, getDependencyScriptAtVersion(dependencyNameAndVersion, version, index)
        );
    }

    /// @notice Returns the typed content hash for the latest dependency script version.
    /// @param dependencyNameAndVersion Dependency key currently stored in the registry.
    /// @return The content hash for the latest chunk sequence under the dependency key.
    function getDependencyScriptContentHash(bytes32 dependencyNameAndVersion)
        external
        view
        returns (bytes32)
    {
        return getDependencyScriptContentHashAtVersion(
            dependencyNameAndVersion, latestDependencyVersions[dependencyNameAndVersion]
        );
    }

    function getDependencyScriptContentHashAtVersion(
        bytes32 dependencyNameAndVersion,
        uint256 version
    ) public view returns (bytes32) {
        if (version == 0) {
            string[] memory emptyScript = new string[](0);
            return _hashDependencyScriptContent(dependencyNameAndVersion, emptyScript);
        }
        return _dependencyVersionRecord(dependencyNameAndVersion, version).contentHash;
    }

    function _createDependencyVersion(
        bytes32 _collectionDependencyName,
        string[] memory _libraryScript,
        string memory _provenance
    ) private {
        _requireDependencyKeyNotReserved(_collectionDependencyName);
        _requireDependencyLimits(_libraryScript, _provenance);
        uint256 version = latestDependencyVersions[_collectionDependencyName] + 1;
        bytes32 contentHash =
            _hashDependencyScriptContent(_collectionDependencyName, _libraryScript);

        dependencyInfoStructure storage record = dependencyInfo[_collectionDependencyName][version];
        record._collectionDependencyName = _collectionDependencyName;
        record.contentHash = contentHash;
        record.provenance = _provenance;
        record.creator = msg.sender;
        record.createdBlock = block.number;
        // Provenance metadata only; not used for authorization, randomness, or ordering.
        record.createdTimestamp = block.timestamp;
        record.exists = true;
        for (uint256 i = 0; i < _libraryScript.length; i++) {
            record.libraryScript.push(_libraryScript[i]);
        }

        latestDependencyVersions[_collectionDependencyName] = version;
        emit DependencyVersionCreated(_collectionDependencyName, version, contentHash, msg.sender);
    }

    function _requireDependencyKeyNotReserved(bytes32 dependencyNameAndVersion) private pure {
        if (dependencyNameAndVersion == bytes32(0)) {
            revert DependencyKeyReserved(dependencyNameAndVersion);
        }
    }

    function _requireDependencyLimits(string[] memory chunks, string memory provenance)
        private
        pure
    {
        if (chunks.length > MAX_DEPENDENCY_SCRIPT_CHUNKS) {
            revert DependencyFieldTooLarge(
                _FIELD_DEPENDENCY_SCRIPT_COUNT, chunks.length, MAX_DEPENDENCY_SCRIPT_CHUNKS
            );
        }
        for (uint256 i = 0; i < chunks.length; i++) {
            _requireMaxBytes(_FIELD_DEPENDENCY_SCRIPT, chunks[i], MAX_DEPENDENCY_SCRIPT_CHUNK_BYTES);
        }
        _requireMaxBytes(_FIELD_DEPENDENCY_PROVENANCE, provenance, MAX_DEPENDENCY_PROVENANCE_BYTES);
    }

    function _requireMaxBytes(bytes32 field, string memory value, uint256 maximum) private pure {
        uint256 actual = bytes(value).length;
        if (actual > maximum) revert DependencyFieldTooLarge(field, actual, maximum);
        if (!StreamMetadataRenderer.isValidUtf8(value)) revert DependencyFieldInvalidUTF8(field);
    }

    // Slither maps the provenance timestamp field to this version-existence check.
    // slither-disable-start timestamp
    function _dependencyVersionRecord(bytes32 dependencyNameAndVersion, uint256 version)
        private
        view
        returns (dependencyInfoStructure storage)
    {
        if (version == 0 || !dependencyInfo[dependencyNameAndVersion][version].exists) {
            revert DependencyVersionMissing(dependencyNameAndVersion, version);
        }
        return dependencyInfo[dependencyNameAndVersion][version];
    }
    // slither-disable-end timestamp

    function _hashDependencyScriptContent(bytes32 dependencyNameAndVersion, string[] memory chunks)
        private
        pure
        returns (bytes32)
    {
        bytes32 chunksHash = bytes32(0);

        for (uint256 i = 0; i < chunks.length; i++) {
            chunksHash = keccak256(abi.encode(chunksHash, _hashDependencyScriptChunk(i, chunks[i])));
        }

        return keccak256(
            abi.encode(
                DEPENDENCY_SCRIPT_CONTENT_TYPEHASH,
                dependencyNameAndVersion,
                chunks.length,
                chunksHash
            )
        );
    }

    function _hashDependencyScriptChunk(uint256 index, string memory chunk)
        private
        pure
        returns (bytes32)
    {
        bytes memory chunkBytes = bytes(chunk);
        return keccak256(
            abi.encode(
                DEPENDENCY_SCRIPT_CHUNK_TYPEHASH, index, keccak256(chunkBytes), chunkBytes.length
            )
        );
    }
}

smart-contracts/domains/entropy/StreamEn.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/core/IStreamCore.sol";
import "../../interfaces/stream/entropy/IStreamEntropyCoordinator.sol";
import "../../interfaces/stream/entropy/IStreamEntropyView.sol";
import "../../interfaces/stream/entropy/IStreamEntropyProvider.sol";
import "../../vendor/openzeppelin/ReentrancyGuard.sol";
import "../modules/StreamModuleBase.sol";

/// @notice Core-bound asynchronous entropy with immutable request inputs and no ordinary reroll.
/// @dev A collection's initial policy locks on its first token or scope registration. Fresh
///      randomness recovery and provider migration require a separate explicit implementation.
contract StreamEntropyCoordinator is
    StreamModuleBase,
    ReentrancyGuard,
    IStreamEntropyCoordinator,
    IStreamEntropyView
{
    bytes32 public constant REQUEST_DOMAIN = keccak256("6529STREAM_ENTROPY_REQUEST_V1");
    bytes32 public constant SEED_DOMAIN = keccak256("6529STREAM_ENTROPY_SEED_V1");
    bytes32 public constant SCOPE_DOMAIN = keccak256("6529STREAM_ENTROPY_SCOPE_SUBJECT_V1");
    bytes32 public constant SCOPE_REQUEST_DOMAIN = keccak256("6529STREAM_ENTROPY_SCOPE_REQUEST_V1");
    bytes32 public constant SCOPE_SEED_DOMAIN = keccak256("6529STREAM_ENTROPY_SCOPE_SEED_V1");

    struct CollectionConfig {
        address provider;
        bool publicRequests;
        bool locked;
        uint64 timeoutBlocks;
        bytes32 providerConfigHash;
        bytes32 providerCodeHash;
        bytes32 collectionSalt;
    }

    struct Subject {
        uint256 collectionId;
        bytes32 inputsHash;
        bytes32 requestKey;
        bytes32 seed;
        StreamEntropyStatus status;
    }

    struct Request {
        bytes32 subjectKey;
        uint256 tokenId;
        bytes32 scopeId;
        address provider;
        uint64 requestedAtBlock;
        uint256 providerRequestId;
        bytes32 rawRandomness;
    }

    struct SeedInputs {
        bytes32 domain;
        uint256 chainId;
        address coordinator;
        address streamCore;
        uint256 collectionId;
        bytes32 identity;
        address provider;
        uint32 providerEpoch;
        bytes32 providerConfigHash;
        bytes32 requestKey;
        uint256 providerRequestId;
        bytes32 rawRandomness;
        bytes32 collectionSalt;
        bytes32 inputsHash;
    }

    IStreamCore public immutable core;
    address public immutable authority;
    mapping(uint256 => CollectionConfig) public collectionEntropyConfig;
    mapping(address => bool) public requesters;
    mapping(address => bool) public providerRevoked;
    mapping(bytes32 => Subject) private _subjects;
    mapping(bytes32 => Request) public requests;
    mapping(address => mapping(uint256 => bytes32)) public providerRequestKeys;
    mapping(address => uint256) public entropyFeeCredit;
    uint256 public totalFeeCredits;
    uint256 public pendingRequestCount;
    mapping(uint256 => bool) public metadataNotificationPending;
    mapping(bytes32 => bool) private _registeredScopes;

    error Unauthorized(address caller);
    error InvalidDependency(address target);
    error InvalidCollection(uint256 collectionId);
    error PolicyLocked(uint256 collectionId);
    error InvalidToken(uint256 tokenId);
    error InvalidSubject(bytes32 subjectKey);
    error InvalidStatus(StreamEntropyStatus actual);
    error ProviderConfigurationChanged(address provider);
    error ProviderRequestCollision(address provider, uint256 providerRequestId);
    error InsufficientEntropyFee(uint256 required, uint256 supplied);
    error InvalidDestination();
    error CreditTransferFailed();
    error RequestNotExpired();
    error ProviderOutputAlreadyReceived();
    error ProviderFailureUnproven();

    event CollectionEntropyConfigured(
        uint256 indexed collectionId,
        address indexed provider,
        bytes32 configHash,
        bytes32 collectionSalt,
        bool publicRequests,
        uint64 timeoutBlocks
    );
    event EntropyRequesterUpdated(address indexed requester, bool allowed);
    event ProviderRevocationUpdated(address indexed provider, bool revoked);
    event EntropyRegistered(
        uint256 indexed collectionId, uint256 indexed tokenId, bytes32 mintCommitment
    );
    event EntropyScopeRegistered(
        uint256 indexed collectionId, bytes32 indexed scopeId, uint8 scopeKind, bytes32 scopeRef
    );
    event EntropyRequested(
        bytes32 indexed requestKey,
        uint256 indexed tokenId,
        bytes32 indexed scopeId,
        address provider,
        uint256 providerRequestId
    );
    event EntropyFinalized(
        bytes32 indexed requestKey,
        uint256 indexed tokenId,
        bytes32 indexed scopeId,
        bytes32 seed,
        bytes32 rawRandomness
    );
    event EntropyRequestTerminal(bytes32 indexed requestKey, StreamEntropyStatus status);
    event EntropyFulfillmentRejected(bytes32 indexed requestKey, uint8 outcome);
    event EntropyFeeCredited(address indexed payer, uint256 amount);
    event EntropyFeeCreditClaimed(
        address indexed payer, address indexed destination, uint256 amount
    );
    event MetadataNotificationFailed(uint256 indexed tokenId, bytes32 indexed requestKey);

    constructor(
        address core_,
        address authority_,
        bytes32 deploymentManifestHash,
        string memory manifestURI,
        bytes32 manifestHash
    )
        StreamModuleBase(
            keccak256("6529stream.entropy-coordinator.schema.v1"),
            address(0),
            deploymentManifestHash,
            manifestURI,
            manifestHash
        )
    {
        if (core_.code.length == 0 || !IERC165(core_).supportsInterface(0x80ac58cd)) revert InvalidDependency(core_);
        if (authority_ == address(0) || deploymentManifestHash == 0 || manifestHash == 0) {
            revert InvalidDependency(authority_);
        }
        core = IStreamCore(core_);
        authority = authority_;
    }

    modifier onlyAuthority() {
        if (msg.sender != authority) revert Unauthorized(msg.sender);
        _;
    }

    function streamModuleType() public pure override returns (bytes32) {
        return 0xb3b3ef20764c647bdeda70b21ab009ff2783106d6995be14389ec6f42ea6dfbb;
    }

    function streamModuleVersion() public pure override returns (bytes32) {
        return keccak256("6529stream.entropy-coordinator.v1");
    }

    function streamModuleInterfaceId() public pure override returns (bytes4) {
        return type(IStreamEntropyCoordinator).interfaceId;
    }

    function supportsInterface(bytes4 id)
        public
        view
        override(StreamModuleBase, IERC165)
        returns (bool)
    {
        return id == type(IStreamEntropyCoordinator).interfaceId
            || id == type(IStreamEntropyView).interfaceId || super.supportsInterface(id);
    }

    function configureCollection(
        uint256 collectionId,
        address provider,
        bytes32 collectionSalt,
        bool publicRequests,
        uint64 timeoutBlocks
    ) external onlyAuthority {
        if (!core.collectionExists(collectionId)) {
            revert InvalidCollection(collectionId);
        }
        if (
            collectionEntropyConfig[collectionId].locked
                || core.collectionFreezeStatus(collectionId)
        ) revert PolicyLocked(collectionId);
        if (
            provider.code.length == 0 || timeoutBlocks == 0
                || !IERC165(provider).supportsInterface(type(IStreamEntropyProvider).interfaceId)
                || IERC165(provider).supportsInterface(0xffffffff)
        ) revert InvalidDependency(provider);
        bytes32 configHash = IStreamEntropyProvider(provider).streamEntropyProviderConfigHash();
        if (configHash == 0 || !IStreamEntropyProvider(provider).isStreamEntropyProvider()) {
            revert InvalidDependency(provider);
        }
        collectionEntropyConfig[collectionId] = CollectionConfig(
            provider,
            publicRequests,
            false,
            timeoutBlocks,
            configHash,
            provider.codehash,
            collectionSalt
        );
        emit CollectionEntropyConfigured(
            collectionId, provider, configHash, collectionSalt, publicRequests, timeoutBlocks
        );
    }

    function setRequester(address requester, bool allowed) external onlyAuthority {
        if (requester == address(0)) revert InvalidDependency(requester);
        requesters[requester] = allowed;
        emit EntropyRequesterUpdated(requester, allowed);
    }

    function setProviderRevoked(address provider, bool revoked) external onlyAuthority {
        providerRevoked[provider] = revoked;
        emit ProviderRevocationUpdated(provider, revoked);
    }

    function onTokenMinted(
        uint256 collectionId,
        uint256 tokenId,
        address recipient,
        bytes32 mintCommitment
    ) external override {
        if (msg.sender != address(core)) revert Unauthorized(msg.sender);
        (bool exists, uint256 actualCollection,, bool burned) =
            core.tokenCollectionIdentity(tokenId);
        if (
            !exists || burned || actualCollection != collectionId || recipient == address(0)
                || core.coordinatorAtMint(tokenId) != address(this)
        ) revert InvalidToken(tokenId);
        bytes32 key = _tokenKey(tokenId);
        if (_subjects[key].status != StreamEntropyStatus.NONE) revert InvalidSubject(key);
        _lockPolicy(collectionId);
        _subjects[key].collectionId = collectionId;
        _subjects[key].inputsHash = mintCommitment;
        _subjects[key].status = StreamEntropyStatus.REGISTERED;
        emit EntropyRegistered(collectionId, tokenId, mintCommitment);
    }

    function requestEntropy(uint256 tokenId)
        external
        payable
        override
        nonReentrant
        returns (bytes32 requestKey, uint256 providerRequestId)
    {
        Subject storage subject = _subjects[_tokenKey(tokenId)];
        if (
            core.tokenLifecycle(tokenId) != uint8(StreamTokenLifecycle.MINTED)
                || core.coordinatorAtMint(tokenId) != address(this)
        ) revert InvalidToken(tokenId);
        if (
            msg.sender != authority && !requesters[msg.sender]
                && !collectionEntropyConfig[subject.collectionId].publicRequests
        ) revert Unauthorized(msg.sender);
        return _request(_tokenKey(tokenId), tokenId, bytes32(0));
    }

    function registerEntropyScope(uint256 collectionId, uint8 scopeKind, bytes32 scopeRef)
        external
        override
        returns (bytes32 scopeId)
    {
        if (msg.sender != authority && !requesters[msg.sender]) {
            revert Unauthorized(msg.sender);
        }
        if (scopeKind > 2 || scopeRef == 0 || !core.collectionExists(collectionId)) {
            revert InvalidCollection(collectionId);
        }
        scopeId = keccak256(
            abi.encode(
                SCOPE_DOMAIN,
                block.chainid,
                address(this),
                address(core),
                collectionId,
                scopeKind,
                scopeRef
            )
        );
        if (_subjects[scopeId].status != StreamEntropyStatus.NONE) revert InvalidSubject(scopeId);
        _lockPolicy(collectionId);
        _registeredScopes[scopeId] = true;
        _subjects[scopeId].collectionId = collectionId;
        _subjects[scopeId].status = StreamEntropyStatus.REGISTERED;
        emit EntropyScopeRegistered(collectionId, scopeId, scopeKind, scopeRef);
    }

    function requestScopeEntropy(bytes32 scopeId, bytes32 scopeInputsHash)
        external
        payable
        override
        nonReentrant
        returns (bytes32 requestKey, uint256 providerRequestId)
    {
        if (msg.sender != authority && !requesters[msg.sender]) {
            revert Unauthorized(msg.sender);
        }
        // Token keys share _subjects storage but must never enter the mutable scope-input path.
        if (!_registeredScopes[scopeId] || scopeInputsHash == 0) revert InvalidSubject(scopeId);
        _subjects[scopeId].inputsHash = scopeInputsHash;
        return _request(scopeId, 0, scopeId);
    }

    function _lockPolicy(uint256 collectionId) private {
        CollectionConfig storage config = collectionEntropyConfig[collectionId];
        if (config.provider == address(0)) revert InvalidCollection(collectionId);
        config.locked = true;
    }

    function _request(bytes32 subjectKey, uint256 tokenId, bytes32 scopeId)
        private
        returns (bytes32 requestKey, uint256 providerRequestId)
    {
        Subject storage subject = _subjects[subjectKey];
        if (subject.status != StreamEntropyStatus.REGISTERED) revert InvalidStatus(subject.status);
        CollectionConfig storage config = collectionEntropyConfig[subject.collectionId];
        address provider = config.provider;
        if (
            providerRevoked[provider] || provider.codehash != config.providerCodeHash
                || IStreamEntropyProvider(provider).streamEntropyProviderConfigHash()
                    != config.providerConfigHash
        ) revert ProviderConfigurationChanged(provider);
        bytes memory context = abi.encode(
            uint16(scopeId == 0 ? 1 : 2),
            address(core),
            subject.collectionId,
            tokenId,
            scopeId,
            uint32(1),
            config.providerConfigHash,
            uint16(1),
            subject.inputsHash
        );
        if (scopeId == 0) {
            requestKey = keccak256(
                abi.encode(
                    REQUEST_DOMAIN,
                    block.chainid,
                    address(this),
                    address(core),
                    subject.collectionId,
                    tokenId,
                    provider,
                    uint32(1),
                    config.providerConfigHash,
                    uint16(1)
                )
            );
        } else {
            requestKey = keccak256(
                abi.encode(
                    SCOPE_REQUEST_DOMAIN,
                    block.chainid,
                    address(this),
                    address(core),
                    subject.collectionId,
                    scopeId,
                    provider,
                    uint32(1),
                    config.providerConfigHash,
                    subject.inputsHash,
                    uint16(1)
                )
            );
        }
        uint256 fee = IStreamEntropyProvider(provider).quoteRequest(context);
        if (msg.value < fee) revert InsufficientEntropyFee(fee, msg.value);
        subject.requestKey = requestKey;
        subject.status = StreamEntropyStatus.REQUESTED;
        requests[requestKey] =
            Request(subjectKey, tokenId, scopeId, provider, uint64(block.number), 0, 0);
        ++pendingRequestCount;
        if (msg.value > fee) {
            uint256 excess = msg.value - fee;
            entropyFeeCredit[msg.sender] += excess;
            totalFeeCredits += excess;
            emit EntropyFeeCredited(msg.sender, excess);
        }
        providerRequestId =
            IStreamEntropyProvider(provider).requestEntropy{ value: fee }(requestKey, context);
        if (providerRequestKeys[provider][providerRequestId] != 0) {
            revert ProviderRequestCollision(provider, providerRequestId);
        }
        providerRequestKeys[provider][providerRequestId] = requestKey;
        requests[requestKey].providerRequestId = providerRequestId;
        emit EntropyRequested(requestKey, tokenId, scopeId, provider, providerRequestId);
    }

    function fulfillEntropy(bytes32 requestKey, bytes32 rawRandomness)
        external
        override
        nonReentrant
        returns (uint8 outcome)
    {
        Request storage request = requests[requestKey];
        if (request.provider == address(0)) return _reject(requestKey, 4);
        if (msg.sender != request.provider) revert Unauthorized(msg.sender);
        Subject storage subject = _subjects[request.subjectKey];
        if (subject.status == StreamEntropyStatus.FINALIZED) return _reject(requestKey, 3);
        if (providerRevoked[msg.sender]) return _reject(requestKey, 5);
        if (subject.status == StreamEntropyStatus.STALE) return _reject(requestKey, 1);
        if (subject.status != StreamEntropyStatus.REQUESTED || subject.requestKey != requestKey) {
            return _reject(requestKey, 2);
        }
        CollectionConfig storage config = collectionEntropyConfig[subject.collectionId];
        bytes32 seed = _deriveSeed(requestKey, request, subject, config, rawRandomness);
        request.rawRandomness = rawRandomness;
        subject.seed = seed;
        subject.status = StreamEntropyStatus.FINALIZED;
        --pendingRequestCount;
        emit EntropyFinalized(requestKey, request.tokenId, request.scopeId, seed, rawRandomness);
        if (request.tokenId != 0) _notify(request.tokenId, requestKey);
        return 0;
    }

    function _deriveSeed(
        bytes32 requestKey,
        Request storage request,
        Subject storage subject,
        CollectionConfig storage config,
        bytes32 rawRandomness
    ) private view returns (bytes32) {
        SeedInputs memory inputs;
        inputs.domain = request.scopeId == 0 ? SEED_DOMAIN : SCOPE_SEED_DOMAIN;
        inputs.chainId = block.chainid;
        inputs.coordinator = address(this);
        inputs.streamCore = address(core);
        inputs.collectionId = subject.collectionId;
        inputs.identity = request.scopeId == 0 ? bytes32(request.tokenId) : request.scopeId;
        inputs.provider = request.provider;
        inputs.providerEpoch = 1;
        inputs.providerConfigHash = config.providerConfigHash;
        inputs.requestKey = requestKey;
        inputs.providerRequestId = request.providerRequestId;
        inputs.rawRandomness = rawRandomness;
        inputs.collectionSalt = config.collectionSalt;
        inputs.inputsHash = subject.inputsHash;
        return keccak256(abi.encode(inputs));
    }

    function _reject(bytes32 requestKey, uint8 outcome) private returns (uint8) {
        emit EntropyFulfillmentRejected(requestKey, outcome);
        return outcome;
    }

    function _notify(uint256 tokenId, bytes32 requestKey) private {
        try core.emitMetadataUpdate(tokenId, requestKey) {
            metadataNotificationPending[tokenId] = false;
        } catch {
            metadataNotificationPending[tokenId] = true;
            emit MetadataNotificationFailed(tokenId, requestKey);
        }
    }

    function retryMetadataNotification(uint256 tokenId) external nonReentrant {
        Subject storage subject = _subjects[_tokenKey(tokenId)];
        if (
            !metadataNotificationPending[tokenId]
                || (subject.status != StreamEntropyStatus.FINALIZED
                    && subject.status != StreamEntropyStatus.STALE
                    && subject.status != StreamEntropyStatus.FAILED)
        ) revert InvalidToken(tokenId);
        _notify(tokenId, subject.requestKey);
    }

    /// @notice Marks a timed-out request terminal without authorizing a fresh random draw.
    function markRequestStale(bytes32 requestKey) external onlyAuthority nonReentrant {
        Request storage request = requests[requestKey];
        Subject storage subject = _subjects[request.subjectKey];
        if (subject.status != StreamEntropyStatus.REQUESTED) revert InvalidStatus(subject.status);
        if (
            block.number
                <= uint256(request.requestedAtBlock)
                    + collectionEntropyConfig[subject.collectionId].timeoutBlocks
        ) revert RequestNotExpired();
        (, bytes32 boundKey,, bool received,) =
            IStreamEntropyProvider(request.provider).providerResultStatus(request.providerRequestId);
        if (boundKey != requestKey || received) revert ProviderOutputAlreadyReceived();
        _terminal(requestKey, subject, StreamEntropyStatus.STALE);
    }

    /// @notice Requires adapter evidence of terminal failure before displaying a failed request.
    function markRequestFailed(bytes32 requestKey) external onlyAuthority nonReentrant {
        Request storage request = requests[requestKey];
        Subject storage subject = _subjects[request.subjectKey];
        if (subject.status != StreamEntropyStatus.REQUESTED) revert InvalidStatus(subject.status);
        (StreamProviderResultStatus status, bytes32 boundKey,, bool received,) =
            IStreamEntropyProvider(request.provider).providerResultStatus(request.providerRequestId);
        if (
            boundKey != requestKey || received
                || status != StreamProviderResultStatus.TERMINAL_FAILED
        ) revert ProviderFailureUnproven();
        _terminal(requestKey, subject, StreamEntropyStatus.FAILED);
    }

    function _terminal(bytes32 requestKey, Subject storage subject, StreamEntropyStatus status)
        private
    {
        subject.status = status;
        --pendingRequestCount;
        emit EntropyRequestTerminal(requestKey, status);
        uint256 tokenId = requests[requestKey].tokenId;
        if (tokenId != 0) _notify(tokenId, requestKey);
    }

    function claimEntropyFeeCredit(address payable destination) external nonReentrant {
        if (destination == address(0)) revert InvalidDestination();
        uint256 amount = entropyFeeCredit[msg.sender];
        entropyFeeCredit[msg.sender] = 0;
        totalFeeCredits -= amount;
        (bool success,) = destination.call{ value: amount }("");
        if (!success) revert CreditTransferFailed();
        emit EntropyFeeCreditClaimed(msg.sender, destination, amount);
    }

    function tokenSeed(uint256 tokenId)
        external
        view
        override
        returns (bytes32 seed, bool finalized)
    {
        Subject storage subject = _subjects[_tokenKey(tokenId)];
        return (subject.seed, subject.status == StreamEntropyStatus.FINALIZED);
    }

    function tokenEntropyStatus(uint256 tokenId)
        public
        view
        override
        returns (StreamEntropyStatus)
    {
        return _subjects[_tokenKey(tokenId)].status;
    }

    function tokenEntropy(uint256 tokenId)
        external
        view
        override
        returns (
            StreamEntropyStatus status,
            bytes32 seed,
            address provider,
            uint32 providerEpoch,
            bytes32 providerConfigHash,
            bytes32 requestKey,
            uint256 providerRequestId,
            uint16 requestAttempt
        )
    {
        Subject storage subject = _subjects[_tokenKey(tokenId)];
        CollectionConfig storage config = collectionEntropyConfig[subject.collectionId];
        return (
            subject.status,
            subject.seed,
            config.provider,
            config.provider == address(0) ? 0 : 1,
            config.providerConfigHash,
            subject.requestKey,
            requests[subject.requestKey].providerRequestId,
            subject.requestKey == 0 ? 0 : 1
        );
    }

    function scopeSeed(bytes32 scopeId) external view returns (bytes32 seed, bool finalized) {
        Subject storage subject = _subjects[scopeId];
        return (subject.seed, subject.status == StreamEntropyStatus.FINALIZED);
    }

    function scopeEntropy(bytes32 scopeId) external view returns (Subject memory) {
        return _subjects[scopeId];
    }

    function _tokenKey(uint256 tokenId) private pure returns (bytes32) {
        return keccak256(abi.encode("TOKEN", tokenId));
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/entropy/IStreamEntropyProvider.sol";
import "../../interfaces/stream/entropy/IStreamEntropyCoordinator.sol";
import "../../integrations/chainlink/IVRFCoordinatorV2Plus.sol";
import "../../vendor/chainlink/VRFConsumerBaseV2.sol";
import "../../vendor/openzeppelin/ReentrancyGuard.sol";
import "../modules/StreamModuleBase.sol";

/// @notice Subscription-funded VRF v2.5 adapter. Every upstream result is stored before delivery.
/// @dev The vendored V2 base provides the unchanged rawFulfillRandomWords callback ABI and an
/// immutable sender check only; requests use the distinct v2.5 ABI with uint256 subscription IDs.
/// Upstream migration changes randomness identity and requires a new adapter deployment.
contract StreamEntropyProviderVRF is
    StreamModuleBase,
    VRFConsumerBaseV2,
    ReentrancyGuard,
    IStreamEntropyProvider
{
    bytes32 public constant RAW_DOMAIN = keccak256("6529STREAM_VRF_RAW_V1");
    uint32 public constant VRF_CALLBACK_GAS_FLOOR = 300000;
    uint32 public constant NUM_WORDS = 1;
    // This reserve belongs to the adapter frame, not to the coordinator's fulfillment envelope.
    // A subcall that exhausts its gas must leave enough to publish the retained-result outcome.
    uint256 private constant _DELIVERY_RESERVE = 50000;
    bytes4 private constant _EXTRA_ARGS_V1_TAG = bytes4(keccak256("VRF ExtraArgsV1"));

    struct Config {
        address coordinator;
        address authority;
        address vrfCoordinator;
        uint256 subscriptionId;
        bytes32 keyHash;
        uint16 requestConfirmations;
        uint32 callbackGasLimit;
        uint32 maximumCallbackGasLimit;
        bool nativePayment;
    }

    struct ProviderResult {
        bytes32 requestKey;
        bytes32 rawRandomness;
        StreamProviderResultStatus status;
        uint64 receivedAtBlock;
        uint64 deliveredAtBlock;
    }

    address public immutable coordinator;
    address public immutable authority;
    address public immutable vrfCoordinatorAddress;
    bytes32 public immutable keyHash;
    uint16 public immutable requestConfirmations;
    uint32 public immutable maximumCallbackGasLimit;
    uint32 public immutable callbackGasLimit;
    uint256 public subscriptionId;
    bool public nativePayment;
    mapping(uint256 => ProviderResult) public results;
    mapping(bytes32 => uint256) public keyToVrfRequest;

    error InvalidConfiguration();
    error Unauthorized(address caller);
    error InvalidRequest(bytes32 requestKey);
    error DuplicateProviderRequest(uint256 providerRequestId);
    error UnexpectedPayment();
    error ResultNotRetryable(uint256 providerRequestId);

    event VRFEntropyRequested(
        uint16 schemaVersion,
        bytes32 indexed requestKey,
        uint256 indexed vrfRequestId,
        uint256 indexed subscriptionId,
        uint32 providerEpoch,
        bytes32 keyHash,
        uint16 requestConfirmations,
        uint32 callbackGasLimit,
        uint32 numWords
    );
    event VRFRequestContext(
        uint16 schemaVersion, uint256 indexed vrfRequestId, bytes32 contextHash, bool nativePayment
    );
    event VRFEntropyReceived(
        uint16 schemaVersion,
        bytes32 indexed requestKey,
        uint256 indexed vrfRequestId,
        bytes32 rawRandomness
    );
    event VRFCallbackIgnored(uint16 schemaVersion, uint256 indexed vrfRequestId, uint8 reason);
    event ProviderCoordinatorFulfillmentAttempted(
        uint16 schemaVersion,
        bytes32 indexed requestKey,
        uint256 indexed providerRequestId,
        bool success,
        bytes returnData
    );
    event VRFSubscriptionUpdated(
        uint16 schemaVersion,
        uint256 indexed oldSubscriptionId,
        uint256 indexed newSubscriptionId,
        bool nativePayment
    );

    constructor(
        Config memory config,
        bytes32 deploymentManifestHash,
        string memory manifestURI,
        bytes32 manifestHash
    )
        StreamModuleBase(
            keccak256("6529stream.entropy-provider-vrf-v2.5.schema.v1"),
            address(0),
            deploymentManifestHash,
            manifestURI,
            manifestHash
        )
        VRFConsumerBaseV2(config.vrfCoordinator)
    {
        if (
            config.coordinator.code.length == 0 || config.vrfCoordinator.code.length == 0
                || config.authority == address(0) || config.subscriptionId == 0
                || config.keyHash == 0 || config.requestConfirmations == 0
                || config.requestConfirmations > 200
                || config.callbackGasLimit < VRF_CALLBACK_GAS_FLOOR
                || config.callbackGasLimit > config.maximumCallbackGasLimit
                || deploymentManifestHash == 0 || manifestHash == 0
        ) revert InvalidConfiguration();
        coordinator = config.coordinator;
        authority = config.authority;
        vrfCoordinatorAddress = config.vrfCoordinator;
        subscriptionId = config.subscriptionId;
        keyHash = config.keyHash;
        requestConfirmations = config.requestConfirmations;
        maximumCallbackGasLimit = config.maximumCallbackGasLimit;
        callbackGasLimit = config.callbackGasLimit;
        nativePayment = config.nativePayment;
    }

    function streamModuleType() public pure override returns (bytes32) {
        return keccak256("ENTROPY_PROVIDER");
    }

    function streamModuleVersion() public pure override returns (bytes32) {
        return keccak256("6529stream.entropy-provider-vrf-v2.5.v1");
    }

    function streamModuleInterfaceId() public pure override returns (bytes4) {
        return type(IStreamEntropyProvider).interfaceId;
    }

    function supportsInterface(bytes4 id)
        public
        view
        override(StreamModuleBase, IERC165)
        returns (bool)
    {
        return id == type(IStreamEntropyProvider).interfaceId || super.supportsInterface(id);
    }

    function isStreamEntropyProvider() external pure override returns (bool) {
        return true;
    }

    function streamEntropyProviderFamily() external pure override returns (bytes32) {
        return keccak256("6529STREAM_ENTROPY_PROVIDER_VRF");
    }

    function streamEntropyProviderVersion() external pure override returns (bytes32) {
        return streamModuleVersion();
    }

    function streamEntropyProviderConfigHash() external view override returns (bytes32) {
        return keccak256(
            abi.encode(
                streamModuleVersion(),
                block.chainid,
                coordinator,
                vrfCoordinatorAddress,
                keyHash,
                requestConfirmations,
                NUM_WORDS
            )
        );
    }

    function quoteRequest(bytes calldata) external pure override returns (uint256) {
        return 0;
    }

    /// @notice The subscription pays Chainlink directly; no per-request Ether is accepted here.
    function requestEntropy(bytes32 requestKey, bytes calldata context)
        external
        payable
        override
        nonReentrant
        returns (uint256 providerRequestId)
    {
        if (msg.sender != coordinator) revert Unauthorized(msg.sender);
        if (msg.value != 0) revert UnexpectedPayment();
        if (requestKey == 0 || keyToVrfRequest[requestKey] != 0) revert InvalidRequest(requestKey);
        uint32 callbackGas = callbackGasLimit;
        providerRequestId = IVRFCoordinatorV2Plus(vrfCoordinatorAddress)
            .requestRandomWords(
                IVRFCoordinatorV2Plus.RandomWordsRequest({
                keyHash: keyHash,
                subId: subscriptionId,
                requestConfirmations: requestConfirmations,
                callbackGasLimit: callbackGas,
                numWords: NUM_WORDS,
                extraArgs: abi.encodeWithSelector(_EXTRA_ARGS_V1_TAG, nativePayment)
            })
            );
        if (providerRequestId == 0 || results[providerRequestId].requestKey != 0) {
            revert DuplicateProviderRequest(providerRequestId);
        }
        keyToVrfRequest[requestKey] = providerRequestId;
        results[providerRequestId].requestKey = requestKey;
        results[providerRequestId].status = StreamProviderResultStatus.REQUESTED;
        emit VRFEntropyRequested(
            1,
            requestKey,
            providerRequestId,
            subscriptionId,
            1,
            keyHash,
            requestConfirmations,
            callbackGas,
            NUM_WORDS
        );
        emit VRFRequestContext(1, providerRequestId, keccak256(context), nativePayment);
    }

    /// @notice Operational billing only; changing this never changes a committed randomness input.
    function updateSubscription(uint256 newSubscriptionId, bool useNativePayment) external {
        if (msg.sender != authority) revert Unauthorized(msg.sender);
        if (newSubscriptionId == 0) revert InvalidConfiguration();
        emit VRFSubscriptionUpdated(1, subscriptionId, newSubscriptionId, useNativePayment);
        subscriptionId = newSubscriptionId;
        nativePayment = useNativePayment;
    }

    function fulfillRandomWords(uint256 requestId, uint256[] memory randomWords)
        internal
        override
        nonReentrant
    {
        ProviderResult storage result = results[requestId];
        if (result.status != StreamProviderResultStatus.REQUESTED) {
            emit VRFCallbackIgnored(1, requestId, result.requestKey == 0 ? 1 : 2);
            return;
        }
        if (randomWords.length != NUM_WORDS) {
            emit VRFCallbackIgnored(1, requestId, 3);
            return;
        }
        result.rawRandomness =
            keccak256(abi.encode(RAW_DOMAIN, result.requestKey, requestId, randomWords));
        result.receivedAtBlock = uint64(block.number);
        result.status = StreamProviderResultStatus.RAW_RANDOMNESS_RECEIVED;
        emit VRFEntropyReceived(1, result.requestKey, requestId, result.rawRandomness);
        _deliver(requestId, result);
    }

    function retryCoordinatorFulfillment(uint256 requestId) external override nonReentrant {
        ProviderResult storage result = results[requestId];
        if (result.status != StreamProviderResultStatus.RAW_RANDOMNESS_RECEIVED) {
            revert ResultNotRetryable(requestId);
        }
        _deliver(requestId, result);
    }

    function _deliver(uint256 requestId, ProviderResult storage result) private {
        bytes memory callData = abi.encodeCall(
            IStreamEntropyCoordinator.fulfillEntropy, (result.requestKey, result.rawRandomness)
        );
        address target = coordinator;
        uint256 availableGas = gasleft();
        if (availableGas <= _DELIVERY_RESERVE) {
            emit ProviderCoordinatorFulfillmentAttempted(1, result.requestKey, requestId, false, "");
            return;
        }
        uint256 forwardedGas = availableGas - _DELIVERY_RESERVE;
        bool success;
        uint256 responseSize;
        uint256 outcome;
        // Copy exactly one return word. A revert, OOG, invalid uint8 or malformed return cannot
        // undo the already-persisted randomness or exhaust the adapter by growing return data.
        assembly ("memory-safe") {
            let response := mload(0x40)
            mstore(response, 0)
            success := call(
                forwardedGas,
                target,
                0,
                add(callData, 32),
                mload(callData),
                response,
                32
            )
            responseSize := returndatasize()
            outcome := mload(response)
        }
        if (!success || responseSize != 32 || outcome > 5) {
            emit ProviderCoordinatorFulfillmentAttempted(1, result.requestKey, requestId, false, "");
            return;
        }
        if (outcome == 0 || outcome == 3) {
            result.status = StreamProviderResultStatus.DELIVERED;
            result.deliveredAtBlock = uint64(block.number);
        } else if (outcome == 1 || outcome == 2) {
            result.status = StreamProviderResultStatus.TERMINAL_STALE;
        }
        emit ProviderCoordinatorFulfillmentAttempted(
            1, result.requestKey, requestId, true, abi.encode(uint8(outcome))
        );
    }

    function providerResultStatus(uint256 requestId)
        external
        view
        override
        returns (
            StreamProviderResultStatus status,
            bytes32 requestKey,
            bytes32 rawRandomnessHash,
            bool rawRandomnessReceived,
            bool delivered
        )
    {
        ProviderResult storage result = results[requestId];
        status = result.status;
        requestKey = result.requestKey;
        rawRandomnessReceived = status == StreamProviderResultStatus.RAW_RANDOMNESS_RECEIVED
            || status == StreamProviderResultStatus.DELIVERED
            || status == StreamProviderResultStatus.TERMINAL_STALE;
        rawRandomnessHash =
            rawRandomnessReceived ? keccak256(abi.encode(result.rawRandomness)) : bytes32(0);
        delivered = status == StreamProviderResultStatus.DELIVERED;
    }
}

smart-contracts/domains/finality/StreamA.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/finality/IStreamArtworkFinalityComponents.sol";
import "../../interfaces/stream/finality/IStreamCoreFinalityAdapter.sol";
import "../../interfaces/stream/finality/IStreamCoreFinalitySource.sol";
import "../../interfaces/stream/finality/IStreamFinalityGovernanceAuthority.sol";
import "../../interfaces/stream/finality/IStreamFinalityMetadataReads.sol";
import "../../interfaces/stream/finality/IStreamFinalitySanctionReads.sol";
import "./StreamArtworkFinalityRegistry.sol";
import "../../interfaces/stream/finality/StreamArtworkFinalityTypes.sol";

/// @notice The finality registry's preview surface: previewFinality per [LTA-FINALITY]
///         exposes every comparison finalization performs — plus the computed sanction
///         subject hash the artist signs ([AA-SANCTION] requirement 2) — before any
///         state-changing finality transaction is sent.
/// @dev View-only periphery bound to one registry. Every pinned preimage is recomputed
///      through the registry's compute* views, never re-derived here, so preview and
///      execution cannot drift on a hash; gate semantics are covered by tests that assert
///      preview flags against execution outcomes.
contract StreamArtworkFinalityPreview {
    error FinalityPreviewZeroAddress();

    StreamArtworkFinalityRegistry public immutable registry;
    IStreamCoreFinalitySource public immutable coreReads;
    IStreamCoreFinalityAdapter public immutable coreFinalityAdapter;
    IStreamFinalityMetadataReads public immutable metadataReads;
    IStreamFinalitySanctionReads public immutable sanctionReads;
    IStreamFinalityGovernanceAuthority public immutable governanceAuthority;
    address public immutable finalityDiscovery;

    constructor(StreamArtworkFinalityRegistry registry_) {
        if (address(registry_) == address(0)) {
            revert FinalityPreviewZeroAddress();
        }
        registry = registry_;
        coreReads = registry_.coreReads();
        coreFinalityAdapter = registry_.coreFinalityAdapter();
        metadataReads = registry_.metadataReads();
        sanctionReads = registry_.sanctionReads();
        governanceAuthority = registry_.governanceAuthority();
        finalityDiscovery = registry_.finalityDiscovery();
    }

    function previewCollectionFinality(
        uint256 collectionId,
        StreamFinalityComponentExpectation[] calldata components,
        StreamFinalityManifestRef calldata manifest
    ) external view returns (StreamFinalityPreview memory) {
        return _preview(
            StreamFinalityScope({
                scopeType: StreamFinalityScopeType.COLLECTION,
                collectionId: collectionId,
                tokenId: 0,
                scopeId: bytes32(0)
            }),
            components,
            manifest
        );
    }

    function previewArtworkScopeFinality(
        StreamFinalityScope calldata scope,
        StreamFinalityComponentExpectation[] calldata components,
        StreamFinalityManifestRef calldata manifest
    ) external view returns (StreamFinalityPreview memory) {
        return _preview(scope, components, manifest);
    }

    // ------------------------------------------------------------------
    // Internal composition
    // ------------------------------------------------------------------

    function _preview(
        StreamFinalityScope memory scope,
        StreamFinalityComponentExpectation[] calldata components,
        StreamFinalityManifestRef calldata manifest
    ) private view returns (StreamFinalityPreview memory p) {
        if (!_isCanonicalScopeShape(scope)) {
            return p;
        }
        uint8 metadataMode = metadataReads.collectionMetadataMode(scope.collectionId);
        p.notAlreadyFinalized = !registry.artworkScopeFinalityRecord(scope).finalized;
        // componentsWellFormed folds the shape rule and the mode-aware mandatory-component
        // floor ([LTA-FINALITY] req 1); the registry enforces both at execution.
        p.componentsWellFormed = _componentListWellFormed(components)
            && _mandatoryComponentsPresent(components, metadataMode);
        p.computedComponentsHash = registry.computeComponentsHash(components);
        p.computedNonSanctionComponentsHash = registry.computeNonSanctionComponentsHash(components);
        p.manifestSatisfied = _manifestSatisfied(manifest);

        // coreGatesSatisfied folds the ONCHAIN/hybrid snapshot-manifest gate
        // ([CMC-FINALITY-INPUTS] rule 3) alongside the Core lifecycle gates.
        (p.coreGatesSatisfied, p.computedCoreFactsHash, p.contentRootSatisfied) =
            _coreAndContentRoot(scope);
        p.coreGatesSatisfied =
            p.coreGatesSatisfied && _snapshotManifestSatisfied(scope.collectionId, metadataMode);
        (p.sanctionSatisfied, p.computedSanctionSubjectHash) = _sanction(
            scope,
            components,
            p.computedCoreFactsHash,
            p.computedNonSanctionComponentsHash,
            manifest
        );
        p.componentsMatchLive = _componentsMatchLive(scope, components);
        p.discoveryMatches = _discoveryMatches(scope, components, p.computedComponentsHash);

        p.computedFinalityRecordHash = registry.computeFinalityRecordHash(
            scope, p.computedCoreFactsHash, p.computedComponentsHash, manifest
        );
        p.stagedFreezeReady = _stagedFreezeReady(scope, p.computedFinalityRecordHash);

        p.wouldExecute = p.notAlreadyFinalized && p.stagedFreezeReady && p.coreGatesSatisfied
            && p.contentRootSatisfied && p.manifestSatisfied && p.componentsWellFormed
            && p.componentsMatchLive && p.sanctionSatisfied && p.discoveryMatches;
    }

    function _stagedFreezeReady(StreamFinalityScope memory scope, bytes32 computedRecordHash)
        private
        view
        returns (bool)
    {
        StreamTerminalFreezeAction memory action = registry.artworkTerminalFreezeAction(scope);
        if (
            action.status != StreamTerminalFreezeStatus.SCHEDULED
                || block.timestamp < action.notBefore || block.timestamp > action.expiresAfter
                || action.expectedFinalityRecordHash != computedRecordHash
        ) {
            return false;
        }
        // Defense in depth ([LTA-FREEZE] rule 4): execution re-resolves the live veto guardian and
        // reverts FinalityFreezeGuardianUnset when it was cleared after scheduling
        // (StreamArtworkFinalityRegistry._requireExecutableFreeze). Mirror that gate so a freeze
        // that would revert is never previewed as ready. scopeKey mirrors the registry's
        // _scopeKey; the guardian is read live from the same authority, never the action's
        // scheduling-time snapshot.
        bytes32 scopeKey = keccak256(
            abi.encode(uint8(scope.scopeType), scope.collectionId, scope.tokenId, scope.scopeId)
        );
        (address guardian,) = governanceAuthority.terminalFreezeVetoGuardian(scopeKey);
        return guardian != address(0);
    }

    function _manifestSatisfied(StreamFinalityManifestRef calldata manifest)
        private
        view
        returns (bool)
    {
        return manifest.uriHash == keccak256(bytes(manifest.uri))
            && manifest.contentHash != bytes32(0) && manifest.schemaId != bytes32(0)
            && manifest.canonicalizationHash != bytes32(0)
            && registry.finalityManifestStored(manifest.contentHash);
    }

    function _coreAndContentRoot(StreamFinalityScope memory scope)
        private
        view
        returns (bool coreGatesSatisfied, bytes32 factsHash, bool contentRootSatisfied)
    {
        uint256 expectedLeafCount;
        bool exactLeafCount;
        if (scope.scopeType == StreamFinalityScopeType.COLLECTION) {
            StreamCoreCollectionFinalityFacts memory facts =
                coreFinalityAdapter.coreCollectionFinalityFacts(scope.collectionId);
            factsHash = registry.computeCollectionCoreFactsHash(scope.collectionId);
            coreGatesSatisfied = facts.exists
                && facts.status <= StreamFinalityDomains.CORE_COLLECTION_STATUS_CLOSED
                && facts.supplyMode
                    <= StreamFinalityDomains.CORE_COLLECTION_SUPPLY_MODE_UNCAPPED_OPEN
                && facts.status == StreamFinalityDomains.CORE_COLLECTION_STATUS_CLOSED
                && coreReads.collectionBurnsBlocked(scope.collectionId)
                && coreReads.collectionFreezeStatus(scope.collectionId);
            expectedLeafCount = facts.mintedSupply;
            exactLeafCount = true;
        } else {
            StreamScopedCoreFinalityFacts memory scopedFacts =
                coreFinalityAdapter.scopedCoreFinalityFacts(_adapterScope(scope));
            factsHash = registry.computeScopedCoreFactsHash(scope);
            coreGatesSatisfied = scopedFacts.scopeExists
                && scopedFacts.collectionStatus
                    <= StreamFinalityDomains.CORE_COLLECTION_STATUS_CLOSED
                && scopedFacts.collectionSupplyMode
                    <= StreamFinalityDomains.CORE_COLLECTION_SUPPLY_MODE_UNCAPPED_OPEN
                && scopedFacts.scopeType == uint8(scope.scopeType)
                && scopedFacts.collectionId == scope.collectionId
                && scopedFacts.tokenId == scope.tokenId && scopedFacts.scopeId == scope.scopeId;
            if (scope.scopeType == StreamFinalityScopeType.TOKEN) {
                coreGatesSatisfied = coreGatesSatisfied && scopedFacts.tokenMappingExists
                    && (scopedFacts.tokenLifecycle == StreamFinalityDomains.TOKEN_LIFECYCLE_MINTED
                        || scopedFacts.tokenLifecycle
                            == StreamFinalityDomains.TOKEN_LIFECYCLE_BURNED);
                expectedLeafCount = 1;
                exactLeafCount = true;
            }
        }
        contentRootSatisfied = _contentRootSatisfied(scope, expectedLeafCount, exactLeafCount);
    }

    function _contentRootSatisfied(
        StreamFinalityScope memory scope,
        uint256 expectedLeafCount,
        bool exactLeafCount
    ) private view returns (bool) {
        (bytes32 contentRoot, uint64 leafCount,) = metadataReads.tokenContentRoot(
            scope.collectionId, registry.contentRootScopeSubject(scope)
        );
        if (contentRoot == bytes32(0)) {
            return false;
        }
        return exactLeafCount ? uint256(leafCount) == expectedLeafCount : leafCount != 0;
    }

    function _mandatoryComponentsPresent(
        StreamFinalityComponentExpectation[] calldata components,
        uint8 metadataMode
    ) private pure returns (bool) {
        return StreamFinalityComponentSet.hasAllMandatory(components, metadataMode);
    }

    function _snapshotManifestSatisfied(uint256 collectionId, uint8 metadataMode)
        private
        view
        returns (bool)
    {
        if (metadataMode == StreamFinalityDomains.METADATA_MODE_OFFCHAIN) {
            return true;
        }
        if (
            metadataMode != StreamFinalityDomains.METADATA_MODE_ONCHAIN
                && metadataMode != StreamFinalityDomains.METADATA_MODE_HYBRID
        ) return false;
        return metadataReads.latestCollectionSnapshotHash(collectionId) != bytes32(0);
    }

    function _sanction(
        StreamFinalityScope memory scope,
        StreamFinalityComponentExpectation[] calldata components,
        bytes32 coreFactsHash,
        bytes32 nonSanctionComponentsHash,
        StreamFinalityManifestRef calldata manifest
    ) private view returns (bool satisfied, bytes32 sanctionSubjectHash) {
        sanctionSubjectHash = registry.computeSanctionSubjectHash(
            scope, coreFactsHash, nonSanctionComponentsHash, manifest
        );
        (uint256 index, uint256 occurrences) =
            StreamFinalityComponentSet.locateSanctionSlot(components);
        if (occurrences != 1) {
            return (false, sanctionSubjectHash);
        }
        bytes32 requiredType = sanctionReads.collectionSanctionComponentType(scope.collectionId);
        if (components[index].componentType != requiredType) {
            return (false, sanctionSubjectHash);
        }
        if (requiredType != StreamFinalityDomains.COMPONENT_ARTIST_SANCTION) {
            return (true, sanctionSubjectHash);
        }
        (bool valid, bytes32 sanctionRecordHash) = _sanctionVerification(scope, sanctionSubjectHash);
        return (valid && sanctionRecordHash == components[index].dataHash, sanctionSubjectHash);
    }

    function _sanctionVerification(StreamFinalityScope memory scope, bytes32 sanctionSubjectHash)
        private
        view
        returns (bool valid, bytes32 sanctionRecordHash)
    {
        (valid, sanctionRecordHash,,) = sanctionReads.verifySanctionForSubject(
            uint8(scope.scopeType),
            scope.collectionId,
            scope.tokenId,
            scope.scopeId,
            sanctionSubjectHash
        );
    }

    function _componentListWellFormed(StreamFinalityComponentExpectation[] calldata components)
        private
        view
        returns (bool)
    {
        uint256 count = components.length;
        if (count == 0 || count > registry.MAX_FINALITY_COMPONENTS()) {
            return false;
        }
        for (uint256 i = 1; i < count; i++) {
            if (!_strictlyAscending(components[i - 1], components[i])) {
                return false;
            }
        }
        return true;
    }

    function _strictlyAscending(
        StreamFinalityComponentExpectation calldata previous,
        StreamFinalityComponentExpectation calldata next
    ) private pure returns (bool) {
        if (previous.componentType != next.componentType) {
            return previous.componentType < next.componentType;
        }
        if (previous.component != next.component) {
            return previous.component < next.component;
        }
        if (previous.interfaceId != next.interfaceId) {
            return previous.interfaceId < next.interfaceId;
        }
        if (previous.codeHash != next.codeHash) {
            return previous.codeHash < next.codeHash;
        }
        if (previous.moduleVersion != next.moduleVersion) {
            return previous.moduleVersion < next.moduleVersion;
        }
        if (previous.manifestHash != next.manifestHash) {
            return previous.manifestHash < next.manifestHash;
        }
        if (previous.dataHash != next.dataHash) {
            return previous.dataHash < next.dataHash;
        }
        return false;
    }

    function _componentsMatchLive(
        StreamFinalityScope memory scope,
        StreamFinalityComponentExpectation[] calldata components
    ) private view returns (bool) {
        (uint8 failCode,) = StreamFinalityComponentSet.verifyComponentsStrict(
            components, _componentCallData(scope)
        );
        return failCode == StreamFinalityComponentSet.STRICT_OK;
    }

    function _componentCallData(StreamFinalityScope memory scope)
        private
        pure
        returns (bytes memory)
    {
        if (scope.scopeType == StreamFinalityScopeType.COLLECTION) {
            return abi.encodeWithSelector(
                IStreamArtworkFinalityComponent.finalityState.selector, scope.collectionId
            );
        }
        return abi.encodeWithSelector(
            IStreamArtworkScopedFinalityComponent.finalityStateForScope.selector, scope
        );
    }

    function _discoveryMatches(
        StreamFinalityScope memory scope,
        StreamFinalityComponentExpectation[] calldata components,
        bytes32 submittedHash
    ) private view returns (bool) {
        address discovery = finalityDiscovery;
        uint256 submittedCount = components.length;
        uint256 gasCap = 0;
        if (!_discoveryFactsMatch(discovery, scope, submittedCount, submittedHash, gasCap)) {
            return false;
        }
        for (uint256 i = 0; i < submittedCount; i++) {
            bytes memory componentCallData = _discoveryComponentCallData(scope, i);
            (
                bool componentReadable,
                StreamFinalityComponentExpectation memory discoveredComponent
            ) = StreamFinalityComponentSet.observeDiscoveryComponent(
                    discovery, componentCallData, gasCap
                );
            if (!componentReadable || !_sameExpectation(discoveredComponent, components[i])) {
                return false;
            }
        }
        return true;
    }

    function _discoveryFactsMatch(
        address discovery,
        StreamFinalityScope memory scope,
        uint256 submittedCount,
        bytes32 submittedHash,
        uint256 gasCap
    ) private view returns (bool) {
        bytes memory countCallData;
        bytes memory hashCallData;
        if (scope.scopeType == StreamFinalityScopeType.COLLECTION) {
            countCallData = abi.encodeWithSelector(
                IStreamArtworkFinalityDiscovery.finalityComponentCount.selector, scope.collectionId
            );
            hashCallData = abi.encodeWithSelector(
                IStreamArtworkFinalityDiscovery.finalityDiscoveryHash.selector, scope.collectionId
            );
        } else {
            countCallData = abi.encodeWithSelector(
                IStreamArtworkScopedFinalityDiscovery.finalityComponentCountForScope.selector, scope
            );
            hashCallData = abi.encodeWithSelector(
                IStreamArtworkScopedFinalityDiscovery.finalityDiscoveryHashForScope.selector, scope
            );
        }
        (bool countReadable, bytes32 discoveredCount) =
            StreamFinalityComponentSet.observeDiscoveryWord(discovery, countCallData, gasCap);
        if (!countReadable || uint256(discoveredCount) != submittedCount) {
            return false;
        }
        (bool hashReadable, bytes32 discoveredHash) =
            StreamFinalityComponentSet.observeDiscoveryWord(discovery, hashCallData, gasCap);
        if (!hashReadable || discoveredHash != submittedHash) {
            return false;
        }
        return true;
    }

    function _discoveryComponentCallData(StreamFinalityScope memory scope, uint256 index)
        private
        pure
        returns (bytes memory)
    {
        if (scope.scopeType == StreamFinalityScopeType.COLLECTION) {
            return abi.encodeWithSelector(
                IStreamArtworkFinalityDiscovery.finalityComponentAt.selector,
                scope.collectionId,
                index
            );
        }
        return abi.encodeWithSelector(
            IStreamArtworkScopedFinalityDiscovery.finalityComponentAtForScope.selector, scope, index
        );
    }

    function _sameExpectation(
        StreamFinalityComponentExpectation memory discovered,
        StreamFinalityComponentExpectation calldata submitted
    ) private pure returns (bool) {
        return discovered.componentType == submitted.componentType
            && discovered.component == submitted.component
            && discovered.interfaceId == submitted.interfaceId
            && discovered.codeHash == submitted.codeHash
            && discovered.moduleVersion == submitted.moduleVersion
            && discovered.manifestHash == submitted.manifestHash
            && discovered.dataHash == submitted.dataHash;
    }

    function _isCanonicalScopeShape(StreamFinalityScope memory scope) private pure returns (bool) {
        if (scope.collectionId == 0) {
            return false;
        }
        if (scope.scopeType == StreamFinalityScopeType.COLLECTION) {
            return scope.tokenId == 0 && scope.scopeId == bytes32(0);
        }
        if (scope.scopeType == StreamFinalityScopeType.TOKEN) {
            return scope.tokenId != 0 && scope.scopeId == bytes32(0);
        }
        return scope.tokenId == 0 && scope.scopeId != bytes32(0);
    }

    function _adapterScope(StreamFinalityScope memory scope)
        private
        pure
        returns (StreamCoreFinalityScopeQuery memory)
    {
        return StreamCoreFinalityScopeQuery({
            scopeType: uint8(scope.scopeType),
            collectionId: scope.collectionId,
            tokenId: scope.tokenId,
            scopeId: scope.scopeId
        });
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/finality/IStreamArtworkFinalityComponents.sol";
import "../../interfaces/stream/finality/IStreamArtworkFinalityRegistry.sol";
import "../../vendor/openzeppelin/IERC165.sol";
import "../../interfaces/stream/finality/IStreamCoreFinalityAdapter.sol";
import "../../interfaces/stream/finality/IStreamCoreFinalitySource.sol";
import "../../interfaces/stream/finality/IStreamFinalityGovernanceAuthority.sol";
import "../../interfaces/stream/finality/IStreamFinalityMetadataReads.sol";
import "../../interfaces/stream/finality/IStreamFinalitySanctionReads.sol";
import "../../interfaces/stream/finality/StreamArtworkFinalityTypes.sol";

/// @notice Five-scope artwork finality registry with the single governed terminal-freeze path.
/// @dev Implements [LTA-FINALITY] collection and scoped finality (all five scopes ship at
///      genesis per ADR 0009 decision 6), the [LTA-FREEZE] rule 4 TERMINAL_FREEZE staging with
///      a 72-hour veto floor and an independent guardian ([GOV-WINDOWS]), the
///      [CMC-FINALITY-INPUTS] execution gates this registry owns (content root, sanction,
///      burn/freeze gates), and the never-revert diagnostic reads. Consumer
///      surfaces built in parallel worktrees (Core facts, metadata satellite, artist registry,
///      governed admin registry) are bound through the narrow IStreamFinality* seams.
contract StreamArtworkFinalityRegistry is
    IStreamArtworkFinalityRegistry,
    IStreamArtworkScopedFrozenRouteRegistry
{
    error FinalityZeroAddress();
    error FinalityDependencyHasNoCode(address dependency);
    error FinalityAdapterInterfaceUnsupported(address adapter);
    error FinalityAdapterBindingMismatch(
        address expectedCore, address actualCore, address expectedMetadata, address actualMetadata
    );
    error FinalityAdapterReturnShapeInvalid(bytes4 selector, uint256 byteLength);
    error FinalityAdapterSemanticProbeInvalid(bytes4 selector);

    /// @notice Event schema version carried by every registry event.
    uint16 public constant FINALITY_EVENT_SCHEMA_VERSION = 1;

    /// @notice Component-count cap ([LTA-FINALITY] planning value, pinned at release).
    uint256 public constant MAX_FINALITY_COMPONENTS = 32;

    /// @notice Calldata cap for finality entries and staged manifest bytes (planning value).
    uint256 public constant MAX_FINALITY_CALLDATA_BYTES = 32_768;

    /// @notice Terminal-freeze veto window floor ([GOV-WINDOWS] rule 2; ADR 0011 decision R10).
    uint64 public constant TERMINAL_FREEZE_VETO_FLOOR = 72 hours;

    /// @notice Open-to-execute window floor for delayed classes ([GOV-WINDOWS] rule 1).
    uint64 public constant TERMINAL_FREEZE_EXECUTION_WINDOW_FLOOR = 7 days;

    /// @notice Per-component gas cap for the never-revert diagnostics; genesis planning value
    ///         of the FINALITY_COMPONENT_READ_GAS governed gas parameter ([LTA-GGP] seam —
    ///         the GGP host framework binds the pinned key below when it lands).
    uint256 public constant FINALITY_COMPONENT_READ_GAS = 30_000;

    /// @dev Strict reads retain enough gas to decode or emit a typed failure. Capped diagnostics
    ///      retain only the smaller reserve required for their compact false return.
    uint256 private constant FINALITY_STRICT_PARENT_GAS_RESERVE = 100_000;
    uint256 private constant FINALITY_DIAGNOSTIC_PARENT_GAS_RESERVE = 10_000;

    /// @notice Pinned GGP key for the diagnostic read budget.
    bytes32 public constant GGP_FINALITY_COMPONENT_READ_GAS_KEY =
        StreamFinalityDomains.GGP_FINALITY_COMPONENT_READ_GAS;

    IStreamCoreFinalitySource public immutable coreReads;
    IStreamCoreFinalityAdapter public immutable coreFinalityAdapter;
    IStreamFinalityMetadataReads public immutable metadataReads;
    IStreamFinalitySanctionReads public immutable sanctionReads;
    IStreamFinalityGovernanceAuthority public immutable governanceAuthority;

    /// @notice Mandatory discovery module (the metadata router).
    address public immutable finalityDiscovery;

    mapping(uint256 => StreamCollectionFinalityRecord) private _collectionRecords;
    mapping(uint256 => StreamFinalityComponentExpectation[]) private _collectionComponents;
    mapping(bytes32 => StreamScopedFinalityRecord) private _scopedRecords;
    mapping(bytes32 => StreamFinalityComponentExpectation[]) private _scopedComponents;
    mapping(bytes32 => StreamTerminalFreezeAction) private _terminalFreezes;
    mapping(bytes32 => bytes) private _manifestBytes;

    /// @dev Bundles per-execution values so deep call frames stay under stack limits.
    struct FinalityExecution {
        bytes32 scopeKey;
        bytes32 coreFactsHash;
        bytes32 componentsHash;
        bytes32 finalityRecordHash;
        uint256 expectedLeafCount;
        bool exactLeafCount;
    }

    constructor(
        address coreReads_,
        address metadataReads_,
        address coreFinalityAdapter_,
        address sanctionReads_,
        address governanceAuthority_,
        address finalityDiscovery_
    ) {
        if (
            coreReads_ == address(0) || metadataReads_ == address(0)
                || coreFinalityAdapter_ == address(0) || sanctionReads_ == address(0)
                || governanceAuthority_ == address(0) || finalityDiscovery_ == address(0)
        ) {
            revert FinalityZeroAddress();
        }
        _requireCode(coreReads_);
        _requireCode(metadataReads_);
        _requireCode(coreFinalityAdapter_);
        _requireCode(sanctionReads_);
        _requireCode(governanceAuthority_);
        _requireCode(finalityDiscovery_);
        _requireAdapter(coreFinalityAdapter_, coreReads_, metadataReads_);
        coreReads = IStreamCoreFinalitySource(coreReads_);
        metadataReads = IStreamFinalityMetadataReads(metadataReads_);
        coreFinalityAdapter = IStreamCoreFinalityAdapter(coreFinalityAdapter_);
        sanctionReads = IStreamFinalitySanctionReads(sanctionReads_);
        governanceAuthority = IStreamFinalityGovernanceAuthority(governanceAuthority_);
        finalityDiscovery = finalityDiscovery_;
    }

    function _requireCode(address dependency) private view {
        if (dependency.code.length == 0) {
            revert FinalityDependencyHasNoCode(dependency);
        }
    }

    function _requireAdapter(address adapter, address expectedCore, address expectedMetadata)
        private
        view
    {
        if (
            !_readExactInterfaceSupport(adapter, type(IERC165).interfaceId)
                || !_readExactInterfaceSupport(
                    adapter, type(IStreamCoreFinalityAdapter).interfaceId
                ) || _readExactInterfaceSupport(adapter, 0xffffffff)
        ) {
            revert FinalityAdapterInterfaceUnsupported(adapter);
        }
        address actualCore = _readExactAddress(adapter, IStreamCoreFinalityAdapter.core.selector);
        address actualMetadata =
            _readExactAddress(adapter, IStreamCoreFinalityAdapter.collectionMetadata.selector);
        if (actualCore != expectedCore || actualMetadata != expectedMetadata) {
            revert FinalityAdapterBindingMismatch(
                expectedCore, actualCore, expectedMetadata, actualMetadata
            );
        }
        bytes4 collectionSelector = IStreamCoreFinalityAdapter.coreCollectionFinalityFacts.selector;
        bytes memory collectionResult = _readExactAdapterResult(
            adapter,
            collectionSelector,
            abi.encodeWithSelector(collectionSelector, uint256(0)),
            9 * 32
        );
        _requireCanonicalCollectionProbe(collectionSelector, collectionResult);

        bytes4 scopedSelector = IStreamCoreFinalityAdapter.scopedCoreFinalityFacts.selector;
        bytes memory scopedResult = _readExactAdapterResult(
            adapter,
            scopedSelector,
            abi.encodeWithSelector(
                scopedSelector,
                StreamCoreFinalityScopeQuery({
                    scopeType: type(uint8).max, collectionId: 0, tokenId: 0, scopeId: bytes32(0)
                })
            ),
            13 * 32
        );
        _requireCanonicalInvalidScopeProbe(scopedSelector, scopedResult);
    }

    function _readExactInterfaceSupport(address adapter, bytes4 interfaceId)
        private
        view
        returns (bool supported)
    {
        (bool success,, bytes memory result) = _readExactStatic(
            adapter, abi.encodeWithSelector(IERC165.supportsInterface.selector, interfaceId), 32
        );
        if (!success) {
            revert FinalityAdapterInterfaceUnsupported(adapter);
        }
        uint256 word;
        assembly ("memory-safe") {
            word := mload(add(result, 0x20))
        }
        if (word > 1) {
            revert FinalityAdapterInterfaceUnsupported(adapter);
        }
        return word == 1;
    }

    function _readExactAddress(address adapter, bytes4 selector)
        private
        view
        returns (address value)
    {
        (bool success, uint256 actualLength, bytes memory result) =
            _readExactStatic(adapter, abi.encodeWithSelector(selector), 32);
        if (!success) {
            revert FinalityAdapterReturnShapeInvalid(selector, actualLength);
        }
        uint256 rawAddress = _adapterResultWord(result, 0);
        if (rawAddress > type(uint160).max) {
            revert FinalityAdapterSemanticProbeInvalid(selector);
        }
        value = address(uint160(rawAddress));
    }

    function _readExactAdapterResult(
        address adapter,
        bytes4 selector,
        bytes memory callData,
        uint256 expectedLength
    ) private view returns (bytes memory) {
        (bool success, uint256 actualLength, bytes memory result) =
            _readExactStatic(adapter, callData, expectedLength);
        if (!success) {
            revert FinalityAdapterReturnShapeInvalid(selector, actualLength);
        }
        return result;
    }

    /// @dev Exact fixed-buffer admission read. Returndata beyond `expectedLength` is never copied,
    ///      so an untrusted constructor dependency cannot force attacker-sized memory expansion.
    function _readExactStatic(address target, bytes memory callData, uint256 expectedLength)
        private
        view
        returns (bool readable, uint256 actualLength, bytes memory result)
    {
        result = new bytes(expectedLength);
        uint256 availableGas = gasleft();
        if (availableGas <= FINALITY_STRICT_PARENT_GAS_RESERVE) {
            return (false, 0, result);
        }
        uint256 forwardedGas = availableGas - FINALITY_STRICT_PARENT_GAS_RESERVE;
        assembly ("memory-safe") {
            readable := staticcall(
                forwardedGas,
                target,
                add(callData, 0x20),
                mload(callData),
                add(result, 0x20),
                expectedLength
            )
            actualLength := returndatasize()
            if iszero(eq(actualLength, expectedLength)) { readable := 0 }
        }
    }

    function _requireCanonicalCollectionProbe(bytes4 selector, bytes memory result) private pure {
        if (
            _adapterResultWord(result, 0) > 1 || _adapterResultWord(result, 1) > 1
                || _adapterResultWord(result, 2) > type(uint8).max
                || _adapterResultWord(result, 3) > type(uint8).max
        ) {
            revert FinalityAdapterSemanticProbeInvalid(selector);
        }
    }

    function _requireCanonicalInvalidScopeProbe(bytes4 selector, bytes memory result) private pure {
        if (_adapterResultWord(result, 0) != 0 || _adapterResultWord(result, 1) != type(uint8).max)
        {
            revert FinalityAdapterSemanticProbeInvalid(selector);
        }
        for (uint256 i = 2; i < 13; i++) {
            if (_adapterResultWord(result, i) != 0) {
                revert FinalityAdapterSemanticProbeInvalid(selector);
            }
        }
    }

    function _adapterResultWord(bytes memory result, uint256 index)
        private
        pure
        returns (uint256 word)
    {
        assembly ("memory-safe") {
            word := mload(add(add(result, 0x20), mul(index, 0x20)))
        }
    }

    /// @notice Returns true for deployment validation.
    function isStreamArtworkFinalityRegistry() external pure returns (bool) {
        return true;
    }

    /// @notice The bound Core address used in every pinned hash preimage.
    function core() public view returns (address) {
        return address(coreReads);
    }

    // ------------------------------------------------------------------
    // Terminal-freeze staging (single governed freeze path)
    // ------------------------------------------------------------------

    /// @notice Stages the irreversible artwork finality for `scope` under the TERMINAL_FREEZE
    ///         class: delay plus an independent veto guardian ([LTA-FREEZE] rule 4).
    function scheduleArtworkTerminalFreeze(
        StreamFinalityScope calldata scope,
        bytes32 expectedFinalityRecordHash,
        uint64 notBefore,
        uint64 expiresAfter
    ) external override {
        _requireFinalityAdmin(msg.sender);
        StreamFinalityScope memory scopeMem = scope;
        _requireCanonicalScopeShape(scopeMem);
        if (expectedFinalityRecordHash == bytes32(0)) {
            revert FinalityExpectedRecordHashZero();
        }
        bytes32 scopeKey = _scopeKey(scopeMem);
        if (_scopeFinalized(scopeMem)) {
            revert FinalityAlreadyFinalized(scopeKey);
        }

        StreamTerminalFreezeAction storage action = _terminalFreezes[scopeKey];
        if (action.status == StreamTerminalFreezeStatus.SCHEDULED) {
            if (block.timestamp > action.expiresAfter) {
                _expireAction(scopeKey, action);
            } else {
                revert FinalityFreezeAlreadyScheduled(scopeKey);
            }
        }

        uint64 earliestNotBefore = uint64(block.timestamp) + TERMINAL_FREEZE_VETO_FLOOR;
        if (notBefore < earliestNotBefore) {
            revert FinalityFreezeDelayTooShort(notBefore, earliestNotBefore);
        }
        uint64 earliestExpiry = notBefore + TERMINAL_FREEZE_EXECUTION_WINDOW_FLOOR;
        if (expiresAfter < earliestExpiry) {
            revert FinalityFreezeWindowTooShort(expiresAfter, earliestExpiry);
        }

        (address guardian,) = governanceAuthority.terminalFreezeVetoGuardian(scopeKey);
        if (guardian == address(0)) {
            revert FinalityFreezeGuardianUnset(scopeKey);
        }

        action.status = StreamTerminalFreezeStatus.SCHEDULED;
        action.scope = scopeMem;
        action.expectedFinalityRecordHash = expectedFinalityRecordHash;
        action.scheduledAt = uint64(block.timestamp);
        action.notBefore = notBefore;
        action.expiresAfter = expiresAfter;
        action.scheduler = msg.sender;
        action.vetoGuardianAtScheduling = guardian;

        emit ArtworkTerminalFreezeScheduled(
            FINALITY_EVENT_SCHEMA_VERSION,
            uint8(scopeMem.scopeType),
            scopeMem.collectionId,
            scopeKey,
            scopeMem.tokenId,
            scopeMem.scopeId,
            expectedFinalityRecordHash,
            notBefore,
            expiresAfter,
            guardian,
            msg.sender
        );
    }

    /// @notice Guardian veto, valid while the action is scheduled and before `notBefore`.
    /// @dev The guardian is re-resolved through the authority at veto time — a role reference,
    ///      never the frozen address captured at scheduling (ADR 0004 execution rules).
    function vetoArtworkTerminalFreeze(StreamFinalityScope calldata scope, bytes32 reasonHash)
        external
        override
    {
        bytes32 scopeKey = _scopeKey(scope);
        StreamTerminalFreezeAction storage action = _terminalFreezes[scopeKey];
        if (action.status != StreamTerminalFreezeStatus.SCHEDULED) {
            revert FinalityFreezeNotScheduled(scopeKey);
        }
        if (block.timestamp >= action.notBefore) {
            revert FinalityFreezeVetoWindowClosed(action.notBefore);
        }
        (address guardian,) = governanceAuthority.terminalFreezeVetoGuardian(scopeKey);
        if (guardian == address(0) || msg.sender != guardian) {
            revert FinalityCallerNotVetoGuardian(msg.sender, guardian);
        }
        action.status = StreamTerminalFreezeStatus.VETOED;
        emit ArtworkTerminalFreezeVetoed(
            FINALITY_EVENT_SCHEMA_VERSION,
            scopeKey,
            action.expectedFinalityRecordHash,
            reasonHash,
            msg.sender
        );
    }

    /// @notice Cancels a scheduled terminal freeze before execution ([LTA-GOV] rule 3).
    function cancelArtworkTerminalFreeze(StreamFinalityScope calldata scope, bytes32 reasonHash)
        external
        override
    {
        _requireFinalityAdmin(msg.sender);
        bytes32 scopeKey = _scopeKey(scope);
        StreamTerminalFreezeAction storage action = _terminalFreezes[scopeKey];
        if (
            action.status != StreamTerminalFreezeStatus.SCHEDULED
                || block.timestamp > action.expiresAfter
        ) {
            revert FinalityFreezeNotScheduled(scopeKey);
        }
        action.status = StreamTerminalFreezeStatus.CANCELLED;
        emit ArtworkTerminalFreezeCancelled(
            FINALITY_EVENT_SCHEMA_VERSION,
            scopeKey,
            action.expectedFinalityRecordHash,
            reasonHash,
            msg.sender
        );
    }

    /// @notice Anyone may materialize the virtual expiry of an overdue scheduled freeze.
    function materializeExpiredArtworkTerminalFreeze(StreamFinalityScope calldata scope)
        external
        override
    {
        bytes32 scopeKey = _scopeKey(scope);
        StreamTerminalFreezeAction storage action = _terminalFreezes[scopeKey];
        if (action.status != StreamTerminalFreezeStatus.SCHEDULED) {
            revert FinalityFreezeNotScheduled(scopeKey);
        }
        if (block.timestamp <= action.expiresAfter) {
            revert FinalityFreezeNotExpired(scopeKey);
        }
        _expireAction(scopeKey, action);
    }

    /// @notice Stored staged action; a virtually expired action reports SCHEDULED until
    ///         materialized, matching the [GOV-WINDOWS] virtual-expiry model.
    function artworkTerminalFreezeAction(StreamFinalityScope calldata scope)
        external
        view
        override
        returns (StreamTerminalFreezeAction memory)
    {
        return _terminalFreezes[_scopeKey(scope)];
    }

    /// @inheritdoc IStreamArtworkFinalityRegistry
    function artworkFreezeMode(StreamFinalityScope calldata scope)
        external
        view
        override
        returns (StreamArtworkFreezeMode)
    {
        StreamFinalityScope memory scopeMem = scope;
        if (scopeMem.scopeType == StreamFinalityScopeType.COLLECTION) {
            if (
                _collectionRecords[scopeMem.collectionId].finalized
                    && _isCanonicalScopeShape(scopeMem)
            ) {
                return StreamArtworkFreezeMode.INHERITED;
            }
            return StreamArtworkFreezeMode.NONE;
        }
        if (_scopedRecords[_scopeKey(scopeMem)].finalized) {
            return StreamArtworkFreezeMode.EXACT;
        }
        if (_collectionRecords[scopeMem.collectionId].finalized) {
            return StreamArtworkFreezeMode.INHERITED;
        }
        return StreamArtworkFreezeMode.NONE;
    }

    // ------------------------------------------------------------------
    // Manifest byte staging ([LTA-FINALITY] requirement 14)
    // ------------------------------------------------------------------

    /// @notice Stages canonical manifest bytes in registry storage, content-addressed by their
    ///         keccak256 hash; idempotent for already-staged content.
    function stageFinalityManifest(bytes calldata manifestBytes)
        external
        override
        returns (bytes32 contentHash)
    {
        uint256 byteLength = manifestBytes.length;
        if (byteLength == 0 || byteLength > MAX_FINALITY_CALLDATA_BYTES) {
            revert FinalityManifestBytesInvalid();
        }
        contentHash = keccak256(manifestBytes);
        if (_manifestBytes[contentHash].length == 0) {
            _manifestBytes[contentHash] = manifestBytes;
            emit FinalityManifestStaged(
                FINALITY_EVENT_SCHEMA_VERSION, contentHash, byteLength, msg.sender
            );
        }
    }

    /// @inheritdoc IStreamArtworkFinalityRegistry
    function finalityManifestStored(bytes32 contentHash) external view override returns (bool) {
        return _manifestBytes[contentHash].length != 0;
    }

    /// @inheritdoc IStreamArtworkFinalityRegistry
    function finalityManifestBytes(bytes32 contentHash)
        external
        view
        override
        returns (bytes memory)
    {
        return _manifestBytes[contentHash];
    }

    // ------------------------------------------------------------------
    // Finality execution
    // ------------------------------------------------------------------

    /// @inheritdoc IStreamArtworkFinalityRegistry
    function finalizeCollectionArtwork(
        uint256 collectionId,
        StreamFinalityComponentExpectation[] calldata components,
        bytes32 expectedFinalityRecordHash,
        StreamFinalityManifestRef calldata manifest
    ) external override {
        _finalize(_collectionScope(collectionId), components, expectedFinalityRecordHash, manifest);
    }

    /// @inheritdoc IStreamArtworkFinalityRegistry
    function finalizeArtworkScope(
        StreamFinalityScope calldata scope,
        StreamFinalityComponentExpectation[] calldata components,
        bytes32 expectedFinalityRecordHash,
        StreamFinalityManifestRef calldata manifest
    ) external override {
        if (scope.scopeType == StreamFinalityScopeType.COLLECTION) {
            revert FinalityScopeUsesCollectionEntry();
        }
        _finalize(scope, components, expectedFinalityRecordHash, manifest);
    }

    function _finalize(
        StreamFinalityScope memory scope,
        StreamFinalityComponentExpectation[] calldata components,
        bytes32 expectedFinalityRecordHash,
        StreamFinalityManifestRef calldata manifest
    ) private {
        if (msg.data.length > MAX_FINALITY_CALLDATA_BYTES) {
            revert FinalityCalldataTooLarge(msg.data.length, MAX_FINALITY_CALLDATA_BYTES);
        }
        _requireFinalityAdmin(msg.sender);
        _requireCanonicalScopeShape(scope);

        FinalityExecution memory ctx;
        ctx.scopeKey = _scopeKey(scope);
        if (_scopeFinalized(scope)) {
            revert FinalityAlreadyFinalized(ctx.scopeKey);
        }

        StreamTerminalFreezeAction storage action = _terminalFreezes[ctx.scopeKey];
        _requireExecutableFreeze(action, ctx.scopeKey, expectedFinalityRecordHash);

        _requireComponentListWellFormed(components);
        _requireManifestValid(manifest);

        uint8 metadataMode = metadataReads.collectionMetadataMode(scope.collectionId);
        if (metadataMode > StreamFinalityDomains.METADATA_MODE_HYBRID) {
            revert FinalityMetadataModeInvalid(metadataMode);
        }
        _requireSnapshotManifestForScriptWorks(scope.collectionId, metadataMode);

        (ctx.coreFactsHash, ctx.expectedLeafCount, ctx.exactLeafCount) =
            _verifyCoreGatesAndFacts(scope);
        _verifyContentRoot(scope, ctx.expectedLeafCount, ctx.exactLeafCount);
        ctx.componentsHash = _componentsHash(components);
        _requireMandatoryComponents(components, metadataMode);
        _verifySanctionComponent(scope, components, ctx.coreFactsHash, manifest);
        _verifyComponentsLiveStrict(components, _componentCallData(scope));
        _verifyDiscovery(scope, components, ctx.componentsHash);

        ctx.finalityRecordHash =
            _finalityRecordHash(scope, ctx.coreFactsHash, ctx.componentsHash, manifest);
        if (ctx.finalityRecordHash != expectedFinalityRecordHash) {
            revert FinalityExpectedRecordHashMismatch(
                expectedFinalityRecordHash, ctx.finalityRecordHash
            );
        }

        action.status = StreamTerminalFreezeStatus.EXECUTED;
        _storeRecordAndEmit(scope, ctx, components, manifest);
    }

