        }
        if (requiredType != StreamFinalityDomains.COMPONENT_ARTIST_SANCTION) {
            return;
        }
        _requireVerifiedSanction(
            scope,
            _sanctionSubjectHash(
                scope, coreFactsHash, _nonSanctionComponentsHash(components), manifest
            ),
