        if (governed) {
            emit SystemManifestTailTriggerRegistered(
                SCHEMA_VERSION,
                triggerTarget,
                triggerSelector,
                triggerCodeHash,
                allowedActionClassMask,
                _manifest.systemManifestSatellite,
                SYSTEM_MANIFEST_PUBLISH_SELECTOR,
                _currentActionId
            );
        }
    }

    function _validateManifestTailComposition(
        bytes32 actionId,
        address proposer,
        uint8 actionClass,
        GovernanceCall[] memory calls,
        bool bootstrapScoped,
        bool scheduling,
        bool privilegedProposer
    ) private {
        StreamGovernanceManifest.validateManifestTailComposition(
            _policy,
            _admin,
            _manifest,
            actionId,
            proposer,
            actionClass,
            calls,
            bootstrapScoped,
            scheduling,
            privilegedProposer,
            this.sealSystemManifestBootstrap.selector,
            this.registerSystemManifestTailTrigger.selector
        );
    }

    function _requireBootstrapCodeHashes() private view {
        StreamGovernanceManifest.requireBootstrapCodeHashes(_manifest);
    }

    function _requireGovernanceRootCodeHash() private view {
        StreamGovernanceManifest.requireGovernanceRootCodeHash(_manifest);
    }

    function _requireBoundRoleRegistry() private view {
        StreamGovernanceManifest.requireBoundRoleRegistry(_manifest);
    }

    function _pruneLiveTerminalFreeze(bytes32 actionId, uint8 actionClass) private {
        if (actionClass == StreamGovernanceActionClasses.TERMINAL_FREEZE) {
            StreamGovernanceBootstrap.pruneTerminalFreeze(_policy, actionId);
        }
    }

    /// @dev Emits `GovernanceActionScheduled` via `log4`. Non-indexed data is
    ///     ABI-encoded in word chunks: 14 head words (the string head slot at
    ///     index 13 points to offset 0x1C0), then the string length, raw
    ///     bytes, and canonical zero padding.
    function _execute(bytes32 actionId, GovernanceCall[] memory calls, bytes[] memory callDatas)
        private
    {
        uint256 startBalance = address(this).balance;
        GovernanceAction storage action = _actions[actionId];
        (uint256 totalValue, bytes[] memory scheduledCallDatas, bytes32 currentCatalogHash) = StreamGovernanceBootstrap.validateExecution(
            _policy,
            _actionPolicy,
            action,
            StreamGovernanceBootstrap.ExecutionValidationContext({
                actionId: actionId,
                nonce: _actionNonces[actionId],
                callDataPointer: _callDataPointers[actionId],
                scheduledCatalogHash: _actionPolicyCatalogHashes[actionId],
                roleRegistry: address(_manifest.roleRegistry),
                systemManifestSatellite: _manifest.systemManifestSatellite,
                sealSelector: this.sealSystemManifestBootstrap.selector
            }),
            calls,
            callDatas
        );
        bool bootstrapSeal = !_manifest.isSealed && calls.length == 2
            && calls[0].target == address(this)
            && calls[0].selector == this.sealSystemManifestBootstrap.selector;
        _validateManifestTailComposition(
            actionId, action.proposer, action.actionClass, calls, !_manifest.isSealed, false, false
        );
        StreamGovernanceActionPolicy.validateCalls(
            _actionPolicy,
            _manifest.actionPolicyCandidateProfileHash,
            _manifest.actionPolicyCatalogHash,
            _manifest.actionPolicyEntryCount,
            action.actionClass,
            calls,
            scheduledCallDatas
        );
        if (!_manifest.isSealed && action.proposer != genesisBootstrapAuthority) {
            revert GenesisBootstrapActorRequired(action.proposer);
        }
        if (!_manifest.isSealed) {
            _requireBootstrapCodeHashes();
        } else {
            _requireGovernanceRootCodeHash();
        }
        if (action.actionClass == StreamGovernanceActionClasses.TERMINAL_FREEZE) {
            _requireBoundRoleRegistry();
            StreamGovernanceBootstrap.validateTerminalFreezeGuardians(_manifest.roleRegistry, calls);
            bytes32 expectedCommitment = _terminalFreezeGuardianConfigCommitments[actionId];
            bytes32 actualCommitment = StreamGovernancePolicy.terminalFreezeGuardianConfigCommitment(
                _manifest.roleRegistry, calls
            );
            if (actualCommitment != expectedCommitment) {
                revert TerminalFreezeGuardianConfigDrift(
                    actionId, expectedCommitment, actualCommitment
                );
            }
        }
        // [GOV-BATCH] rule 2: msg.value equals the exact batch value sum.
        if (msg.value != totalValue) {
            revert BatchValueMismatch(totalValue, msg.value);
        }

        action.status = GovernanceActionStatus.EXECUTED;
        action.executor = msg.sender;
        _pruneLiveTerminalFreeze(actionId, action.actionClass);
        _executing = true;
        _currentActionId = actionId;
        _currentActionClass = action.actionClass;
        _currentBatchLength = calls.length;

        // Governed targets observe these values through currentAction() during
        // each call. Clearing them immediately afterward is the security
        // boundary, not a redundant write.
        // slither-disable-start write-after-write
        for (uint256 i = 0; i < calls.length; i++) {
            _currentCallIndex = i;
            _currentScopeHash = calls[i].scopeHash;
            _currentOldValueHash = calls[i].oldValueHash;
            _currentNewValueHash = calls[i].newValueHash;
            StreamGovernanceBootstrap.executeCall(_policy, actionId, i, calls[i], callDatas[i]);
            _currentScopeHash = bytes32(0);
            _currentOldValueHash = bytes32(0);
            _currentNewValueHash = bytes32(0);
        }
        // slither-disable-end write-after-write

        if (bootstrapSeal) {
            emit SystemManifestBootstrapSealed(
                SCHEMA_VERSION,
                _manifest.bootstrapTriggerSetHash,
                _manifest.expectedTriggerCount,
                _manifest.sealedPayloadPointer,
                _manifest.expectedManifestHash,
                actionId
            );
        }

        _executing = false;
        _currentActionId = bytes32(0);
        _currentActionClass = 0;
        _currentBatchLength = 0;
        _currentCallIndex = 0;
        _pendingScheduledActionCount -= 1;

        // [GOV-BATCH] rule 2: refunded surplus reverts the batch rather than
        // stranding value in the governance contract.
        uint256 expectedBalance = startBalance - totalValue;
        if (address(this).balance != expectedBalance) {
            revert BatchValueSurplus(address(this).balance - expectedBalance);
        }

        emit GovernanceActionExecuted(
            SCHEMA_VERSION,
            actionId,
            action.actionClass,
            action.target,
            action.value,
            action.selector,
            action.callHash,
            action.scopeHash,
            action.oldValueHash,
            action.newValueHash,
            msg.sender,
            action.manifestHash
        );
        emit GovernanceActionPolicyValidated(
            SCHEMA_VERSION, actionId, 2, _actionPolicy.candidateProfileHash, currentCatalogHash
        );
    }

    function _firstSelector(bytes memory callData) private pure returns (bytes4 selector) {
        assembly ("memory-safe") {
            selector := mload(add(callData, 0x20))
        }
    }

    function _callsHash(GovernanceCall[] memory calls) private pure returns (bytes32) {
        return StreamGovernanceBootstrap.governanceCallsHash(calls);
    }

    function _deriveBatchTransitionHashes(GovernanceCall[] memory calls, bytes32 callsHash)
        private
        pure
        returns (bytes32 scopeHash, bytes32 oldValueHash, bytes32 newValueHash)
    {
        (scopeHash, oldValueHash, newValueHash) =
            StreamGovernanceBootstrap.deriveBatchTransitionHashes(calls, callsHash);
    }

    function _bytesEqual(bytes memory left, bytes memory right) private pure returns (bool equal) {
        return StreamGovernanceBootstrap.bytesEqual(left, right);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/governance/IStreamGovernanceExecutor.sol";
import "../../interfaces/stream/modules/IStreamModuleRegistry.sol";
import "../../interfaces/stream/governance/IStreamRoleRegistry.sol";
import "./StreamGovernanceBootstrap.sol";
import "./StreamGovernanceActionPolicy.sol";
import "./StreamGovernanceEvidence.sol";
import "./StreamGovernancePolicy.sol";
import "./StreamRoles.sol";

/// @notice Linked lifecycle and evidence library for the one-way system-manifest
///         bootstrap. Public functions execute by DELEGATECALL, preserving the
///         Executor as `address(this)` and keeping all lifecycle state in one
///         compiler-managed storage struct.
library StreamGovernanceManifest {
    bytes32 private constant SYSTEM_MANIFEST_BOOTSTRAP_SCOPE_V1 =
        0xace275f08856e822491961304b01cdc9423d7d16c05518327353df5cd02e33f8;
    bytes32 private constant SYSTEM_MANIFEST_BOOTSTRAP_STATE_V2 =
        keccak256("6529STREAM_SYSTEM_MANIFEST_BOOTSTRAP_STATE_V2");
    bytes32 private constant SYSTEM_MANIFEST_BOOTSTRAP_TRIGGER_V1 =
        0x9927dc0a368efe3d99880bb180d83938664a29ad399291c4544e4cab70c84548;
    bytes4 private constant MANIFEST_PUBLISH_SELECTOR = 0x09b1b5c6;
    bytes4 private constant MANIFEST_PUBLICATION_COUNT_SELECTOR = 0x5b1e1cba;
    bytes4 private constant REGISTER_ROLE_MANAGER_SELECTOR =
        IStreamRoleRegistry.registerRoleManager.selector;
    uint256 private constant BOOTSTRAP_STATE_WORDS = 29;
    uint256 private constant BOOTSTRAP_STATE_BYTES = BOOTSTRAP_STATE_WORDS * 32;

    struct LifecycleState {
        bool bound;
        bool isSealed;
        IStreamRoleRegistry roleRegistry;
        bytes32 roleRegistryCodeHash;
        address governanceRoot;
        bytes32 governanceRootCodeHash;
        uint64 governanceRootRevision;
        address[] initialTerminalFreezeVetoGuardians;
        bytes32 initialGuardianSetHash;
        bytes32 initialTerminalRoleMutationChain;
        uint64 initialTerminalRoleMutationRevision;
        address core;
        bytes32 coreCodeHash;
        address systemManifestSatellite;
        bytes32 systemManifestSatelliteCodeHash;
        bytes32 bootstrapTriggerSetHash;
        bytes32 expectedTriggerSetHash;
        uint256 expectedTriggerCount;
        bytes32 expectedManifestHash;
        bytes32 expectedInventoryStateRoot;
        uint256 expectedInventoryLeafCount;
        address sealedPayloadPointer;
        bytes32 actionPolicyCandidateProfileHash;
        bytes32 actionPolicyCatalogHash;
        uint256 actionPolicyEntryCount;
        bytes32[] pointerTypes;
        address[] registries;
        bytes32[] registryCodeHashes;
        mapping(bytes32 => uint64) controlPlaneActionRootRevisions;
    }

    struct BootstrapStateView {
        bool bound;
        bool isSealed;
        address roleRegistry;
        bytes32 roleRegistryCodeHash;
        address governanceRoot;
        bytes32 governanceRootCodeHash;
        uint64 governanceRootRevision;
        bytes32 initialGuardianSetHash;
        uint256 initialGuardianCount;
        bytes32 terminalFreezeVetoMutationChain;
        uint64 terminalFreezeVetoMutationRevision;
        address core;
        bytes32 coreCodeHash;
        address systemManifestSatellite;
        bytes32 systemManifestSatelliteCodeHash;
        bytes32 triggerSetHash;
        uint256 triggerCount;
        bytes32 expectedTriggerSetHash;
        uint256 expectedTriggerCount;
        bytes32 expectedManifestHash;
        bytes32 expectedInventoryStateRoot;
        uint256 expectedInventoryLeafCount;
        bytes32 inventoryStateRoot;
        uint256 inventoryLeafCount;
        address bootstrapAuthority;
        address sealedPayloadPointer;
        bytes32 actionPolicyCandidateProfileHash;
        bytes32 actionPolicyCatalogHash;
        uint256 actionPolicyEntryCount;
    }

    struct BindContext {
        address genesisBootstrapAuthority;
        uint256 governanceNonce;
        uint256 pendingScheduledActionCount;
    }

    struct SealContext {
        bool executing;
        bytes32 actionId;
        uint8 actionClass;
        uint256 batchLength;
        uint256 callIndex;
        uint256 pendingScheduledActionCount;
        address actionProposer;
        address callDataPointer;
        bytes32 scopeHash;
        bytes32 oldValueHash;
        bytes32 newValueHash;
        address genesisBootstrapAuthority;
    }

    event SystemManifestBootstrapBound(
        uint16 schemaVersion,
        address indexed core,
        address indexed systemManifestSatellite,
        bytes32 coreCodeHash,
        bytes32 systemManifestSatelliteCodeHash,
        bytes32 indexed expectedManifestHash,
        bytes32 expectedInventoryStateRoot,
        bytes32 expectedTriggerSetHash,
        uint256 triggerCount,
        address genesisBootstrapAuthority,
        address roleRegistry,
        bytes32 roleRegistryCodeHash,
        address governanceRoot,
        bytes32 governanceRootCodeHash,
        bytes32 initialGuardianSetHash,
        uint256 initialGuardianCount,
        bytes32 terminalFreezeVetoMutationChain,
        uint64 terminalFreezeVetoMutationRevision
    );

    function bind(
        LifecycleState storage state,
        StreamGovernanceBootstrap.PolicyState storage policy,
        StreamGovernanceActionPolicy.State storage actionPolicy,
        SystemManifestBootstrapBinding calldata binding,
        BindContext memory ctx
    ) public {
        if (msg.sender != ctx.genesisBootstrapAuthority) {
            revert IStreamGovernanceExecutor.GenesisBootstrapActorRequired(msg.sender);
        }
        if (state.bound) {
            revert IStreamGovernanceExecutor.SystemManifestBootstrapAlreadyBound();
        }
        if (
            state.isSealed || ctx.governanceNonce != 0 || ctx.pendingScheduledActionCount != 0
                || policy.tailEntries.length != 0
        ) {
            revert IStreamGovernanceExecutor.InvalidSystemManifestBootstrap();
        }
        _validateBootstrapBinding(binding, ctx.genesisBootstrapAuthority);
        StreamGovernanceActionPolicy.bind(
            actionPolicy,
            binding.actionPolicyCandidateProfileHash,
            binding.expectedActionPolicyCatalogHash,
            binding.actionPolicies
        );
        state.actionPolicyCandidateProfileHash = actionPolicy.candidateProfileHash;
        state.actionPolicyCatalogHash = actionPolicy.catalogHash;
        state.actionPolicyEntryCount = actionPolicy.entries.length;

        state.roleRegistry = IStreamRoleRegistry(binding.roleRegistry);
        state.roleRegistryCodeHash = binding.roleRegistry.codehash;
        state.governanceRoot = binding.governanceRoot;
        state.governanceRootCodeHash = binding.governanceRootCodeHash;
        state.governanceRootRevision = 1;
        for (uint256 i = 0; i < binding.initialTerminalFreezeVetoGuardians.length; i++) {
            address guardian = binding.initialTerminalFreezeVetoGuardians[i];
            state.initialTerminalFreezeVetoGuardians.push(guardian);
            state.roleRegistry.grantRole(StreamRoles.ROLE_TERMINAL_FREEZE_VETO, guardian);
        }
        if (!state.roleRegistry.isRoleRedundant(StreamRoles.ROLE_TERMINAL_FREEZE_VETO)) {
            revert IStreamGovernanceExecutor.InvalidSystemManifestBootstrap();
        }
        (state.initialTerminalRoleMutationChain, state.initialTerminalRoleMutationRevision) =
            state.roleRegistry.roleMutationState(StreamRoles.ROLE_TERMINAL_FREEZE_VETO);
        if (
            state.roleRegistry.roleHolderCount(StreamRoles.ROLE_TERMINAL_FREEZE_VETO)
                    != binding.initialTerminalFreezeVetoGuardians.length
                || state.initialTerminalRoleMutationRevision
                    != binding.initialTerminalFreezeVetoGuardians.length
        ) revert IStreamGovernanceExecutor.InvalidSystemManifestBootstrap();
        state.initialGuardianSetHash = StreamGovernancePolicy.initialTerminalGuardianSetHash(
            binding.roleRegistry,
            binding.initialTerminalFreezeVetoGuardians,
            state.initialTerminalRoleMutationChain,
            state.initialTerminalRoleMutationRevision
        );
        state.core = binding.core;
        state.coreCodeHash = binding.core.codehash;
        state.systemManifestSatellite = binding.systemManifestSatellite;
        state.systemManifestSatelliteCodeHash = binding.systemManifestSatellite.codehash;
        state.expectedManifestHash = binding.expectedManifestHash;
        state.expectedInventoryStateRoot = binding.expectedInventoryStateRoot;
        state.expectedInventoryLeafCount = binding.expectedInventoryLeafCount;

        bytes32 triggerSetHash = bytes32(0);
        for (uint256 i = 0; i < binding.expectedTriggers.length; i++) {
            SystemManifestBootstrapTriggerExpectation calldata expected =
                binding.expectedTriggers[i];
            StreamGovernanceBootstrap.appendManifestTailTrigger(
                policy,
                expected.triggerTarget,
                expected.triggerSelector,
                expected.triggerCodeHash,
                expected.allowedActionClassMask,
                binding.systemManifestSatellite,
                state.systemManifestSatelliteCodeHash,
                false,
                bytes32(0),
                bytes32(0),
                bytes32(0)
            );
            triggerSetHash = keccak256(
                abi.encode(
                    SYSTEM_MANIFEST_BOOTSTRAP_TRIGGER_V1,
                    triggerSetHash,
                    expected.triggerTarget,
                    expected.triggerSelector,
                    expected.triggerCodeHash,
                    expected.allowedActionClassMask
                )
            );
        }
        state.bootstrapTriggerSetHash = triggerSetHash;
        state.expectedTriggerSetHash = triggerSetHash;
        state.expectedTriggerCount = binding.expectedTriggers.length;
        for (uint256 i = 0; i < binding.pointerTypes.length; i++) {
            state.pointerTypes.push(binding.pointerTypes[i]);
        }
        for (uint256 i = 0; i < binding.registries.length; i++) {
            state.registries.push(binding.registries[i]);
            state.registryCodeHashes.push(binding.registries[i].codehash);
        }
        // The Executor's nonReentrant bind wrapper protects the external grant
        // phase; keep `bound` false until that phase is complete so callbacks
        // cannot publish or schedule against partial lifecycle state.
        state.bound = true;
        requireBootstrapCodeHashes(state);
        computeInventoryState(state);

        emit SystemManifestBootstrapBound(
            1,
            state.core,
            state.systemManifestSatellite,
            state.coreCodeHash,
            state.systemManifestSatelliteCodeHash,
            state.expectedManifestHash,
            state.expectedInventoryStateRoot,
            triggerSetHash,
            state.expectedTriggerCount,
            ctx.genesisBootstrapAuthority,
            address(state.roleRegistry),
            state.roleRegistryCodeHash,
            state.governanceRoot,
            state.governanceRootCodeHash,
            state.initialGuardianSetHash,
            state.initialTerminalFreezeVetoGuardians.length,
            state.initialTerminalRoleMutationChain,
            state.initialTerminalRoleMutationRevision
        );
    }

    function prepareSeal(
        LifecycleState storage state,
        StreamGovernanceBootstrap.PolicyState storage policy,
        SealContext memory ctx
    ) public returns (address governanceRoot) {
        if (
            msg.sender != address(this) || !ctx.executing || ctx.actionId == bytes32(0)
                || ctx.actionClass != StreamGovernanceActionClasses.POINTER_REPLACEMENT
        ) {
            revert IStreamGovernanceExecutor.GovernanceSelfCallContextRequired();
        }
        if (!state.bound) revert IStreamGovernanceExecutor.SystemManifestBootstrapNotBound();
        if (state.isSealed) {
            revert IStreamGovernanceExecutor.SystemManifestBootstrapAlreadySealed();
        }
        if (ctx.batchLength != 2 || ctx.callIndex != 0 || ctx.pendingScheduledActionCount != 1) {
            revert IStreamGovernanceExecutor.BootstrapActionNotPermitted();
        }
        if (ctx.actionProposer != ctx.genesisBootstrapAuthority) {
            revert IStreamGovernanceExecutor.GenesisBootstrapActorRequired(ctx.actionProposer);
        }
        _verifyBootstrapTriggerSet(state, policy);
        requireBootstrapCodeHashes(state);
        _requireBootstrapRoleState(state);
        bytes32[] memory pointerTypes = state.pointerTypes;
        address[] memory registries = state.registries;
        (bytes32 currentRoot, uint256 currentCount) = StreamGovernanceEvidence.computeAndValidateSealInventory(
            state.core,
            pointerTypes,
            registries,
            state.systemManifestSatellite,
            state.expectedInventoryLeafCount
        );
        if (
            currentRoot != state.expectedInventoryStateRoot
                || currentCount != state.expectedInventoryLeafCount
        ) revert IStreamGovernanceExecutor.InvalidSystemManifestBootstrap();

        bytes[] memory callDatas =
            StreamGovernanceBootstrap.readCanonicalCallDatas(ctx.callDataPointer);
        (address payloadPointer, StreamGovernanceEvidence.ManifestUpdate memory update) =
            StreamGovernanceEvidence.decodeManifestPublication(callDatas[1]);
        if (payloadPointer == address(0) || update.manifestHash != state.expectedManifestHash) {
            revert IStreamGovernanceExecutor.InvalidManifestTail();
        }
        StreamGovernanceEvidence.verifyManifestPayload(payloadPointer, update.manifestHash);
        if (_readManifestPublicationCount(state.systemManifestSatellite) != 0) {
            revert IStreamGovernanceExecutor.InvalidSystemManifestBootstrap();
        }
        bytes32 scopeHash = _bootstrapScopeHash();
        bytes32 oldStateHash = _bootstrapStateHash(
            state, ctx.genesisBootstrapAuthority, false, address(0), currentRoot, currentCount
        );
        bytes32 newStateHash = _bootstrapStateHash(
            state, ctx.genesisBootstrapAuthority, true, payloadPointer, currentRoot, currentCount
        );
        if (
            ctx.scopeHash != scopeHash || ctx.oldValueHash != oldStateHash
                || ctx.newValueHash != newStateHash
        ) revert IStreamGovernanceExecutor.GovernanceTransitionContextMismatch();
        state.isSealed = true;
        state.sealedPayloadPointer = payloadPointer;
        return state.governanceRoot;
    }

    function encodeBootstrapState(LifecycleState storage state, address genesisBootstrapAuthority)
        public
        view
        returns (bytes memory encoded)
    {
        bytes32 inventoryStateRoot;
        uint256 inventoryLeafCount;
        if (state.isSealed) {
            inventoryStateRoot = state.expectedInventoryStateRoot;
            inventoryLeafCount = state.expectedInventoryLeafCount;
        } else if (state.bound) {
            (inventoryStateRoot, inventoryLeafCount) = computeInventoryState(state);
        }
        BootstrapStateView memory stateView = _stateView(
            state,
            genesisBootstrapAuthority,
            state.isSealed,
            state.sealedPayloadPointer,
            inventoryStateRoot,
            inventoryLeafCount
        );
        if (abi.encode(stateView).length != BOOTSTRAP_STATE_BYTES) {
            revert IStreamGovernanceExecutor.InvalidSystemManifestBootstrap();
        }
        uint256 bootstrapStateBytes = BOOTSTRAP_STATE_BYTES;
        encoded = new bytes(bootstrapStateBytes);
        assembly ("memory-safe") {
            let source := stateView
            let destination := add(encoded, 0x20)
            for { let offset := 0 } lt(offset, bootstrapStateBytes) {
                offset := add(offset, 0x20)
            } {
                mstore(add(destination, offset), mload(add(source, offset)))
            }
        }
    }

    function appendManifestTailTrigger(
        StreamGovernanceBootstrap.PolicyState storage policy,
        LifecycleState storage state,
        address triggerTarget,
        bytes4 triggerSelector,
        bytes32 triggerCodeHash,
        uint8 allowedActionClassMask,
        bool governed,
        bytes32 currentScopeHash,
        bytes32 currentOldValueHash,
        bytes32 currentNewValueHash
    ) public {
        StreamGovernanceBootstrap.appendManifestTailTrigger(
            policy,
            triggerTarget,
            triggerSelector,
            triggerCodeHash,
            allowedActionClassMask,
            state.systemManifestSatellite,
            state.systemManifestSatelliteCodeHash,
            governed,
            currentScopeHash,
            currentOldValueHash,
            currentNewValueHash
        );
    }

    function extendActionPolicy(
        LifecycleState storage state,
        StreamGovernanceActionPolicy.State storage actionPolicy,
        uint64 expectedRevision,
        bytes32 expectedOldCatalogHash,
        bytes32 expectedNewCatalogHash,
        GovernanceActionPolicyEntry[] calldata additions,
        bytes32 currentScopeHash,
        bytes32 currentOldValueHash,
        bytes32 currentNewValueHash
    ) public {
        if (!state.isSealed) {
            revert IStreamGovernanceExecutor.SystemManifestBootstrapNotSealed();
        }
        StreamGovernanceActionPolicy.extend(
            actionPolicy,
            expectedRevision,
            expectedOldCatalogHash,
            expectedNewCatalogHash,
            additions,
            currentScopeHash,
            currentOldValueHash,
            currentNewValueHash
        );
        // These are the current policy commitments read by scheduling/execution;
        // the original genesis commitment remains in its binding and seal events.
        state.actionPolicyCatalogHash = actionPolicy.catalogHash;
        state.actionPolicyEntryCount = actionPolicy.entries.length;
    }

    function validateManifestTailComposition(
        StreamGovernanceBootstrap.PolicyState storage policy,
        StreamGovernancePolicy.AdminState storage admin,
        LifecycleState storage state,
        bytes32 actionId,
        address proposer,
        uint8 actionClass,
        GovernanceCall[] memory calls,
        bool bootstrapScoped,
        bool scheduling,
        bool privilegedProposer,
        bytes4 sealSelector,
        bytes4 registerTailSelector
    ) public {
        bool controlPlaneAction = _validateControlPlaneAuthority(
            state, proposer, actionClass, calls, sealSelector
        );
        StreamGovernanceBootstrap.validateManifestTailComposition(
            policy,
            actionClass,
            calls,
            bootstrapScoped,
            state.core,
            state.coreCodeHash,
            state.systemManifestSatellite,
            state.systemManifestSatelliteCodeHash,
            sealSelector,
            registerTailSelector
        );
        if (scheduling) {
            _snapshotControlPlaneRootRevision(state, actionId, controlPlaneAction);
            StreamGovernancePolicy.snapshotActionProposerRevision(
                admin, actionId, proposer, privilegedProposer
            );
        } else {
            if (controlPlaneAction) _requireControlPlaneRootRevision(state, actionId);
            StreamGovernancePolicy.requireActionProposerRevision(admin, actionId, proposer);
        }
    }

    /// @dev Scans the complete batch before the manifest-tail validator can
    ///      take any bootstrap-specific early return. Executor control calls
    ///      are root-only after the one-way seal exception expires, and every
    ///      RoleRegistry calls are root-only. Ordinary role mutations and
    ///      manager enablement are delayed; the calldata-classified manager
    ///      disable path is the sole immediate tightening exception.
    function _validateControlPlaneAuthority(
        LifecycleState storage state,
        address proposer,
        uint8 actionClass,
        GovernanceCall[] memory calls,
        bytes4 bootstrapSealSelector
    ) private view returns (bool controlPlaneAction) {
        for (uint256 i = 0; i < calls.length; i++) {
            GovernanceCall memory call_ = calls[i];
            bool executorControl = call_.target == address(this)
                && (state.isSealed || call_.selector != bootstrapSealSelector);
            bool roleRegistryControl = call_.target == address(state.roleRegistry);
            if (!executorControl && !roleRegistryControl) continue;
            controlPlaneAction = true;
            if (roleRegistryControl) {
                bytes32 actualRoleRegistryCodeHash = call_.target.codehash;
                if (actualRoleRegistryCodeHash != state.roleRegistryCodeHash) {
                    revert IStreamGovernanceExecutor.RoleRegistryCodeHashMismatch(
                        state.roleRegistryCodeHash, actualRoleRegistryCodeHash
                    );
                }
            }
            if (proposer != state.governanceRoot) {
                revert IStreamGovernanceExecutor.GovernanceRootProposerRequired(
                    proposer, state.governanceRoot, call_.target, call_.selector
                );
            }
            bool immediateManagerDisable = roleRegistryControl
                && call_.selector == REGISTER_ROLE_MANAGER_SELECTOR
                && actionClass == StreamGovernanceActionClasses.IMMEDIATE_TIGHTENING;
            if (
                roleRegistryControl && !immediateManagerDisable
                    && actionClass != StreamGovernanceActionClasses.DELAYED_LOOSENING
            ) {
                revert IStreamGovernanceExecutor.RoleRegistryDelayedActionRequired(actionClass);
            }
        }
    }

    function _snapshotControlPlaneRootRevision(
        LifecycleState storage state,
        bytes32 actionId,
        bool controlPlaneAction
    ) private {
        if (controlPlaneAction) {
            state.controlPlaneActionRootRevisions[actionId] = state.governanceRootRevision;
        }
    }

    function _requireControlPlaneRootRevision(LifecycleState storage state, bytes32 actionId)
        private
        view
    {
        uint64 expected = state.controlPlaneActionRootRevisions[actionId];
        uint64 actual = state.governanceRootRevision;
        if (expected == 0 || expected != actual) {
            revert IStreamGovernanceExecutor.GovernanceRootRevisionMismatch(
                actionId, expected, actual
            );
        }
    }

    function requireCancellationAuthority(
        LifecycleState storage state,
        StreamGovernancePolicy.AdminState storage admin,
        GovernanceAction storage action,
        address genesisBootstrapAuthority,
        bytes4 registerCancellerSelector
    ) public view {
        if (!state.isSealed) {
            if (msg.sender != genesisBootstrapAuthority && msg.sender != action.proposer) {
                revert IStreamGovernanceExecutor.GovernanceActorNotAuthorized(msg.sender);
            }
            return;
        }
        bool rootAuthorized = msg.sender == state.governanceRoot;
        if (rootAuthorized) requireGovernanceRootCodeHash(state);
        bool proposerAuthorized = msg.sender == action.proposer;
        bool registeredCanceller = admin.cancellers[msg.sender];
        bool cancellerRemoval = action.target == address(this)
            && action.selector == registerCancellerSelector
            && action.actionClass == StreamGovernanceActionClasses.DELAYED_LOOSENING;
        if (!rootAuthorized && !proposerAuthorized && (!registeredCanceller || cancellerRemoval)) {
            revert IStreamGovernanceExecutor.GovernanceActorNotAuthorized(msg.sender);
        }
    }

    function computeInventoryState(LifecycleState storage state)
        public
        view
        returns (bytes32 inventoryStateRoot, uint256 inventoryLeafCount)
    {
        bytes32[] memory pointerTypes = state.pointerTypes;
        address[] memory registries = state.registries;
        (inventoryStateRoot, inventoryLeafCount) =
            StreamGovernanceEvidence.computeInventoryState(state.core, pointerTypes, registries);
    }

    function requireBootstrapCodeHashes(LifecycleState storage state) public view {
        if (
            !state.bound || address(state.roleRegistry).codehash != state.roleRegistryCodeHash
                || state.core.codehash != state.coreCodeHash
                || state.systemManifestSatellite.codehash != state.systemManifestSatelliteCodeHash
                || state.governanceRoot.codehash != state.governanceRootCodeHash
        ) {
            if (state.bound && address(state.roleRegistry).codehash != state.roleRegistryCodeHash) {
                revert IStreamGovernanceExecutor.RoleRegistryCodeHashMismatch(
                    state.roleRegistryCodeHash, address(state.roleRegistry).codehash
                );
            }
            if (state.bound && state.governanceRoot.codehash != state.governanceRootCodeHash) {
                revert IStreamGovernanceExecutor.GovernanceRootCodeHashMismatch(
                    state.governanceRootCodeHash, state.governanceRoot.codehash
                );
            }
            revert IStreamGovernanceExecutor.InvalidSystemManifestBootstrap();
        }
        if (state.registries.length != state.registryCodeHashes.length) {
            revert IStreamGovernanceExecutor.InvalidSystemManifestBootstrap();
        }
        for (uint256 i = 0; i < state.registries.length; i++) {
            if (state.registries[i].codehash != state.registryCodeHashes[i]) {
                revert IStreamGovernanceExecutor.InvalidSystemManifestBootstrap();
            }
        }
    }

    function requireGovernanceRootCodeHash(LifecycleState storage state) public view {
        bytes32 actual = state.governanceRoot.codehash;
        if (
            !state.bound || state.governanceRoot == address(0)
                || actual != state.governanceRootCodeHash
        ) {
            revert IStreamGovernanceExecutor.GovernanceRootCodeHashMismatch(
                state.governanceRootCodeHash, actual
            );
        }
    }

    function validateGovernanceRootRotation(
        LifecycleState storage state,
        address genesisBootstrapAuthority,
        address newRoot,
        bytes32 expectedCodeHash
    ) public view returns (address oldRoot) {
        requireBoundRoleRegistry(state);
        oldRoot = state.governanceRoot;
        if (
            newRoot == address(0) || newRoot == address(this) || newRoot.code.length == 0
                || _isEip7702DelegatedEOA(newRoot) || newRoot == genesisBootstrapAuthority
                || newRoot == address(state.roleRegistry) || newRoot == state.core
                || newRoot == state.systemManifestSatellite
                || state.roleRegistry.hasAnyTerminalFreezeVetoRole(newRoot)
        ) {
            revert IStreamGovernanceExecutor.InvalidGovernanceRoot(newRoot);
        }
        if (newRoot == oldRoot) {
            revert IStreamGovernanceExecutor.GovernanceRootNoOp(newRoot);
        }
        requireGovernanceRootCodeHash(state);
        bytes32 actualCodeHash = newRoot.codehash;
        if (expectedCodeHash == bytes32(0) || actualCodeHash != expectedCodeHash) {
            revert IStreamGovernanceExecutor.GovernanceRootCodeHashMismatch(
                expectedCodeHash, actualCodeHash
            );
        }
    }

    function _readManifestPublicationCount(address satellite)
        private
        view
        returns (uint256 publicationCount)
    {
        bytes memory callData = abi.encodeWithSelector(MANIFEST_PUBLICATION_COUNT_SELECTOR);
        bool success;
        assembly ("memory-safe") {
            success := staticcall(
                gas(),
                satellite,
                add(callData, 0x20),
                mload(callData),
                0x00,
                0x00
            )
            if eq(returndatasize(), 0x20) {
                returndatacopy(0x00, 0x00, 0x20)
                publicationCount := mload(0x00)
            }
            if iszero(eq(returndatasize(), 0x20)) { success := 0 }
        }
        if (!success) revert IStreamGovernanceExecutor.InvalidSystemManifestBootstrap();
    }

    function requireBoundRoleRegistry(LifecycleState storage state) public view {
        if (!state.bound) revert IStreamGovernanceExecutor.SystemManifestBootstrapNotBound();
        bytes32 actual = address(state.roleRegistry).codehash;
        if (actual != state.roleRegistryCodeHash) {
            revert IStreamGovernanceExecutor.RoleRegistryCodeHashMismatch(
                state.roleRegistryCodeHash, actual
            );
        }
    }

    /// @dev EIP-7702 designations are exactly `0xef0100 || delegate`.
    function _isEip7702DelegatedEOA(address account) private view returns (bool delegated) {
        if (account.code.length != 23) return false;
        bytes3 prefix;
        assembly ("memory-safe") {
            extcodecopy(account, 0, 0, 3)
            prefix := mload(0)
        }
        return prefix == 0xef0100;
    }

    function _validateBootstrapBinding(
        SystemManifestBootstrapBinding calldata binding,
        address genesisBootstrapAuthority
    ) private view {
        if (binding.governanceRoot == genesisBootstrapAuthority) {
            revert IStreamGovernanceExecutor.InvalidGovernanceRoot(binding.governanceRoot);
        }
        if (
            binding.roleRegistry == genesisBootstrapAuthority
                || binding.core == genesisBootstrapAuthority
                || binding.systemManifestSatellite == genesisBootstrapAuthority
        ) revert IStreamGovernanceExecutor.InvalidSystemManifestBootstrap();
        for (uint256 i = 0; i < binding.initialTerminalFreezeVetoGuardians.length; i++) {
            if (binding.initialTerminalFreezeVetoGuardians[i] == genesisBootstrapAuthority) {
                revert IStreamGovernanceExecutor.InvalidSystemManifestBootstrap();
            }
        }
        StreamGovernanceEvidence.validateBootstrapBinding(binding);
    }

    function _requireBootstrapRoleState(LifecycleState storage state) private view {
        StreamGovernanceEvidence.requireRoleRegistryOwner(
            address(state.roleRegistry), address(this)
        );
        (bytes32 chainHash, uint64 revision) =
            state.roleRegistry.roleMutationState(StreamRoles.ROLE_TERMINAL_FREEZE_VETO);
        uint256 guardianCount = state.initialTerminalFreezeVetoGuardians.length;
        if (
            chainHash != state.initialTerminalRoleMutationChain
                || revision != state.initialTerminalRoleMutationRevision
                || state.roleRegistry.roleHolderCount(StreamRoles.ROLE_TERMINAL_FREEZE_VETO)
                    != guardianCount
                || !state.roleRegistry.isRoleRedundant(StreamRoles.ROLE_TERMINAL_FREEZE_VETO)
        ) revert IStreamGovernanceExecutor.InvalidSystemManifestBootstrap();
        address[] memory guardians = state.initialTerminalFreezeVetoGuardians;
        for (uint256 i = 0; i < guardianCount; i++) {
            if (
                state.roleRegistry.roleHolderAt(StreamRoles.ROLE_TERMINAL_FREEZE_VETO, i)
                    != guardians[i]
            ) revert IStreamGovernanceExecutor.InvalidSystemManifestBootstrap();
        }
        if (
            StreamGovernancePolicy.initialTerminalGuardianSetHash(
                    address(state.roleRegistry), guardians, chainHash, revision
                ) != state.initialGuardianSetHash
        ) revert IStreamGovernanceExecutor.InvalidSystemManifestBootstrap();
    }

    function _verifyBootstrapTriggerSet(
        LifecycleState storage state,
        StreamGovernanceBootstrap.PolicyState storage policy
    ) private view {
        StreamGovernanceBootstrap.verifyBootstrapTriggerSet(
                policy,
                state.bootstrapTriggerSetHash,
                state.expectedTriggerSetHash,
                state.expectedTriggerCount
            );
    }

    function _bootstrapScopeHash() private view returns (bytes32) {
        return keccak256(
            abi.encode(SYSTEM_MANIFEST_BOOTSTRAP_SCOPE_V1, uint256(block.chainid), address(this))
        );
    }

    function _bootstrapStateHash(
        LifecycleState storage state,
        address genesisBootstrapAuthority,
        bool isSealed,
        address sealedPayloadPointer,
        bytes32 currentInventoryRoot,
        uint256 currentInventoryCount
    ) private view returns (bytes32) {
        BootstrapStateView memory stateView = _stateView(
            state,
            genesisBootstrapAuthority,
            isSealed,
            sealedPayloadPointer,
            currentInventoryRoot,
            currentInventoryCount
        );
        return keccak256(
            bytes.concat(
                abi.encode(SYSTEM_MANIFEST_BOOTSTRAP_STATE_V2, _bootstrapScopeHash()),
                abi.encode(stateView)
            )
        );
    }

    function _stateView(
        LifecycleState storage state,
        address genesisBootstrapAuthority,
        bool isSealed,
        address sealedPayloadPointer,
        bytes32 currentInventoryRoot,
        uint256 currentInventoryCount
    ) private view returns (BootstrapStateView memory) {
        if (
            state.expectedTriggerCount > type(uint64).max
                || state.expectedInventoryLeafCount > type(uint64).max
                || currentInventoryCount > type(uint64).max
        ) {
            revert IStreamGovernanceExecutor.InvalidSystemManifestBootstrap();
        }
        return BootstrapStateView({
            bound: state.bound,
            isSealed: isSealed,
            roleRegistry: address(state.roleRegistry),
            roleRegistryCodeHash: state.roleRegistryCodeHash,
            governanceRoot: state.governanceRoot,
            governanceRootCodeHash: state.governanceRootCodeHash,
            governanceRootRevision: state.governanceRootRevision,
            initialGuardianSetHash: state.initialGuardianSetHash,
            initialGuardianCount: state.initialTerminalFreezeVetoGuardians.length,
            terminalFreezeVetoMutationChain: state.initialTerminalRoleMutationChain,
            terminalFreezeVetoMutationRevision: state.initialTerminalRoleMutationRevision,
            core: state.core,
            coreCodeHash: state.coreCodeHash,
            systemManifestSatellite: state.systemManifestSatellite,
            systemManifestSatelliteCodeHash: state.systemManifestSatelliteCodeHash,
            triggerSetHash: state.bootstrapTriggerSetHash,
            triggerCount: state.expectedTriggerCount,
            expectedTriggerSetHash: state.expectedTriggerSetHash,
            expectedTriggerCount: state.expectedTriggerCount,
            expectedManifestHash: state.expectedManifestHash,
            expectedInventoryStateRoot: state.expectedInventoryStateRoot,
            expectedInventoryLeafCount: state.expectedInventoryLeafCount,
            inventoryStateRoot: currentInventoryRoot,
            inventoryLeafCount: currentInventoryCount,
            bootstrapAuthority: genesisBootstrapAuthority,
            sealedPayloadPointer: sealedPayloadPointer,
            actionPolicyCandidateProfileHash: state.actionPolicyCandidateProfileHash,
            actionPolicyCatalogHash: state.actionPolicyCatalogHash,
            actionPolicyEntryCount: state.actionPolicyEntryCount
        });
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/governance/IStreamGovernanceExecutor.sol";
import "../../interfaces/stream/governance/IStreamRoleRegistry.sol";
import "./StreamGovernanceBootstrap.sol";
import "./StreamRoles.sol";

/// @notice Linked policy/state-transition library for Executor-resident
///         governance configuration. Public functions execute by DELEGATECALL,
///         so `address(this)`, `msg.sender`, emitted events, and storage remain
///         those of the Executor while the validation bytecode stays outside
///         its EIP-170 envelope.
library StreamGovernancePolicy {
    uint16 private constant SCHEMA_VERSION = 1;
    bytes32 private constant TERMINAL_GUARDIAN_CONFIG_V1 =
        keccak256("6529STREAM_TERMINAL_GUARDIAN_CONFIG_V1");
    bytes32 private constant TERMINAL_GUARDIAN_SCOPE_V1 =
        keccak256("6529STREAM_TERMINAL_GUARDIAN_SCOPE_V1");
    bytes32 private constant INITIAL_TERMINAL_GUARDIAN_SET_V1 =
        keccak256("6529STREAM_INITIAL_TERMINAL_GUARDIAN_SET_V1");
    bytes32 private constant TERMINAL_GUARDIAN_HOLDER_V1 =
        keccak256("6529STREAM_TERMINAL_GUARDIAN_HOLDER_V1");
    bytes32 private constant GOVERNANCE_CONFIG_SCOPE_V1 =
        keccak256("6529STREAM_GOVERNANCE_CONFIG_SCOPE_V1");
    bytes32 private constant GOVERNANCE_CONFIG_STATE_V1 =
        keccak256("6529STREAM_GOVERNANCE_CONFIG_STATE_V1");
    bytes32 private constant GOVERNANCE_ROOT_SCOPE_V1 =
        keccak256("6529STREAM_GOVERNANCE_ROOT_SCOPE_V1");
    bytes32 private constant GOVERNANCE_ROOT_STATE_V1 =
        keccak256("6529STREAM_GOVERNANCE_ROOT_STATE_V1");
    bytes32 private constant GOVERNANCE_CONFIG_PROPOSER =
        keccak256("6529STREAM_GOVERNANCE_CONFIG_PROPOSER");
    bytes32 private constant GOVERNANCE_CONFIG_CANCELLER =
        keccak256("6529STREAM_GOVERNANCE_CONFIG_CANCELLER");
    bytes32 private constant GOVERNANCE_CONFIG_NATIVE_RECEIVER =
        keccak256("6529STREAM_GOVERNANCE_CONFIG_NATIVE_RECEIVER");
    bytes32 private constant GOVERNANCE_CONFIG_TIGHTENING_CALL =
        keccak256("6529STREAM_GOVERNANCE_CONFIG_TIGHTENING_CALL");
    bytes32 private constant GOVERNANCE_CONFIG_FREEZE_SELECTOR =
        keccak256("6529STREAM_GOVERNANCE_CONFIG_FREEZE_SELECTOR");

    struct AdminState {
        mapping(address => bool) proposers;
        mapping(address => bool) cancellers;
        mapping(address => uint64) proposerRevisions;
        mapping(address => uint64) cancellerRevisions;
        mapping(address => uint64) nativeReceiverRevisions;
        mapping(bytes32 => uint64) tighteningCallRevisions;
        mapping(bytes32 => uint64) freezeSelectorRevisions;
        mapping(bytes32 => uint64) actionProposerRevisions;
    }

    struct ExecutionContext {
        bool executing;
        bytes32 actionId;
        uint8 actionClass;
        bytes32 scopeHash;
        bytes32 oldValueHash;
        bytes32 newValueHash;
        uint256 batchLength;
        uint256 callIndex;
    }

    event GovernanceProposerUpdated(
        uint16 schemaVersion,
        address indexed account,
        bool enabled,
        uint64 revision,
        bytes32 indexed actionId
    );
    event GovernanceCancellerUpdated(
        uint16 schemaVersion,
        address indexed account,
        bool enabled,
        uint64 revision,
        bytes32 indexed actionId
    );
    event ApprovedNativeReceiverUpdated(
        uint16 schemaVersion,
        address indexed receiver,
        bool approved,
        uint64 revision,
        bytes32 indexed actionId
    );
    event TighteningCallUpdated(
        uint16 schemaVersion,
        address indexed target,
        bytes4 indexed selector,
        bool tightening,
        bytes32 targetCodeHash,
        uint64 revision,
        bytes32 indexed actionId
    );
    event FreezeSelectorUpdated(
        uint16 schemaVersion,
        address indexed target,
        bytes4 indexed selector,
        bool freeze,
        bytes32 targetCodeHash,
        uint64 revision,
        bytes32 indexed actionId
    );

    function snapshotActionProposerRevision(
        AdminState storage admin,
        bytes32 actionId,
        address proposer,
        bool privilegedProposer
    ) internal {
        if (!privilegedProposer) {
            admin.actionProposerRevisions[actionId] = admin.proposerRevisions[proposer];
        }
    }

    function requireActionProposerRevision(
        AdminState storage admin,
        bytes32 actionId,
        address proposer
    ) internal view {
        uint64 expected = admin.actionProposerRevisions[actionId];
        if (expected == 0) return;
        uint64 actual = admin.proposerRevisions[proposer];
        bool enabled = admin.proposers[proposer];
        if (!enabled || expected != actual) {
            revert IStreamGovernanceExecutor.GovernanceProposerAuthorizationDrift(
                actionId, proposer, expected, actual, enabled
            );
        }
    }

    function updateProposer(
        AdminState storage admin,
        IStreamRoleRegistry roleRegistry,
        address account,
        bool enabled,
        ExecutionContext memory ctx
    ) public {
        _requireIsolated(
            ctx,
            enabled
                ? StreamGovernanceActionClasses.DELAYED_LOOSENING
                : StreamGovernanceActionClasses.IMMEDIATE_TIGHTENING
        );
        if (account == address(0)) revert IStreamGovernanceExecutor.ZeroProposer();
        if (enabled && roleRegistry.hasAnyTerminalFreezeVetoRole(account)) {
            revert IStreamGovernanceExecutor.GovernanceIdentityRoleOverlap(
                account, StreamRoles.ROLE_TERMINAL_FREEZE_VETO
            );
        }
        bool oldEnabled = admin.proposers[account];
        if (oldEnabled == enabled) {
            revert IStreamGovernanceExecutor.GovernanceConfigNoOp(
                GOVERNANCE_CONFIG_PROPOSER, account, enabled
            );
        }
        (bytes32 scopeHash, bytes32 oldHash, bytes32 newHash, uint64 revision) = governanceConfigTransitionHashes(
            GOVERNANCE_CONFIG_PROPOSER,
            account,
            oldEnabled,
            admin.proposerRevisions[account],
            enabled
        );
        _requireTransition(ctx, scopeHash, oldHash, newHash);
        admin.proposers[account] = enabled;
        admin.proposerRevisions[account] = revision;
        emit GovernanceProposerUpdated(SCHEMA_VERSION, account, enabled, revision, ctx.actionId);
    }

    function updateCanceller(
        AdminState storage admin,
        address account,
        bool enabled,
        ExecutionContext memory ctx
    ) public {
        _requireIsolated(
            ctx,
            enabled
                ? StreamGovernanceActionClasses.IMMEDIATE_TIGHTENING
                : StreamGovernanceActionClasses.DELAYED_LOOSENING
        );
        if (account == address(0)) revert IStreamGovernanceExecutor.ZeroCanceller();
        bool oldEnabled = admin.cancellers[account];
        if (oldEnabled == enabled) {
            revert IStreamGovernanceExecutor.GovernanceConfigNoOp(
                GOVERNANCE_CONFIG_CANCELLER, account, enabled
            );
        }
        (bytes32 scopeHash, bytes32 oldHash, bytes32 newHash, uint64 revision) = governanceConfigTransitionHashes(
            GOVERNANCE_CONFIG_CANCELLER,
            account,
            oldEnabled,
            admin.cancellerRevisions[account],
            enabled
        );
        _requireTransition(ctx, scopeHash, oldHash, newHash);
        admin.cancellers[account] = enabled;
        admin.cancellerRevisions[account] = revision;
        emit GovernanceCancellerUpdated(SCHEMA_VERSION, account, enabled, revision, ctx.actionId);
    }

    function updateNativeReceiver(
        StreamGovernanceBootstrap.PolicyState storage policy,
        AdminState storage admin,
        address receiver,
        bool approved,
        ExecutionContext memory ctx
    ) public {
        _requireIsolated(
            ctx,
            approved
                ? StreamGovernanceActionClasses.DELAYED_LOOSENING
                : StreamGovernanceActionClasses.IMMEDIATE_TIGHTENING
        );
        if (receiver == address(0)) revert IStreamGovernanceExecutor.ZeroNativeReceiver();
        bool oldApproved = policy.approvedNativeReceivers[receiver];
        if (oldApproved == approved) {
            revert IStreamGovernanceExecutor.GovernanceConfigNoOp(
                GOVERNANCE_CONFIG_NATIVE_RECEIVER, receiver, approved
            );
        }
        (bytes32 scopeHash, bytes32 oldHash, bytes32 newHash, uint64 revision) = governanceConfigTransitionHashes(
            GOVERNANCE_CONFIG_NATIVE_RECEIVER,
            receiver,
            oldApproved,
            admin.nativeReceiverRevisions[receiver],
            approved
        );
        _requireTransition(ctx, scopeHash, oldHash, newHash);
        policy.approvedNativeReceivers[receiver] = approved;
        admin.nativeReceiverRevisions[receiver] = revision;
        emit ApprovedNativeReceiverUpdated(
            SCHEMA_VERSION, receiver, approved, revision, ctx.actionId
        );
    }

    function updateTighteningCall(
        StreamGovernanceBootstrap.PolicyState storage policy,
        AdminState storage admin,
        address target,
        bytes4 selector,
        bool tightening,
        ExecutionContext memory ctx
    ) public {
        _requireIsolated(
            ctx,
            tightening
                ? StreamGovernanceActionClasses.DELAYED_LOOSENING
                : StreamGovernanceActionClasses.IMMEDIATE_TIGHTENING
        );
        if (target == address(0)) revert IStreamGovernanceExecutor.ZeroTighteningTarget();
        if (selector == bytes4(0)) {
            revert IStreamGovernanceExecutor.ZeroTighteningSelector();
        }
        if (target == address(this)) {
            revert IStreamGovernanceExecutor.TighteningCallSelfTargetForbidden(selector);
        }
        bool oldEnabled = policy.tighteningCalls[target][selector];
        bytes32 oldCodeHash = policy.tighteningCallCodeHashes[target][selector];
        if (oldEnabled == tightening) {
            revert IStreamGovernanceExecutor.GovernanceConfigNoOp(
                GOVERNANCE_CONFIG_TIGHTENING_CALL, target, tightening
            );
        }
        if (oldEnabled) _requirePolicyCodeHash(target, selector, oldCodeHash);
        bytes32 newCodeHash = _enabledCodeHash(target, tightening);
        bytes32 key = keccak256(abi.encode(target, selector));
        (bytes32 scopeHash, bytes32 oldHash, bytes32 newHash, uint64 revision) = governanceSelectorConfigTransitionHashes(
            GOVERNANCE_CONFIG_TIGHTENING_CALL,
            target,
            selector,
            oldEnabled,
            oldCodeHash,
            admin.tighteningCallRevisions[key],
            tightening,
            newCodeHash
        );
        _requireTransition(ctx, scopeHash, oldHash, newHash);
        policy.tighteningCalls[target][selector] = tightening;
        policy.tighteningCallCodeHashes[target][selector] = newCodeHash;
        admin.tighteningCallRevisions[key] = revision;
        emit TighteningCallUpdated(
            SCHEMA_VERSION, target, selector, tightening, newCodeHash, revision, ctx.actionId
        );
    }

    function updateFreezeSelector(
        StreamGovernanceBootstrap.PolicyState storage policy,
        AdminState storage admin,
        address target,
        bytes4 selector,
        bool freeze,
        address manifestTailTarget,
        bytes4 manifestTailSelector,
        ExecutionContext memory ctx
    ) public {
        _requireIsolated(
            ctx,
            freeze
                ? StreamGovernanceActionClasses.IMMEDIATE_TIGHTENING
                : StreamGovernanceActionClasses.DELAYED_LOOSENING
        );
        if (target == address(0)) revert IStreamGovernanceExecutor.ZeroFreezeTarget();
        if (selector == bytes4(0)) revert IStreamGovernanceExecutor.ZeroFreezeSelector();
        if (target == address(this)) {
            revert IStreamGovernanceExecutor.FreezeSelectorSelfTargetForbidden(selector);
        }
        if (freeze && target == manifestTailTarget && selector == manifestTailSelector) {
            revert IStreamGovernanceExecutor.InvalidManifestTailTrigger(target, selector);
        }
        if (
            freeze && policy.tailRules[target][selector].triggerCodeHash != bytes32(0)
                && (policy.tailRules[target][selector].allowedActionClassMask & 0x04) == 0
        ) {
            revert IStreamGovernanceExecutor.InvalidManifestTailTrigger(target, selector);
        }
        bool oldEnabled = policy.freezeSelectors[target][selector];
        bytes32 oldCodeHash = policy.freezeSelectorCodeHashes[target][selector];
        if (oldEnabled == freeze) {
            revert IStreamGovernanceExecutor.GovernanceConfigNoOp(
                GOVERNANCE_CONFIG_FREEZE_SELECTOR, target, freeze
            );
        }
        if (oldEnabled) _requirePolicyCodeHash(target, selector, oldCodeHash);
        bytes32 newCodeHash = _enabledCodeHash(target, freeze);
        bytes32 key = keccak256(abi.encode(target, selector));
        (bytes32 scopeHash, bytes32 oldHash, bytes32 newHash, uint64 revision) = governanceSelectorConfigTransitionHashes(
            GOVERNANCE_CONFIG_FREEZE_SELECTOR,
            target,
            selector,
            oldEnabled,
            oldCodeHash,
            admin.freezeSelectorRevisions[key],
            freeze,
            newCodeHash
        );
        _requireTransition(ctx, scopeHash, oldHash, newHash);
        policy.freezeSelectors[target][selector] = freeze;
        policy.freezeSelectorCodeHashes[target][selector] = newCodeHash;
        admin.freezeSelectorRevisions[key] = revision;
        emit FreezeSelectorUpdated(
            SCHEMA_VERSION, target, selector, freeze, newCodeHash, revision, ctx.actionId
        );
    }

    function _enabledCodeHash(address target, bool enabled) private view returns (bytes32) {
        if (!enabled) return bytes32(0);
        bytes32 codeHash = target.codehash;
        if (target.code.length == 0 || codeHash == bytes32(0) || _isEip7702DelegatedEOA(target)) {
            revert IStreamGovernanceExecutor.TargetHasNoCode(0, target);
        }
        return codeHash;
    }

    function _isEip7702DelegatedEOA(address account) private view returns (bool delegated) {
        if (account.code.length != 23) return false;
        bytes3 prefix;
        assembly ("memory-safe") {
            extcodecopy(account, 0, 0, 3)
            prefix := mload(0)
        }
        return prefix == 0xef0100;
    }

    function _requireIsolated(ExecutionContext memory ctx, uint8 requiredClass) private view {
        if (
            msg.sender != address(this) || !ctx.executing || ctx.actionId == bytes32(0)
                || ctx.actionClass != requiredClass || ctx.batchLength != 1 || ctx.callIndex != 0
        ) revert IStreamGovernanceExecutor.GovernanceSelfCallContextRequired();
    }

    function _requireTransition(
        ExecutionContext memory ctx,
        bytes32 scopeHash,
        bytes32 oldValueHash,
        bytes32 newValueHash
    ) private pure {
        if (
            ctx.scopeHash != scopeHash || ctx.oldValueHash != oldValueHash
                || ctx.newValueHash != newValueHash
        ) revert IStreamGovernanceExecutor.GovernanceTransitionContextMismatch();
    }

    function requirePolicyCodeHash(address target, bytes4 selector, bytes32 expectedCodeHash)
        public
        view
    {
        _requirePolicyCodeHash(target, selector, expectedCodeHash);
    }

    function _requirePolicyCodeHash(address target, bytes4 selector, bytes32 expectedCodeHash)
        private
        view
    {
        bytes32 actualCodeHash = target.codehash;
        if (expectedCodeHash == bytes32(0) || actualCodeHash != expectedCodeHash) {
            revert IStreamGovernanceExecutor.GovernancePolicyCodeHashMismatch(
                target, selector, expectedCodeHash, actualCodeHash
            );
        }
    }

    function terminalFreezeGuardianConfigCommitment(
        IStreamRoleRegistry registry,
        GovernanceCall[] memory calls
    ) public view returns (bytes32 commitment) {
        (bytes32 baseChain, uint64 baseRevision) = registry.roleMutationState(
            StreamRoles.ROLE_TERMINAL_FREEZE_VETO
        );
        commitment = keccak256(
            abi.encode(
                TERMINAL_GUARDIAN_CONFIG_V1,
                uint256(block.chainid),
                address(this),
                address(registry),
                address(registry).codehash,
                baseChain,
                baseRevision
            )
        );
        commitment = _appendGuardianHolderCodeHashes(
            registry, StreamRoles.ROLE_TERMINAL_FREEZE_VETO, commitment
        );
        uint256 distinctScopeCount = 0;
        for (uint256 i = 0; i < calls.length; i++) {
            if (_scopeSeenBefore(calls, i, calls[i].scopeHash)) continue;
            bytes32 derivedRole =
                keccak256(abi.encode(StreamRoles.ROLE_TERMINAL_FREEZE_VETO, calls[i].scopeHash));
            (bytes32 scopedChain, uint64 scopedRevision) = registry.roleMutationState(derivedRole);
            commitment = keccak256(
                abi.encode(
                    TERMINAL_GUARDIAN_SCOPE_V1,
                    commitment,
                    calls[i].scopeHash,
                    derivedRole,
                    scopedChain,
                    scopedRevision
                )
            );
            commitment = _appendGuardianHolderCodeHashes(registry, derivedRole, commitment);
            distinctScopeCount++;
        }
        return keccak256(abi.encode(TERMINAL_GUARDIAN_CONFIG_V1, commitment, distinctScopeCount));
    }

    function initialTerminalGuardianSetHash(
        address registry,
        address[] memory guardians,
        bytes32 terminalRoleMutationChain,
        uint64 terminalRoleMutationRevision
    ) public view returns (bytes32 setHash) {
        setHash = keccak256(
            abi.encode(
                INITIAL_TERMINAL_GUARDIAN_SET_V1,
                uint256(block.chainid),
                address(this),
                registry,
                guardians.length,
                terminalRoleMutationChain,
                terminalRoleMutationRevision
            )
        );
        for (uint256 i = 0; i < guardians.length; i++) {
            setHash = keccak256(
                abi.encode(
                    TERMINAL_GUARDIAN_HOLDER_V1, setHash, i, guardians[i], guardians[i].codehash
                )
            );
        }
    }

    function _appendGuardianHolderCodeHashes(
        IStreamRoleRegistry registry,
        bytes32 role,
        bytes32 chainHash
    ) private view returns (bytes32) {
        uint256 holderCount = registry.roleHolderCount(role);
        chainHash = keccak256(abi.encode(TERMINAL_GUARDIAN_HOLDER_V1, chainHash, role, holderCount));
        for (uint256 i = 0; i < holderCount; i++) {
            address holder = registry.roleHolderAt(role, i);
            chainHash = keccak256(
                abi.encode(TERMINAL_GUARDIAN_HOLDER_V1, chainHash, role, i, holder, holder.codehash)
            );
        }
        return chainHash;
    }

    function governanceConfigTransitionHashes(
        bytes32 configKind,
        address key,
        bool oldEnabled,
        uint64 oldRevision,
        bool newEnabled
    )
        public
        view
        returns (bytes32 scopeHash, bytes32 oldStateHash, bytes32 newStateHash, uint64 newRevision)
    {
        if (oldRevision == type(uint64).max) {
            revert IStreamGovernanceExecutor.GovernanceRevisionOverflow(configKind, key);
        }
        unchecked {
            newRevision = oldRevision + 1;
        }
        scopeHash = keccak256(
            abi.encode(
                GOVERNANCE_CONFIG_SCOPE_V1, uint256(block.chainid), address(this), configKind, key
            )
        );
        oldStateHash = governanceConfigStateHash(configKind, key, oldEnabled, oldRevision);
        newStateHash = governanceConfigStateHash(configKind, key, newEnabled, newRevision);
    }

    function governanceConfigStateHash(
        bytes32 configKind,
        address key,
        bool enabled,
        uint64 revision
    ) public view returns (bytes32) {
        return keccak256(
            abi.encode(
                GOVERNANCE_CONFIG_STATE_V1,
                uint256(block.chainid),
                address(this),
                configKind,
                key,
                enabled,
                revision
            )
        );
    }

    function governanceSelectorConfigTransitionHashes(
        bytes32 configKind,
        address target,
        bytes4 selector,
        bool oldEnabled,
        bytes32 oldCodeHash,
        uint64 oldRevision,
        bool newEnabled,
        bytes32 newCodeHash
    )
        public
        view
        returns (bytes32 scopeHash, bytes32 oldStateHash, bytes32 newStateHash, uint64 newRevision)
    {
        if (oldRevision == type(uint64).max) {
            revert IStreamGovernanceExecutor.GovernanceRevisionOverflow(configKind, target);
        }
        unchecked {
            newRevision = oldRevision + 1;
        }
        scopeHash = keccak256(
            abi.encode(
                GOVERNANCE_CONFIG_SCOPE_V1,
                uint256(block.chainid),
                address(this),
                configKind,
                target,
                selector
            )
        );
        oldStateHash = governanceSelectorConfigStateHash(
            configKind, target, selector, oldEnabled, oldCodeHash, oldRevision
        );
        newStateHash = governanceSelectorConfigStateHash(
            configKind, target, selector, newEnabled, newCodeHash, newRevision
        );
    }

    function governanceSelectorConfigStateHash(
        bytes32 configKind,
        address target,
        bytes4 selector,
        bool enabled,
        bytes32 targetCodeHash,
        uint64 revision
    ) public view returns (bytes32) {
        return keccak256(
            abi.encode(
                GOVERNANCE_CONFIG_STATE_V1,
                uint256(block.chainid),
                address(this),
                configKind,
                target,
                selector,
                enabled,
                targetCodeHash,
                revision
            )
        );
    }

    function governanceRootTransitionHashes(
        address oldRoot,
        bytes32 oldCodeHash,
        uint64 oldRevision,
        address newRoot,
        bytes32 newCodeHash
    )
        public
        view
        returns (bytes32 scopeHash, bytes32 oldStateHash, bytes32 newStateHash, uint64 newRevision)
    {
        if (oldRevision == type(uint64).max) {
            revert IStreamGovernanceExecutor.GovernanceRevisionOverflow(
                GOVERNANCE_ROOT_STATE_V1, oldRoot
            );
        }
        unchecked {
            newRevision = oldRevision + 1;
        }
        scopeHash = keccak256(
            abi.encode(GOVERNANCE_ROOT_SCOPE_V1, uint256(block.chainid), address(this))
        );
        oldStateHash = governanceRootStateHash(oldRoot, oldCodeHash, oldRevision);
        newStateHash = governanceRootStateHash(newRoot, newCodeHash, newRevision);
    }

    function governanceRootStateHash(address root, bytes32 codeHash, uint64 revision)
        public
        view
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                GOVERNANCE_ROOT_STATE_V1,
                uint256(block.chainid),
                address(this),
                root,
                codeHash,
                revision
            )
        );
    }

    function _scopeSeenBefore(
        GovernanceCall[] memory calls,
        uint256 endExclusive,
        bytes32 scopeHash
    ) private pure returns (bool) {
        for (uint256 i = 0; i < endExclusive; i++) {
            if (calls[i].scopeHash == scopeHash) return true;
        }
        return false;
    }

    function proposerConfig(AdminState storage admin, address account)
        public
        view
        returns (bool enabled, uint64 revision, bytes32 stateHash)
    {
        enabled = admin.proposers[account];
        revision = admin.proposerRevisions[account];
        stateHash =
            governanceConfigStateHash(GOVERNANCE_CONFIG_PROPOSER, account, enabled, revision);
    }

    function cancellerConfig(AdminState storage admin, address account)
        public
        view
        returns (bool enabled, uint64 revision, bytes32 stateHash)
    {
        enabled = admin.cancellers[account];
        revision = admin.cancellerRevisions[account];
        stateHash =
            governanceConfigStateHash(GOVERNANCE_CONFIG_CANCELLER, account, enabled, revision);
    }

    function nativeReceiverConfig(
        StreamGovernanceBootstrap.PolicyState storage policy,
        AdminState storage admin,
        address receiver
    ) public view returns (bool approved, uint64 revision, bytes32 stateHash) {
        approved = policy.approvedNativeReceivers[receiver];
        revision = admin.nativeReceiverRevisions[receiver];
        stateHash = governanceConfigStateHash(
            GOVERNANCE_CONFIG_NATIVE_RECEIVER, receiver, approved, revision
        );
    }

    function tighteningConfig(
        StreamGovernanceBootstrap.PolicyState storage policy,
        AdminState storage admin,
        address target,
        bytes4 selector
    )
        public
        view
        returns (bool tightening, bytes32 targetCodeHash, uint64 revision, bytes32 stateHash)
    {
        tightening = policy.tighteningCalls[target][selector];
        targetCodeHash = policy.tighteningCallCodeHashes[target][selector];
        revision = admin.tighteningCallRevisions[keccak256(abi.encode(target, selector))];
        stateHash = governanceSelectorConfigStateHash(
            GOVERNANCE_CONFIG_TIGHTENING_CALL,
            target,
            selector,
            tightening,
            targetCodeHash,
            revision
        );
    }

    function freezeConfig(
        StreamGovernanceBootstrap.PolicyState storage policy,
        AdminState storage admin,
        address target,
        bytes4 selector
    )
        public
        view
        returns (bool freeze, bytes32 targetCodeHash, uint64 revision, bytes32 stateHash)
    {
        freeze = policy.freezeSelectors[target][selector];
        targetCodeHash = policy.freezeSelectorCodeHashes[target][selector];
        revision = admin.freezeSelectorRevisions[keccak256(abi.encode(target, selector))];
        stateHash = governanceSelectorConfigStateHash(
            GOVERNANCE_CONFIG_FREEZE_SELECTOR, target, selector, freeze, targetCodeHash, revision
        );
    }

    function isTighteningCall(
        StreamGovernanceBootstrap.PolicyState storage policy,
        address target,
        bytes4 selector
    ) public view returns (bool tightening) {
        tightening = policy.tighteningCalls[target][selector];
        if (tightening) {
            _requirePolicyCodeHash(
                target, selector, policy.tighteningCallCodeHashes[target][selector]
            );
        }
    }

    function isFreezeSelector(
        StreamGovernanceBootstrap.PolicyState storage policy,
        address target,
        bytes4 selector
    ) public view returns (bool freeze) {
        freeze = policy.freezeSelectors[target][selector];
        if (freeze) {
            _requirePolicyCodeHash(
                target, selector, policy.freezeSelectorCodeHashes[target][selector]
            );
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamGovernanceManifest.sol";

/// @notice Linked scheduling validation and record encoding for the immutable Executor.
/// @dev Storage references point to the Executor's existing fields. This library does
///      not own execution context, counters, or a new storage layout. Public methods
///      run by DELEGATECALL, preserving the original caller and action-ID domain.
library StreamGovernanceScheduling {
    struct Runtime {
        address owner;
        address bootstrapAuthority;
        uint256 nonce;
        uint256 pendingCount;
        bool executing;
        bytes32 genesisPlanHash;
        bool genesisInitialized;
    }

    struct Prepared {
        bytes32 actionId;
        bytes32 callsHash;
        address callDataPointer;
        uint256 totalValue;
        bool privilegedProposer;
    }

    /// @notice Validate the complete schedule before the Executor consumes its nonce.
    function prepare(
        StreamGovernancePolicy.AdminState storage admin,
        StreamGovernanceBootstrap.PolicyState storage policy,
        StreamGovernanceActionPolicy.State storage actionPolicy,
        StreamGovernanceManifest.LifecycleState storage manifest,
        Runtime memory runtime,
        StreamGovernanceBootstrap.ScheduleContext memory ctx,
        GovernanceCall[] memory calls
    ) public returns (Prepared memory prepared) {
        if (runtime.executing) {
            revert IStreamGovernanceExecutor.GovernanceSchedulingDuringExecution();
        }
        if (runtime.genesisPlanHash != bytes32(0) && !runtime.genesisInitialized) {
            revert IStreamGenesisInitializer.InvalidGenesisPlan();
        }
        bool bootstrapAuthority =
            manifest.bound && !manifest.isSealed && msg.sender == runtime.bootstrapAuthority;
        prepared.privilegedProposer = bootstrapAuthority || msg.sender == runtime.owner;
        if (manifest.isSealed) StreamGovernanceManifest.requireGovernanceRootCodeHash(manifest);
        if (!prepared.privilegedProposer && !admin.proposers[msg.sender]) {
            revert IStreamGovernanceExecutor.GovernanceActorNotAuthorized(msg.sender);
        }
        if (!manifest.bound) revert IStreamGovernanceExecutor.SystemManifestBootstrapNotBound();
        if (!manifest.isSealed) {
            if (msg.sender != runtime.bootstrapAuthority) {
                revert IStreamGovernanceExecutor.GenesisBootstrapActorRequired(msg.sender);
            }
            if (runtime.pendingCount != 0) {
                revert IStreamGovernanceExecutor.PendingGovernanceActionExists(runtime.pendingCount);
            }
            StreamGovernanceManifest.requireBootstrapCodeHashes(manifest);
        }

        prepared.callDataPointer = StreamGovernanceBootstrap.requirePublishedCallData(policy, calls);
        bytes[] memory callDatas =
            StreamGovernanceBootstrap.readCanonicalCallDatas(prepared.callDataPointer);
        prepared.totalValue = StreamGovernanceBootstrap.validateCalls(
            policy,
            address(manifest.roleRegistry),
            manifest.systemManifestSatellite,
            ctx.actionClass,
            calls,
            callDatas,
            IStreamGovernanceExecutor.sealSystemManifestBootstrap.selector
        );
        prepared.callsHash = StreamGovernanceBootstrap.governanceCallsHash(calls);
        (bytes32 scopeHash, bytes32 oldValueHash, bytes32 newValueHash) =
            StreamGovernanceBootstrap.deriveBatchTransitionHashes(calls, prepared.callsHash);
        if (ctx.scopeHash != scopeHash) {
            revert IStreamGovernanceExecutor.BatchScopeHashMismatch(scopeHash, ctx.scopeHash);
        }
        if (ctx.oldValueHash != oldValueHash) {
            revert IStreamGovernanceExecutor.BatchOldValueHashMismatch(
                oldValueHash, ctx.oldValueHash
            );
        }
        if (ctx.newValueHash != newValueHash) {
            revert IStreamGovernanceExecutor.BatchNewValueHashMismatch(
                newValueHash, ctx.newValueHash
            );
        }
        // The atomic committed initializer alone has immediate windows.
        if (runtime.genesisInitialized && !manifest.isSealed) {
            if (!bootstrapAuthority) revert IStreamGenesisInitializer.InvalidGenesisPlan();
        } else {
            StreamGovernanceBootstrap.validateActionWindow(
                ctx.actionClass, ctx.notBefore, ctx.expiresAfter
            );
        }
        prepared.actionId = StreamGovernanceBootstrap.governanceActionId(
            StreamGovernanceBootstrap.ActionIdentity({
                actionClass: ctx.actionClass,
                callsHash: prepared.callsHash,
                scopeHash: ctx.scopeHash,
                oldValueHash: ctx.oldValueHash,
                newValueHash: ctx.newValueHash,
                nonce: runtime.nonce,
                notBefore: ctx.notBefore,
                expiresAfter: ctx.expiresAfter,
                reasonHash: ctx.reasonHash,
                manifestHash: ctx.manifestHash
            })
        );
        StreamGovernanceManifest.validateManifestTailComposition(
            policy,
            admin,
            manifest,
            prepared.actionId,
            msg.sender,
            ctx.actionClass,
            calls,
            !manifest.isSealed,
            true,
            prepared.privilegedProposer,
            IStreamGovernanceExecutor.sealSystemManifestBootstrap.selector,
            IStreamGovernanceExecutor.registerSystemManifestTailTrigger.selector
        );
        StreamGovernanceActionPolicy.validateCalls(
            actionPolicy,
            manifest.actionPolicyCandidateProfileHash,
            manifest.actionPolicyCatalogHash,
            manifest.actionPolicyEntryCount,
            ctx.actionClass,
            calls,
            callDatas
        );
        if (ctx.actionClass == StreamGovernanceActionClasses.TERMINAL_FREEZE) {
            StreamGovernanceManifest.requireBoundRoleRegistry(manifest);
            StreamGovernanceBootstrap.validateTerminalFreezeGuardians(manifest.roleRegistry, calls);
        }
    }

    /// @notice Persist the action at its existing mapping slot after validation.
    function storeAction(
        GovernanceAction storage action,
        StreamGovernanceBootstrap.ScheduleContext memory ctx,
        GovernanceCall memory firstCall,
        Prepared memory prepared
    ) public {
        if (action.status != GovernanceActionStatus.NONE) {
            revert IStreamGovernanceExecutor.GovernanceActionNotScheduled(prepared.actionId);
        }
        action.status = GovernanceActionStatus.SCHEDULED;
        action.actionClass = ctx.actionClass;
        action.target = firstCall.target;
        action.value = prepared.totalValue;
        action.selector = firstCall.selector;
        action.callHash = prepared.callsHash;
        action.scopeHash = ctx.scopeHash;
        action.oldValueHash = ctx.oldValueHash;
        action.newValueHash = ctx.newValueHash;
        action.notBefore = ctx.notBefore;
        action.expiresAfter = ctx.expiresAfter;
        action.proposer = msg.sender;
        action.reasonHash = ctx.reasonHash;
        action.reasonURI = ctx.reasonURI;
        action.manifestHash = ctx.manifestHash;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/governance/IStreamRoleRegistry.sol";
import "../../interfaces/stream/governance/IStreamGovernanceExecutor.sol";
import "../../vendor/openzeppelin/Ownable.sol";
import "./StreamRoles.sol";

/// @notice Admin registry resolving the ADR 0004 [GOV-ROLES] `ROLE_*`
///         vocabulary to current holders.
/// @dev The permanent owner is the staged governance Executor supplied at
///     construction. Root-class roles are granted and revoked only by the
///     Executor; operational-class roles are also grantable
///     by registered role managers. The vocabulary is closed-world: grants
///     against constants outside the pinned [GOV-ROLES] table revert. Holder
///     sets are enumerable so redundancy gates and deployment checks can prove
///     the active authority graph from state reads alone.
contract StreamRoleRegistry is Ownable, IStreamRoleRegistry {
    /// @notice Schema version carried by role lifecycle events.
    uint16 public constant SCHEMA_VERSION = 1;

    bytes32 private constant STREAM_ROLE_MUTATION_V1 = keccak256("6529STREAM_ROLE_MUTATION_V1");
    bytes32 private constant STREAM_GLOBAL_ROLE_MUTATION_V1 =
        keccak256("6529STREAM_GLOBAL_ROLE_MUTATION_V1");
    bytes32 private constant STREAM_ROLE_MUTATION_SCOPE_V1 =
        keccak256("6529STREAM_ROLE_MUTATION_SCOPE_V1");
    bytes32 private constant STREAM_ROLE_MUTATION_STATE_V1 =
        keccak256("6529STREAM_ROLE_MUTATION_STATE_V1");
    bytes32 private constant STREAM_ROLE_MANAGER_CONFIG_V1 =
        keccak256("6529STREAM_ROLE_MANAGER_CONFIG_V1");
    bytes32 private constant STREAM_ROLE_MANAGER_CONFIG_STATE_V1 =
        keccak256("6529STREAM_ROLE_MANAGER_CONFIG_STATE_V1");
    bytes32 private constant STREAM_ROLE_MANAGER_CONFIG_MUTATION_V1 =
        keccak256("6529STREAM_ROLE_MANAGER_CONFIG_MUTATION_V1");
    uint8 private constant IMMEDIATE_TIGHTENING = 0;
    bytes4 private constant SYSTEM_MANIFEST_BOOTSTRAP_STATE_SELECTOR = 0x8a2d979b;
    uint8 private constant DELAYED_LOOSENING = 1;

    mapping(address => bool) private _roleManagers;
    mapping(address => bytes32) private _roleManagerConfigChain;
    mapping(address => uint64) private _roleManagerConfigRevision;
    mapping(bytes32 => address[]) private _roleHolders;
    // holder => (index + 1) into _roleHolders[role]; zero means not a holder.
    mapping(bytes32 => mapping(address => uint256)) private _roleHolderIndex;
    mapping(bytes32 => bytes32) private _roleMutationChain;
    mapping(bytes32 => uint64) private _roleMutationRevision;
    bytes32 private _globalRoleMutationChain;
    uint64 private _globalRoleMutationRevision;
    bool private _terminalGuardianFloorActivated;
    mapping(address => uint256) private _terminalVetoMembershipCount;

    constructor(address governanceExecutor) {
        if (
            governanceExecutor == address(0) || governanceExecutor.code.length == 0
                || _isEip7702DelegatedEOA(governanceExecutor)
        ) {
            revert InvalidGovernanceExecutor(governanceExecutor);
        }
        _transferOwnership(governanceExecutor);
    }

    function transferOwnership(address) public pure override {
        revert DirectRoleRegistryOwnershipMutationDisabled();
    }

    function renounceOwnership() public pure override {
        revert DirectRoleRegistryOwnershipMutationDisabled();
    }

    /// @inheritdoc IStreamRoleRegistry
    function supportsInterface(bytes4 interfaceId) external pure override returns (bool) {
        return interfaceId == type(IStreamRoleRegistry).interfaceId || interfaceId == 0x01ffc9a7;
    }

    /// @inheritdoc IStreamRoleRegistry
    function grantRole(bytes32 role, address holder) external override {
        uint8 grantClass = roleGrantClass(role);
        _checkRoleActor(role, grantClass);
        _grant(role, holder, grantClass, role == StreamRoles.ROLE_TERMINAL_FREEZE_VETO);
    }

    /// @inheritdoc IStreamRoleRegistry
    function revokeRole(bytes32 role, address holder) external override {
        uint8 grantClass = roleGrantClass(role);
        _checkRoleActor(role, grantClass);
        _revoke(role, holder, grantClass, role == StreamRoles.ROLE_TERMINAL_FREEZE_VETO);
    }

    /// @inheritdoc IStreamRoleRegistry
    function grantScopedRole(bytes32 baseRole, bytes32 scopeHash, address holder)
        external
        override
    {
        uint8 grantClass = _scopableGrantClass(baseRole);
        _checkRoleActor(baseRole, grantClass);
        _grant(
            scopedRole(baseRole, scopeHash),
            holder,
            grantClass,
            baseRole == StreamRoles.ROLE_TERMINAL_FREEZE_VETO
        );
    }

    /// @inheritdoc IStreamRoleRegistry
    function revokeScopedRole(bytes32 baseRole, bytes32 scopeHash, address holder)
        external
        override
    {
        uint8 grantClass = _scopableGrantClass(baseRole);
        _checkRoleActor(baseRole, grantClass);
        _revoke(
            scopedRole(baseRole, scopeHash),
            holder,
            grantClass,
            baseRole == StreamRoles.ROLE_TERMINAL_FREEZE_VETO
        );
    }

    function _grant(bytes32 role, address holder, uint8 grantClass, bool terminalVetoRole) private {
        if (holder == address(0)) {
            revert ZeroRoleHolder(role);
        }
        if (_roleHolderIndex[role][holder] != 0) {
            revert RoleAlreadyGranted(role, holder);
        }
        if (terminalVetoRole) {
            if (holder.code.length == 0) {
                revert TerminalFreezeVetoGuardianMustHaveCode(holder);
            }
            if (_isEip7702DelegatedEOA(holder)) {
                revert TerminalFreezeVetoGuardianDelegatedEOA(holder);
            }
            if (_roleHolders[role].length >= 16) {
                revert TerminalFreezeVetoGuardianCap(_roleHolders[role].length);
            }
            IStreamGovernanceExecutor executor = IStreamGovernanceExecutor(owner());
            // Identity disjointness needs only the root address; the executor
            // validates the code hash and revision at its control boundary.
            // slither-disable-next-line unused-return
            (address governanceRoot,,) = executor.governanceRootState();
            if (executor.isProposer(holder) || holder == governanceRoot) {
                revert GovernanceIdentityRoleOverlap(holder, StreamRoles.ROLE_TERMINAL_FREEZE_VETO);
            }
        }
        _checkDisjointness(role, holder);
        bytes32 governanceActionId = bytes32(0);
        if (msg.sender == owner()) {
            governanceActionId = _requireGovernanceRoleTransition(role, holder, false, true);
        }
        _roleHolders[role].push(holder);
        _roleHolderIndex[role][holder] = _roleHolders[role].length;
        if (terminalVetoRole) _terminalVetoMembershipCount[holder] += 1;
        if (role == StreamRoles.ROLE_TERMINAL_FREEZE_VETO && _roleHolders[role].length >= 2) {
            _terminalGuardianFloorActivated = true;
        }
        _appendRoleMutation(role, holder, true, governanceActionId);
        emit StreamRoleGranted(
            SCHEMA_VERSION, role, holder, grantClass, msg.sender, governanceActionId
        );
    }

    function _revoke(bytes32 role, address holder, uint8 grantClass, bool terminalVetoRole)
        private
    {
        uint256 indexPlusOne = _roleHolderIndex[role][holder];
        if (indexPlusOne == 0) {
            revert RoleNotGranted(role, holder);
        }
        if (
            role == StreamRoles.ROLE_TERMINAL_FREEZE_VETO && _terminalGuardianFloorActivated
                && _roleHolders[role].length <= 2
        ) {
            revert TerminalFreezeVetoGuardianFloor(_roleHolders[role].length);
        }
        bytes32 governanceActionId = bytes32(0);
        if (msg.sender == owner()) {
            governanceActionId = _requireGovernanceRoleTransition(role, holder, true, false);
        }
        address[] storage holders = _roleHolders[role];
        uint256 index = indexPlusOne - 1;
        uint256 lastIndex = holders.length - 1;
        if (index != lastIndex) {
            address moved = holders[lastIndex];
            holders[index] = moved;
            _roleHolderIndex[role][moved] = indexPlusOne;
        }
        holders.pop();
        delete _roleHolderIndex[role][holder];
        if (terminalVetoRole) _terminalVetoMembershipCount[holder] -= 1;
        _appendRoleMutation(role, holder, false, governanceActionId);
        emit StreamRoleRevoked(
            SCHEMA_VERSION, role, holder, grantClass, msg.sender, governanceActionId
        );
    }

    /// @inheritdoc IStreamRoleRegistry
    function registerRoleManager(address account, bool enabled) external override onlyOwner {
        if (account == address(0)) {
            revert ZeroRoleHolder(bytes32(0));
        }
        bool currentEnabled = _roleManagers[account];
        if (currentEnabled == enabled) revert RoleManagerConfigNoOp(account, enabled);
        bytes32 governanceActionId = _requireGovernanceRoleTransition(
            STREAM_ROLE_MANAGER_CONFIG_V1, account, currentEnabled, enabled
        );
        _roleManagers[account] = enabled;
        (bytes32 configChainHash, uint64 configRevision) =
            _appendRoleManagerConfigMutation(account, enabled);
        _appendRoleMutation(STREAM_ROLE_MANAGER_CONFIG_V1, account, enabled, governanceActionId);
        emit RoleManagerUpdated(
            SCHEMA_VERSION,
            account,
            enabled,
            msg.sender,
            configChainHash,
            configRevision,
            governanceActionId
        );
    }

    /// @inheritdoc IStreamRoleRegistry
    function hasRole(bytes32 role, address account) public view override returns (bool) {
        return _roleHolderIndex[role][account] != 0;
    }

    /// @inheritdoc IStreamRoleRegistry
    function hasAnyTerminalFreezeVetoRole(address account) external view override returns (bool) {
        return _terminalVetoMembershipCount[account] != 0;
    }

    /// @inheritdoc IStreamRoleRegistry
    function terminalFreezeVetoMembershipCount(address account)
        external
        view
        override
        returns (uint256)
    {
        return _terminalVetoMembershipCount[account];
    }

    /// @inheritdoc IStreamRoleRegistry
    function roleHolderCount(bytes32 role) public view override returns (uint256) {
        return _roleHolders[role].length;
    }

    /// @inheritdoc IStreamRoleRegistry
    function roleHolderAt(bytes32 role, uint256 index) public view override returns (address) {
        if (index >= _roleHolders[role].length) {
            revert RoleHolderIndexOutOfBounds(role, index);
        }
        return _roleHolders[role][index];
    }

    /// @inheritdoc IStreamRoleRegistry
    function roleMutationState(bytes32 role)
        external
        view
        override
        returns (bytes32 chainHash, uint64 revision)
    {
        return (_roleMutationChain[role], _roleMutationRevision[role]);
    }

    /// @inheritdoc IStreamRoleRegistry
    function scopedRoleMutationState(bytes32 baseRole, bytes32 scopeHash)
        external
        view
        override
        returns (bytes32 role, bytes32 chainHash, uint64 revision)
    {
        role = scopedRole(baseRole, scopeHash);
        if (!isScopableRole(baseRole)) revert UnknownRole(baseRole);
        chainHash = _roleMutationChain[role];
        revision = _roleMutationRevision[role];
    }

    /// @inheritdoc IStreamRoleRegistry
    function globalRoleMutationState()
        external
        view
        override
        returns (bytes32 chainHash, uint64 revision)
    {
        return (_globalRoleMutationChain, _globalRoleMutationRevision);
    }

    /// @inheritdoc IStreamRoleRegistry
    function resolveRole(bytes32 role) public view override returns (address holder) {
        uint256 count = _roleHolders[role].length;
        if (count == 0) {
            revert RoleUnresolved(role);
        }
        if (count > 1) {
            revert AmbiguousRoleResolution(role, count);
        }
        return _roleHolders[role][0];
    }

    /// @inheritdoc IStreamRoleRegistry
    function emergencyRecipient() external view override returns (address) {
        return resolveRole(StreamRoles.ROLE_EMERGENCY_RECIPIENT);
    }

    /// @inheritdoc IStreamRoleRegistry
    function roleGrantClass(bytes32 role) public pure override returns (uint8) {
        uint8 grantClass = _grantClassOrZero(role);
        if (grantClass == 0) {
            revert UnknownRole(role);
        }
        return grantClass;
    }

    /// @inheritdoc IStreamRoleRegistry
    function isKnownRole(bytes32 role) public pure override returns (bool) {
        return _grantClassOrZero(role) != 0;
    }

    /// @inheritdoc IStreamRoleRegistry
    function roleRedundancy(bytes32 role)
        public
        view
        override
        returns (uint256 holderCount, uint256 contractHolderCount)
    {
        address[] storage holders = _roleHolders[role];
        holderCount = holders.length;
        for (uint256 i = 0; i < holderCount; i++) {
            if (holders[i].code.length > 0 && !_isEip7702DelegatedEOA(holders[i])) {
                contractHolderCount++;
            }
        }
    }

    /// @inheritdoc IStreamRoleRegistry
    function isRoleRedundant(bytes32 role) external view override returns (bool) {
        (uint256 holderCount, uint256 contractHolderCount) = roleRedundancy(role);
        return holderCount >= 2 && contractHolderCount == holderCount;
    }

    /// @inheritdoc IStreamRoleRegistry
    function isRoleManager(address account) external view override returns (bool) {
        return _roleManagers[account];
    }

    /// @notice Returns the manager-address-scoped exact governance chain.
    /// @dev This chain is deliberately independent from operational-role and
    ///      global audit mutations so a compromised manager cannot stale its
    ///      own root-initiated removal.
    function roleManagerConfigMutationState(address account)
        external
        view
        override
        returns (bytes32 chainHash, uint64 revision)
    {
        return (_roleManagerConfigChain[account], _roleManagerConfigRevision[account]);
    }

    /// @inheritdoc IStreamRoleRegistry
    function scopedRole(bytes32 baseRole, bytes32 scopeHash)
        public
        pure
        override
        returns (bytes32)
    {
        return keccak256(abi.encode(baseRole, scopeHash));
    }

    /// @inheritdoc IStreamRoleRegistry
    function isScopableRole(bytes32 baseRole) public pure override returns (bool) {
        // Only per-scope terminal-freeze veto guardians are scopable today
        // (ADR 0004 [GOV-WINDOWS] veto surface). Extending the set amends this.
        return baseRole == StreamRoles.ROLE_TERMINAL_FREEZE_VETO;
    }

    function _scopableGrantClass(bytes32 baseRole) private pure returns (uint8) {
        if (!isScopableRole(baseRole)) {
            revert UnknownRole(baseRole);
        }
        return roleGrantClass(baseRole);
    }

    function _checkRoleActor(bytes32 role, uint8 grantClass) private view {
        if (msg.sender == owner()) {
            return;
        }
        if (grantClass == StreamRoles.GRANT_CLASS_OPERATIONAL && _roleManagers[msg.sender]) {
            return;
        }
        revert RoleActorNotAuthorized(role, msg.sender);
    }

    function _appendRoleMutation(
        bytes32 role,
        address holder,
        bool granted,
        bytes32 governanceActionId
    ) private {
        uint64 roleRevision = _roleMutationRevision[role];
        uint64 globalRevision = _globalRoleMutationRevision;
        if (roleRevision == type(uint64).max || globalRevision == type(uint64).max) {
            revert RoleMutationRevisionOverflow(role);
        }
        unchecked {
            roleRevision += 1;
            globalRevision += 1;
        }
        bytes32 roleChainHash = keccak256(
            abi.encode(
                STREAM_ROLE_MUTATION_V1,
                _roleMutationChain[role],
                uint256(block.chainid),
                address(this),
                role,
                holder,
                granted,
                roleRevision
            )
        );
        bytes32 globalChainHash = keccak256(
            abi.encode(
                STREAM_GLOBAL_ROLE_MUTATION_V1,
                _globalRoleMutationChain,
                uint256(block.chainid),
                address(this),
                role,
                holder,
                granted,
                globalRevision
            )
        );
        _roleMutationChain[role] = roleChainHash;
        _roleMutationRevision[role] = roleRevision;
        _globalRoleMutationChain = globalChainHash;
        _globalRoleMutationRevision = globalRevision;
        emit RoleMutationCommitted(
            SCHEMA_VERSION,
            role,
            holder,
            granted,
            roleChainHash,
            roleRevision,
            globalChainHash,
            globalRevision,
            governanceActionId
        );
    }

    function _appendRoleManagerConfigMutation(address account, bool enabled)
        private
        returns (bytes32 chainHash, uint64 revision)
    {
        revision = _roleManagerConfigRevision[account];
        if (revision == type(uint64).max) {
            revert RoleMutationRevisionOverflow(STREAM_ROLE_MANAGER_CONFIG_V1);
        }
        unchecked {
            revision += 1;
        }
        chainHash = keccak256(
            abi.encode(
                STREAM_ROLE_MANAGER_CONFIG_MUTATION_V1,
                _roleManagerConfigChain[account],
                uint256(block.chainid),
                address(this),
                account,
                enabled,
                revision
            )
        );
        _roleManagerConfigChain[account] = chainHash;
        _roleManagerConfigRevision[account] = revision;
    }

    function _requireGovernanceRoleTransition(
        bytes32 role,
        address holder,
        bool oldGranted,
        bool newGranted
    ) private view returns (bytes32 governanceActionId) {
        (
            bool executing,
            bytes32 actionId,
            uint8 actionClass,
            bytes32 actualScopeHash,
            bytes32 actualOldStateHash,
            bytes32 actualNewStateHash
        ) = IStreamGovernanceExecutor(owner()).currentAction();
        if (!executing) {
            if (
                role == StreamRoles.ROLE_TERMINAL_FREEZE_VETO && !oldGranted && newGranted
                    && _isBootstrapGuardianGrant()
            ) return bytes32(0);
            revert RoleGovernanceActionNotExecuting();
        }
        if (actionId == bytes32(0)) revert RoleGovernanceActionIdZero();
        uint8 expectedClass = role == STREAM_ROLE_MANAGER_CONFIG_V1 && !newGranted
            ? IMMEDIATE_TIGHTENING
            : DELAYED_LOOSENING;
        if (actionClass != expectedClass) {
            revert RoleGovernanceActionClassMismatch(expectedClass, actionClass);
        }

        bytes32 expectedScopeHash = keccak256(
            abi.encode(
                STREAM_ROLE_MUTATION_SCOPE_V1, uint256(block.chainid), address(this), role, holder
            )
        );
        bytes32 expectedOldStateHash;
        bytes32 expectedNewStateHash;
        if (role == STREAM_ROLE_MANAGER_CONFIG_V1) {
            (expectedOldStateHash, expectedNewStateHash) = _roleManagerTransitionStateHashes(
                expectedScopeHash, holder, oldGranted, newGranted
            );
        } else {
            (expectedOldStateHash, expectedNewStateHash) =
                _roleTransitionStateHashes(expectedScopeHash, role, holder, oldGranted, newGranted);
        }
        if (actualScopeHash != expectedScopeHash) {
            revert RoleGovernanceScopeHashMismatch(expectedScopeHash, actualScopeHash);
        }
        if (actualOldStateHash != expectedOldStateHash) {
            revert RoleGovernanceOldStateHashMismatch(expectedOldStateHash, actualOldStateHash);
        }
        if (actualNewStateHash != expectedNewStateHash) {
            revert RoleGovernanceNewStateHashMismatch(expectedNewStateHash, actualNewStateHash);
        }
        return actionId;
    }

    function _roleTransitionStateHashes(
        bytes32 scopeHash,
        bytes32 role,
        address holder,
        bool oldGranted,
        bool newGranted
    ) private view returns (bytes32 oldStateHash, bytes32 newStateHash) {
        uint64 roleRevision = _roleMutationRevision[role];
        uint64 globalRevision = _globalRoleMutationRevision;
        if (roleRevision == type(uint64).max || globalRevision == type(uint64).max) {
            revert RoleMutationRevisionOverflow(role);
        }
        uint64 nextRoleRevision;
        uint64 nextGlobalRevision;
        unchecked {
            nextRoleRevision = roleRevision + 1;
            nextGlobalRevision = globalRevision + 1;
        }
        bytes32 roleChainHash = _roleMutationChain[role];
        bytes32 globalChainHash = _globalRoleMutationChain;
        bytes32 nextRoleChainHash = keccak256(
            abi.encode(
                STREAM_ROLE_MUTATION_V1,
                roleChainHash,
                uint256(block.chainid),
                address(this),
                role,
                holder,
                newGranted,
                nextRoleRevision
            )
        );
        bytes32 nextGlobalChainHash = keccak256(
            abi.encode(
                STREAM_GLOBAL_ROLE_MUTATION_V1,
                globalChainHash,
                uint256(block.chainid),
                address(this),
                role,
                holder,
                newGranted,
                nextGlobalRevision
            )
        );
        oldStateHash = _roleMutationStateHash(
            scopeHash, oldGranted, roleChainHash, roleRevision, globalChainHash, globalRevision
        );
        newStateHash = _roleMutationStateHash(
            scopeHash,
            newGranted,
            nextRoleChainHash,
            nextRoleRevision,
            nextGlobalChainHash,
            nextGlobalRevision
        );
    }

    /// @dev Manager enablement is delayed, while removal is an immediate
    ///      tightening. Its exact transition deliberately excludes the global
    ///      role chain: a compromised manager may advance that chain through
    ///      direct operational writes and must not be able to censor its own
    ///      root-initiated removal. The manager-address-scoped config chain
    ///      remains monotonic and cannot be touched by a RoleManager.
    function _roleManagerTransitionStateHashes(
        bytes32 scopeHash,
        address account,
        bool oldEnabled,
        bool newEnabled
    ) private view returns (bytes32 oldStateHash, bytes32 newStateHash) {
        uint64 revision = _roleManagerConfigRevision[account];
        if (revision == type(uint64).max) {
            revert RoleMutationRevisionOverflow(STREAM_ROLE_MANAGER_CONFIG_V1);
        }
        uint64 nextRevision;
        unchecked {
            nextRevision = revision + 1;
        }
        bytes32 chainHash = _roleManagerConfigChain[account];
        bytes32 nextChainHash = keccak256(
            abi.encode(
                STREAM_ROLE_MANAGER_CONFIG_MUTATION_V1,
                chainHash,
                uint256(block.chainid),
                address(this),
                account,
                newEnabled,
                nextRevision
            )
        );
        oldStateHash = _roleManagerConfigStateHash(scopeHash, oldEnabled, chainHash, revision);
        newStateHash =
            _roleManagerConfigStateHash(scopeHash, newEnabled, nextChainHash, nextRevision);
    }

    function _roleManagerConfigStateHash(
        bytes32 scopeHash,
        bool enabled,
        bytes32 chainHash,
        uint64 revision
    ) private view returns (bytes32) {
        return keccak256(
            abi.encode(
                STREAM_ROLE_MANAGER_CONFIG_STATE_V1,
                uint256(block.chainid),
                address(this),
                scopeHash,
                enabled,
                chainHash,
                revision
            )
        );
    }

    function _roleMutationStateHash(
        bytes32 scopeHash,
        bool granted,
        bytes32 roleChainHash,
        uint64 roleRevision,
        bytes32 globalChainHash,
        uint64 globalRevision
    ) private view returns (bytes32) {
        return keccak256(
            abi.encode(
                STREAM_ROLE_MUTATION_STATE_V1,
                uint256(block.chainid),
                address(this),
                scopeHash,
                granted,
                roleChainHash,
                roleRevision,
                globalChainHash,
                globalRevision
            )
        );
    }

    /// @dev The only owner-originated mutation outside an executing action is
    ///      the initial terminal-veto population performed from the Executor's
    ///      one-way bootstrap bind. The Executor has already bound this exact
    ///      registry in memory/storage, while `bound` and `sealed` are still
    ///      false. Once bind completes this exception can never be re-entered.
    function _isBootstrapGuardianGrant() private view returns (bool) {
        (bool success, bytes memory result) =
            owner().staticcall(abi.encodeWithSelector(SYSTEM_MANIFEST_BOOTSTRAP_STATE_SELECTOR));
        if (!success || result.length < 96) return false;
        (bool bound, bool isSealed, address roleRegistry) =
            abi.decode(result, (bool, bool, address));
        return !bound && !isSealed && roleRegistry == address(this);
    }

    /// @dev [GOV-WINDOWS] rule 3: pause guardians cannot unpause and unpause
    ///     holders cannot pause; one account may never hold both authorities.
    function _checkDisjointness(bytes32 role, address holder) private view {
        if (role == StreamRoles.ROLE_PAUSE_GUARDIAN && hasRole(StreamRoles.ROLE_UNPAUSE, holder)) {
            revert DisjointRoleConflict(role, StreamRoles.ROLE_UNPAUSE, holder);
        }
        if (role == StreamRoles.ROLE_UNPAUSE && hasRole(StreamRoles.ROLE_PAUSE_GUARDIAN, holder)) {
            revert DisjointRoleConflict(role, StreamRoles.ROLE_PAUSE_GUARDIAN, holder);
        }
    }

    /// @dev EIP-7702 designations are exactly `0xef0100 || delegate` (23
    ///      bytes). They expose code but remain EOAs for the emergency-holder
    ///      classification pinned by [GOV-WINDOWS].
    function _isEip7702DelegatedEOA(address account) private view returns (bool delegated) {
        if (account.code.length != 23) return false;
        bytes3 prefix;
        assembly ("memory-safe") {
            extcodecopy(account, 0, 0, 3)
            prefix := mload(0)
        }
        return prefix == 0xef0100;
    }

    function _grantClassOrZero(bytes32 role) private pure returns (uint8) {
        if (
            role == StreamRoles.ROLE_PAUSE_GUARDIAN || role == StreamRoles.ROLE_UNPAUSE
                || role == StreamRoles.ROLE_COLLECTION_FINALITY_ADMIN
                || role == StreamRoles.ROLE_TERMINAL_FREEZE_VETO
                || role == StreamRoles.ROLE_ATTRIBUTION_ARBITER
                || role == StreamRoles.ROLE_ARTIST_DORMANCY_ADMIN
                || role == StreamRoles.ROLE_ATTRIBUTION_APPEAL
                || role == StreamRoles.ROLE_EMERGENCY_RECIPIENT || role == StreamRoles.ROLE_TREASURY
        ) {
            return StreamRoles.GRANT_CLASS_ROOT;
        }
        if (
            role == StreamRoles.ROLE_ENTROPY_INCIDENT_DECLARER
                || role == StreamRoles.ROLE_ENTROPY_REVEAL_OWNER
                || role == StreamRoles.ROLE_ARTIST_REGISTRY_ADMIN
                || role == StreamRoles.ROLE_FIXITY_OPERATOR
                || role == StreamRoles.ROLE_EXPORT_PUBLISHER
                || role == StreamRoles.ROLE_CLAIM_ROUTER_OPERATOR
                || role == StreamRoles.ROLE_ENTROPY_ADMIN
        ) {
            return StreamRoles.GRANT_CLASS_OPERATIONAL;
        }
        return 0;
    }
}

