// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/mint/IStreamERC20FixedPriceSaleAdapter.sol";
import "../../interfaces/stream/mint/IStreamMintReads.sol";
import "../../interfaces/stream/revenue/IStreamRevenueResolver.sol";
import "../../interfaces/stream/revenue/IStreamSplitFactory.sol";
import "../../interfaces/stream/artist/IStreamCollectionArtistRegistry.sol";
import "../../vendor/openzeppelin/ERC165.sol";
import "../../interfaces/standards/IERC20.sol";
import "../revenue/StreamPaymentIntentVerifier.sol";

/// @notice One creator/platform-authorized ERC-20 purchase funds a verified split and mints atomically.
/// @dev The adapter itself pulls allowances. Relayers require payer-signed intent; direct payers
///      remain bounded by signed, immutable sale terms. This current fixed-profile lane is not
///      the universal official settlement/escrow implementation tracked by issue #694.
contract StreamERC20FixedPriceSaleAdapter is
    IStreamERC20FixedPriceSaleAdapter,
    StreamPaymentIntentVerifier,
    ERC165
{
    bytes32 public constant SALE_AUTHORIZATION_TYPEHASH = keccak256(
        "ERC20SaleAuthorization(bytes32 saleId,bytes32 saleConfigHash,address payer,address recipient,address artist,bytes32 tokenDataHash,bytes32 mintCommitment,bytes32 nonce,uint64 deadline,uint64 signerEpoch)"
    );
    bytes32 public constant STREAM_SALE_V1 = keccak256("6529STREAM_SALE_V1");
    bytes32 public constant PRIMARY_POLICY_DOMAIN = keccak256("6529STREAM_PRIMARY_POLICY_V1");
    bytes32 private constant CONFIG_DOMAIN =
        keccak256("6529STREAM_CURRENT_ERC20_FIXED_PRICE_CONFIG_V1");
    bytes32 private constant NONCE_DOMAIN = keccak256("6529STREAM_ERC20_SALE_NONCE_V1");

    IStreamMintManager public immutable override mintManager;
    IStreamRevenueResolver public immutable override revenueResolver;
    IStreamSplitFactory public immutable override splitFactory;
    IStreamAssetPolicyRegistry public immutable override assetPolicyRegistry;
    IStreamCollectionArtistRegistry public immutable override artistRegistry;
    address public override platformSigner;
    uint64 public override signerEpoch = 1;
    uint256 public override nextSaleNonce = 1;
    bool public override paused;
    mapping(bytes32 => SaleRecord) private _sales;
    mapping(address => mapping(bytes32 => bool)) public override authorizationUsed;
    mapping(bytes32 => mapping(address => uint256)) public override proceeds;
    mapping(address => uint256) public override totalProceeds;

    constructor(
        IStreamMintManager manager_,
        IStreamRevenueResolver resolver_,
        address platformSigner_,
        IStreamCollectionArtistRegistry artists_
    ) {
        if (
            address(manager_).code.length == 0 || address(resolver_).code.length == 0
                || platformSigner_ == address(0) || !resolver_.isStreamRevenueResolver()
                || address(artists_).code.length == 0
                || !artists_.supportsInterface(type(IStreamCollectionArtistRegistry).interfaceId)
                || artists_.supportsInterface(0xffffffff)
                || address(IStreamMintReads(address(manager_)).core()) != artists_.core()
        ) {
            revert InvalidSaleConfiguration();
        }
        IStreamSplitFactory factory_ = IStreamSplitFactory(resolver_.splitFactory());
        if (address(factory_).code.length == 0) revert InvalidSaleConfiguration();
        IStreamAssetPolicyRegistry assets_ = factory_.assetPolicyRegistry();
        if (
            address(assets_).code.length == 0 || !assets_.isStreamAssetPolicyRegistry()
                || assets_.ASSET_STATUS_ACTIVE() != 1
        ) revert InvalidSaleConfiguration();
        mintManager = manager_;
        revenueResolver = resolver_;
        splitFactory = factory_;
        assetPolicyRegistry = assets_;
        artistRegistry = artists_;
        platformSigner = platformSigner_;
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC165, IERC165)
        returns (bool)
    {
        return interfaceId == type(IStreamERC20FixedPriceSaleAdapter).interfaceId
            || interfaceId == type(IStreamPaymentIntentVerifier).interfaceId
            || super.supportsInterface(interfaceId);
    }

    /// @notice Rotates the platform signer and invalidates outstanding sale signatures by epoch.
    function setPlatformSigner(address signer) external override onlyOwner nonReentrant {
        if (signer == address(0)) revert InvalidSaleConfiguration();
        platformSigner = signer;
        signerEpoch += 1;
        emit PlatformSignerChanged(signer, signerEpoch);
    }

    /// @notice Stops purchases without preventing payer or artist nonce revocation.
    function setPaused(bool value) external override onlyOwner nonReentrant {
        paused = value;
        emit SalesPauseChanged(value);
    }

    function saleIdFor(uint256 collectionId, bytes32 phaseId, uint256 saleNonce)
        public
        view
        override
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                STREAM_SALE_V1,
                block.chainid,
                address(this),
                uint8(0),
                collectionId,
                phaseId,
                saleNonce
            )
        );
    }

    function registerSale(SaleConfig calldata config)
        external
        override
        onlyOwner
        nonReentrant
        returns (bytes32 saleId)
    {
        if (
            config.collectionId == 0 || config.phaseId == bytes32(0)
                || config.revenueClass == bytes32(0) || config.price == 0
                || config.endsAt <= config.startsAt || config.endsAt < block.timestamp
                || config.mintPolicyHash == bytes32(0)
                || config.expectedPrimaryPolicyHash == bytes32(0)
                || IStreamMintReads(address(mintManager))
                        .phasePolicyHash(config.collectionId, config.phaseId)
                    != config.mintPolicyHash
        ) {
            revert InvalidSaleConfiguration();
        }
        _requireActiveAsset(config.asset);
        (bytes32 policy,,) = primaryPolicy(config.collectionId, config.revenueClass);
        if (policy != config.expectedPrimaryPolicyHash) {
            revert PrimaryPolicyMismatch(config.expectedPrimaryPolicyHash, policy);
        }
        uint256 nonce = nextSaleNonce++;
        saleId = saleIdFor(config.collectionId, config.phaseId, nonce);
        bytes32 configHash = keccak256(abi.encode(CONFIG_DOMAIN, saleId, config));
        _sales[saleId] = SaleRecord(config, nonce, configHash, false);
        emit SaleConfigured(saleId, config.collectionId, config.phaseId, nonce, configHash);
    }

    function saleRecord(bytes32 saleId) external view override returns (SaleRecord memory) {
        return _sales[saleId];
    }

    function cancelSale(bytes32 saleId) external override onlyOwner nonReentrant {
        SaleRecord storage record = _sales[saleId];
        if (record.saleNonce == 0 || record.cancelled) revert SaleUnavailable(saleId);
        record.cancelled = true;
        emit SaleCancelled(saleId);
    }

    function cancelAuthorization(bytes32 nonce) external override nonReentrant {
        if (authorizationUsed[msg.sender][nonce]) revert SaleAuthorizationUsed(msg.sender, nonce);
        authorizationUsed[msg.sender][nonce] = true;
        emit SaleAuthorizationCancelled(msg.sender, nonce);
    }

    function primaryPolicy(uint256 collectionId, bytes32 revenueClass)
        public
        view
        override
        returns (bytes32 policyHash, bytes32 profileId, address wallet)
    {
        IStreamRevenueResolver.ResolvedPrimaryAssignment memory assignment =
            revenueResolver.resolvePrimaryAssignment(collectionId, 0, revenueClass);
        if (
            !assignment.exists || assignment.assignmentType != 1 || assignment.scope > 1
                || assignment.templateId != bytes32(0) || assignment.profileId == bytes32(0)
                || assignment.assignmentHash == bytes32(0)
        ) revert UnsupportedPrimaryAssignment();
        profileId = assignment.profileId;
        if (!splitFactory.splitWalletExists(profileId)) revert UnsupportedPrimaryAssignment();
        wallet = splitFactory.walletFor(profileId);
        policyHash = keccak256(
            abi.encode(
                PRIMARY_POLICY_DOMAIN,
                block.chainid,
                address(revenueResolver),
                revenueClass,
                collectionId,
                uint256(0),
                bytes32(0),
                profileId,
                wallet,
                assignment.assignmentHash
            )
        );
    }

    function authorizationId(address artist, bytes32 nonce) public view override returns (bytes32) {
        return keccak256(abi.encode(NONCE_DOMAIN, block.chainid, address(this), artist, nonce));
    }

    function authorizationDigest(SaleAuthorization calldata authorization)
        public
        view
        override
        returns (bytes32)
    {
        return _typedDigest(keccak256(abi.encode(SALE_AUTHORIZATION_TYPEHASH, authorization)));
    }

    struct Execution {
        SaleConfig config;
        bytes32 digest;
        bytes32 authorizationId;
        bytes32 profileId;
        address wallet;
        bytes32 operationRoot;
        bytes32 operationId;
    }

    function buy(
        SaleAuthorization calldata authorization,
        bytes calldata tokenData,
        bytes calldata platformSignature,
        bytes calldata artistSignature,
        PaymentIntent calldata intent,
        bytes calldata payerSignature
    ) external override nonReentrant returns (uint256 tokenId, bytes32 operationRoot) {
        Execution memory execution =
            _validate(authorization, tokenData, platformSignature, artistSignature);
        return _executePurchase(authorization, tokenData, intent, payerSignature, execution);
    }

    function _executePurchase(
        SaleAuthorization calldata authorization,
        bytes calldata tokenData,
        PaymentIntent calldata intent,
        bytes calldata payerSignature,
        Execution memory execution
    ) private returns (uint256 tokenId, bytes32 operationRoot) {
        IStreamMintManager.MintBatch memory batch = _mintBatch(authorization, tokenData, execution);
        bytes32[] memory expectedIds;
        (execution.operationRoot, expectedIds) =
            IStreamMintReads(address(mintManager)).previewSingleStepMintOperation(batch, "");
        if (
            execution.operationRoot == bytes32(0) || expectedIds.length != 1
                || expectedIds[0] == bytes32(0)
        ) {
            revert SaleMintResultInvalid();
        }
        execution.operationId = expectedIds[0];
        _authorizePayment(
            PaymentTerms(
                authorization.payer,
                execution.config.asset,
                execution.config.price,
                authorization.saleId,
                execution.config.expectedPrimaryPolicyHash
            ),
            intent,
            payerSignature
        );
        authorizationUsed[authorization.artist][authorization.nonce] = true;
        proceeds[execution.profileId][execution.config.asset] += execution.config.price;
        totalProceeds[execution.config.asset] += execution.config.price;
        _pay(authorization.payer, execution);
        uint256[] memory tokenIds;
        bytes32[] memory operationIds;
        (tokenIds, operationRoot, operationIds) = mintManager.executeSingleStepMint(batch, "");
        if (
            tokenIds.length != 1 || tokenIds[0] == 0 || operationRoot != execution.operationRoot
                || operationIds.length != 1 || operationIds[0] != execution.operationId
        ) revert SaleMintResultInvalid();
        tokenId = tokenIds[0];
        _emitSale(authorization, execution, tokenId);
    }

    function _validate(
        SaleAuthorization calldata authorization,
        bytes calldata tokenData,
        bytes calldata platformSignature,
        bytes calldata artistSignature
    ) private view returns (Execution memory e) {
        SaleRecord storage record = _sales[authorization.saleId];
        if (
            paused || record.saleNonce == 0 || record.cancelled
                || block.timestamp < record.config.startsAt
                || block.timestamp > record.config.endsAt
        ) revert SaleUnavailable(authorization.saleId);
        if (
            authorization.saleConfigHash != record.configHash || authorization.payer == address(0)
                || authorization.payer == address(this) || authorization.recipient == address(0)
                || authorization.artist == address(0) || authorization.mintCommitment == bytes32(0)
                || authorization.signerEpoch != signerEpoch
                || block.timestamp > authorization.deadline
                || keccak256(tokenData) != authorization.tokenDataHash
        ) revert InvalidSaleAuthorization();
        if (authorizationUsed[authorization.artist][authorization.nonce]) {
            revert SaleAuthorizationUsed(authorization.artist, authorization.nonce);
        }
        e.config = record.config;
        artistRegistry.requireArtist(e.config.collectionId, authorization.artist);
        e.digest = authorizationDigest(authorization);
        if (!_validSignature(platformSigner, e.digest, platformSignature)) {
            revert InvalidSaleSignature(platformSigner);
        }
        if (!_validSignature(authorization.artist, e.digest, artistSignature)) {
            revert InvalidSaleSignature(authorization.artist);
        }
        _requireActiveAsset(e.config.asset);
        bytes32 policy;
        (policy, e.profileId, e.wallet) =
            primaryPolicy(e.config.collectionId, e.config.revenueClass);
        if (policy != e.config.expectedPrimaryPolicyHash) {
            revert PrimaryPolicyMismatch(e.config.expectedPrimaryPolicyHash, policy);
        }
        if (authorization.payer == e.wallet) revert InvalidSaleAuthorization();
        e.authorizationId = authorizationId(authorization.artist, authorization.nonce);
    }

    function _mintBatch(SaleAuthorization calldata a, bytes calldata data, Execution memory e)
        private
        pure
        returns (IStreamMintManager.MintBatch memory batch)
    {
        batch.collectionId = e.config.collectionId;
        batch.phaseId = e.config.phaseId;
        batch.payer = a.payer;
        batch.initialRecipients = new address[](1);
        batch.beneficiaries = new address[](1);
        batch.tokenData = new bytes[](1);
        batch.mintCommitments = new bytes32[](1);
        batch.initialRecipients[0] = a.recipient;
        batch.beneficiaries[0] = a.recipient;
        batch.tokenData[0] = data;
        batch.mintCommitments[0] = a.mintCommitment;
        batch.expectedPolicyHash = e.config.mintPolicyHash;
        batch.authorizationId = e.authorizationId;
        batch.contextHash = e.digest;
    }

    function _emitSale(SaleAuthorization calldata a, Execution memory e, uint256 tokenId) private {
        emit ERC20SaleSettled(
            a.saleId,
            e.operationRoot,
            tokenId,
            e.authorizationId,
            e.digest,
            e.profileId,
            e.wallet,
            e.config.asset,
            e.config.price
        );
        emit ERC20SaleParticipants(
            e.authorizationId, a.artist, a.payer, a.recipient, e.config.expectedPrimaryPolicyHash
        );
    }

    function _pay(address payer, Execution memory e) private {
        uint256 startingBalance = _balance(e.config.asset, address(this));
        _transfer(e.config.asset, payer, address(this), e.config.price, true);
        _transfer(e.config.asset, address(this), e.wallet, e.config.price, false);
        if (_balance(e.config.asset, address(this)) != startingBalance) {
            revert ERC20AmountMismatch(e.config.asset);
        }
        _requireActiveAsset(e.config.asset);
        (bytes32 policy,,) = primaryPolicy(e.config.collectionId, e.config.revenueClass);
        if (policy != e.config.expectedPrimaryPolicyHash) {
            revert PrimaryPolicyMismatch(e.config.expectedPrimaryPolicyHash, policy);
        }
    }

    function _requireActiveAsset(address asset) private view {
        if (asset.code.length == 0) revert AssetNotActive(asset);
        address registry = address(assetPolicyRegistry);
        bytes memory data = abi.encodeCall(IStreamAssetPolicyRegistry.assetStatus, (asset));
        bool ok;
        uint256 status;
        if (gasleft() < 50_000) revert AssetNotActive(asset);
        assembly ("memory-safe") {
            let ptr := mload(0x40)
            ok := staticcall(30000, registry, add(data, 32), mload(data), ptr, 32)
            ok := and(ok, eq(returndatasize(), 32))
            status := mload(ptr)
        }
        if (!ok || status != 1) revert AssetNotActive(asset);
    }

    function _balance(address asset, address account) private view returns (uint256 value) {
        bytes memory data = abi.encodeCall(IERC20.balanceOf, (account));
        bool ok;
        assembly ("memory-safe") {
            let ptr := mload(0x40)
            ok := staticcall(gas(), asset, add(data, 32), mload(data), ptr, 32)
            ok := and(ok, eq(returndatasize(), 32))
            value := mload(ptr)
        }
        if (!ok) revert ERC20BalanceReadFailed(asset, account);
    }

    function _transfer(address asset, address from, address to, uint256 amount, bool pull) private {
        uint256 fromBefore = _balance(asset, from);
        uint256 toBefore = _balance(asset, to);
        bytes memory data = pull
            ? abi.encodeCall(IERC20.transferFrom, (from, to, amount))
            : abi.encodeCall(IERC20.transfer, (to, amount));
        bool ok;
        uint256 result;
        assembly ("memory-safe") {
            let ptr := mload(0x40)
            ok := call(gas(), asset, 0, add(data, 32), mload(data), ptr, 32)
            ok := and(ok, eq(returndatasize(), 32))
            result := mload(ptr)
        }
        if (!ok || result != 1) revert ERC20TransferFailed(asset);
        uint256 fromAfter = _balance(asset, from);
        uint256 toAfter = _balance(asset, to);
        if (
            fromAfter > fromBefore || fromBefore - fromAfter != amount || toAfter < toBefore
                || toAfter - toBefore != amount
        ) revert ERC20AmountMismatch(asset);
    }
}

smart-contracts/domains/mint/StreamFixed.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/mint/IStreamFixedPriceSaleAdapter.sol";
import "../../interfaces/stream/mint/IStreamMintManager.sol";
import "../../interfaces/stream/revenue/IStreamSplitFactory.sol";
import "../../interfaces/stream/artist/IStreamCollectionArtistRegistry.sol";
import "../../vendor/openzeppelin/ERC165.sol";
import "../../vendor/openzeppelin/Ownable.sol";
import "../../vendor/openzeppelin/ReentrancyGuard.sol";
import "./StreamSaleSignatures.sol";

/// @notice One signed native sale mints one NFT and funds its immutable split wallet atomically.
/// @dev Both creator and platform approve the complete sale. The wallet is funded before
///      Core invokes a recipient callback. Any later failure rolls back payment and replay state.
contract StreamFixedPriceSaleAdapter is
    IStreamFixedPriceSaleAdapter,
    ERC165,
    Ownable,
    ReentrancyGuard
{
    bytes32 public constant SALE_AUTHORIZATION_TYPEHASH = keccak256(
        "SaleAuthorization(uint256 collectionId,bytes32 phaseId,address payer,address recipient,address artist,bytes32 profileId,bytes32 tokenDataHash,bytes32 mintCommitment,bytes32 mintPolicyHash,uint256 price,bytes32 nonce,uint64 deadline,uint64 signerEpoch)"
    );
    bytes32 private constant DOMAIN_TYPEHASH = keccak256(
        "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
    );
    bytes32 private constant NONCE_DOMAIN = keccak256("6529STREAM_NATIVE_SALE_NONCE_V1");
    bytes32 private constant NAME_HASH = keccak256("6529StreamFixedPriceSale");
    bytes32 private constant VERSION_HASH = keccak256("1");

    IStreamMintManager public immutable mintManager;
    IStreamSplitFactory public immutable splitFactory;
    IStreamCollectionArtistRegistry public immutable artistRegistry;
    address public platformSigner;
    uint64 public signerEpoch = 1;
    bool public paused;
    mapping(address => mapping(bytes32 => bool)) public override authorizationUsed;
    mapping(bytes32 => uint256) public nativeProceeds;
    uint256 public totalNativeProceeds;

    constructor(
        IStreamMintManager mintManager_,
        IStreamSplitFactory splitFactory_,
        address platformSigner_,
        IStreamCollectionArtistRegistry artistRegistry_
    ) {
        if (
            address(mintManager_).code.length == 0 || address(splitFactory_).code.length == 0
                || platformSigner_ == address(0)
        ) revert InvalidSaleConfiguration();
        if (
            address(artistRegistry_).code.length == 0
                || !artistRegistry_.supportsInterface(
                    type(IStreamCollectionArtistRegistry).interfaceId
                ) || artistRegistry_.supportsInterface(0xffffffff)
        ) revert InvalidSaleConfiguration();
        (bool bound, bytes memory coreData) =
            address(mintManager_).staticcall(abi.encodeWithSignature("core()"));
        if (
            !bound || coreData.length != 32
                || abi.decode(coreData, (address)) != artistRegistry_.core()
        ) {
            revert InvalidSaleConfiguration();
        }
        mintManager = mintManager_;
        splitFactory = splitFactory_;
        platformSigner = platformSigner_;
        artistRegistry = artistRegistry_;
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC165, IERC165)
        returns (bool)
    {
        return interfaceId == type(IStreamFixedPriceSaleAdapter).interfaceId
            || super.supportsInterface(interfaceId);
    }

    function setPlatformSigner(address signer) external onlyOwner nonReentrant {
        if (signer == address(0)) revert InvalidSaleConfiguration();
        platformSigner = signer;
        signerEpoch += 1;
        emit SalePlatformSignerChanged(signer, signerEpoch);
    }

    function setPaused(bool paused_) external onlyOwner nonReentrant {
        paused = paused_;
        emit SalesPauseChanged(paused_);
    }

    /// @notice An artist can invalidate an outstanding nonce without disclosing the authorization.
    function cancelAuthorization(bytes32 nonce) external override nonReentrant {
        if (nonce == bytes32(0)) revert InvalidSaleAuthorization();
        if (authorizationUsed[msg.sender][nonce]) revert SaleAlreadyConsumed(msg.sender, nonce);
        authorizationUsed[msg.sender][nonce] = true;
        emit SaleAuthorizationCancelled(msg.sender, nonce);
    }

    function authorizationId(address artist, bytes32 nonce) public view override returns (bytes32) {
        return keccak256(abi.encode(NONCE_DOMAIN, block.chainid, address(this), artist, nonce));
    }

    function domainSeparator() public view returns (bytes32) {
        return keccak256(
            abi.encode(DOMAIN_TYPEHASH, NAME_HASH, VERSION_HASH, block.chainid, address(this))
        );
    }

    function eip712Domain()
        external
        view
        returns (
            bytes1 fields,
            string memory name,
            string memory version,
            uint256 chainId,
            address verifyingContract,
            bytes32 salt,
            uint256[] memory extensions
        )
    {
        return (
            0x0f,
            "6529StreamFixedPriceSale",
            "1",
            block.chainid,
            address(this),
            bytes32(0),
            new uint256[](0)
        );
    }

    function authorizationDigest(SaleAuthorization calldata sale)
        public
        view
        override
        returns (bytes32)
    {
        bytes32 structHash = keccak256(abi.encode(SALE_AUTHORIZATION_TYPEHASH, sale));
        return keccak256(abi.encodePacked(hex"1901", domainSeparator(), structHash));
    }

    function buy(
        SaleAuthorization calldata sale,
        bytes calldata tokenData,
        bytes calldata platformSignature,
        bytes calldata artistSignature
    ) external payable override nonReentrant returns (uint256 tokenId, bytes32 operationRoot) {
        if (paused) revert SalesPaused();
        _validateSale(sale, tokenData);
        artistRegistry.requireArtist(sale.collectionId, sale.artist);
        bytes32 digest = authorizationDigest(sale);
        _requireSignature(platformSigner, digest, platformSignature);
        _requireSignature(sale.artist, digest, artistSignature);
        address wallet = splitFactory.walletFor(sale.profileId);
        if (!splitFactory.splitWalletExists(sale.profileId)) {
            revert InvalidSplitProfile(sale.profileId);
        }

        bytes32 id = authorizationId(sale.artist, sale.nonce);
        IStreamMintManager.MintBatch memory batch = _mintBatch(sale, tokenData, digest, id);
        authorizationUsed[sale.artist][sale.nonce] = true;
        nativeProceeds[sale.profileId] += msg.value;
        totalNativeProceeds += msg.value;
        if (msg.value != 0) {
            (bool deposited,) = payable(wallet).call{ value: msg.value }("");
            if (!deposited) revert SaleDepositFailed(wallet);
        }
        uint256[] memory tokenIds;
        bytes32[] memory operationIds;
        (tokenIds, operationRoot, operationIds) = mintManager.executeSingleStepMint(batch, "");
        if (
            tokenIds.length != 1 || tokenIds[0] == 0 || operationRoot == bytes32(0)
                || operationIds.length != 1 || operationIds[0] == bytes32(0)
        ) revert SaleMintResultInvalid();
        tokenId = tokenIds[0];
        _emitSale(sale, id, digest, tokenId, operationRoot, wallet);
    }

    function _validateSale(SaleAuthorization calldata sale, bytes calldata tokenData) private view {
        if (
            sale.collectionId == 0 || sale.phaseId == bytes32(0) || sale.payer != msg.sender
                || sale.recipient == address(0) || sale.artist == address(0)
                || sale.profileId == bytes32(0) || sale.nonce == bytes32(0)
                || sale.mintPolicyHash == bytes32(0) || sale.mintCommitment == bytes32(0)
                || sale.signerEpoch != signerEpoch || keccak256(tokenData) != sale.tokenDataHash
        ) revert InvalidSaleAuthorization();
        if (block.timestamp > sale.deadline) revert SaleExpired(sale.deadline);
        if (msg.value != sale.price) revert IncorrectSaleValue(sale.price, msg.value);
        if (authorizationUsed[sale.artist][sale.nonce]) {
            revert SaleAlreadyConsumed(sale.artist, sale.nonce);
        }
    }

    function _mintBatch(
        SaleAuthorization calldata sale,
        bytes calldata tokenData,
        bytes32 digest,
        bytes32 id
    ) private pure returns (IStreamMintManager.MintBatch memory batch) {
        batch.collectionId = sale.collectionId;
        batch.phaseId = sale.phaseId;
        batch.payer = sale.payer;
        batch.initialRecipients = new address[](1);
        batch.beneficiaries = new address[](1);
        batch.tokenData = new bytes[](1);
        batch.mintCommitments = new bytes32[](1);
        batch.initialRecipients[0] = sale.recipient;
        batch.beneficiaries[0] = sale.recipient;
        batch.tokenData[0] = tokenData;
        batch.mintCommitments[0] = sale.mintCommitment;
        batch.expectedPolicyHash = sale.mintPolicyHash;
        batch.authorizationId = id;
        batch.contextHash = digest;
    }

    function _emitSale(
        SaleAuthorization calldata sale,
        bytes32 id,
        bytes32 digest,
        uint256 tokenId,
        bytes32 operationRoot,
        address wallet
    ) private {
        emit NativeSaleSettled(
            id, operationRoot, tokenId, digest, sale.profileId, wallet, sale.price
        );
        emit SaleParticipants(id, sale.collectionId, sale.artist, sale.payer, sale.recipient);
    }

    function _requireSignature(address signer, bytes32 digest, bytes calldata signature)
        private
        view
    {
        if (!StreamSaleSignatures.isValid(signer, digest, signature)) {
            revert InvalidSaleSignature(signer);
        }
    }
}

smart-contracts/domains/mint/StreamMintC.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/core/IStreamCore.sol";
import "../../interfaces/stream/mint/IStreamMintManager.sol";

/// @notice Core token execution and token-level event emission for StreamMintManager.
/// @dev Library calls execute by delegatecall, so events retain the manager as their emitter.
library StreamMintCoreExecutor {
    event MintTokenExecuted(
        uint16 schemaVersion,
        bytes32 indexed operationId,
        uint256 indexed tokenId,
        bytes32 indexed operationRoot,
        uint256 collectionId,
        bytes32 phaseId,
        uint256 tokenIndex,
        address initialRecipient,
        address beneficiary,
        bytes32 tokenDataHash,
        bytes32 mintCommitment
    );
    event PreparedMintStarted(
        uint16 schemaVersion,
        bytes32 indexed operationId,
        uint256 indexed tokenId,
        uint256 indexed collectionId,
        bytes32 operationRoot,
        uint256 collectionSerial,
        address beneficiary,
        bytes32 tokenDataHash,
        bytes32 mintCommitment
    );
    event PreparedMintCompleted(
        uint16 schemaVersion,
        bytes32 indexed operationId,
        uint256 indexed tokenId,
        uint256 indexed collectionId,
        bytes32 operationRoot,
        address initialRecipient
    );

    struct TokenExecutionFact {
        bytes32 operationId;
        uint256 tokenId;
        bytes32 operationRoot;
        uint256 collectionId;
        bytes32 phaseId;
        uint256 tokenIndex;
        address initialRecipient;
        address beneficiary;
        bytes32 tokenDataHash;
        bytes32 mintCommitment;
        uint256 collectionSerial;
    }

    function executeSingleStep(
        IStreamCore core,
        IStreamMintManager.MintBatch calldata batch,
        uint256 tokenIndex,
        bytes32 operationRoot,
        bytes32 operationId,
        uint16 schemaVersion
    ) external returns (uint256 tokenId) {
        bytes32 tokenDataHash = keccak256(batch.tokenData[tokenIndex]);
        // Single-step identity is emitted by Core's TokenIdentityAllocated event.
        // slither-disable-next-line unused-return
        (tokenId,) = core.mintFromManager(
            batch.collectionId,
            batch.initialRecipients[tokenIndex],
            batch.tokenData[tokenIndex],
            tokenDataHash,
            batch.mintCommitments[tokenIndex]
        );
        TokenExecutionFact memory fact = _tokenExecutionFact(
            batch, tokenIndex, operationRoot, operationId, tokenId, tokenDataHash
        );
        emit MintTokenExecuted(
            schemaVersion,
            fact.operationId,
            fact.tokenId,
            fact.operationRoot,
            fact.collectionId,
            fact.phaseId,
            fact.tokenIndex,
            fact.initialRecipient,
            fact.beneficiary,
            fact.tokenDataHash,
            fact.mintCommitment
        );
    }

    function executePrepared(
        IStreamCore core,
        IStreamMintManager.MintBatch calldata batch,
        uint256 tokenIndex,
        bytes32 operationRoot,
        bytes32 operationId,
        uint16 schemaVersion
    ) external returns (uint256 tokenId) {
        bytes32 tokenDataHash = keccak256(batch.tokenData[tokenIndex]);
        uint256 collectionSerial;
        (tokenId, collectionSerial) = core.prepareMintFromManager(
            batch.collectionId, batch.tokenData[tokenIndex], tokenDataHash, operationId
        );
        TokenExecutionFact memory fact = _tokenExecutionFact(
            batch, tokenIndex, operationRoot, operationId, tokenId, tokenDataHash
        );
        fact.collectionSerial = collectionSerial;
        emit PreparedMintStarted(
            schemaVersion,
            fact.operationId,
            fact.tokenId,
            fact.collectionId,
            fact.operationRoot,
            fact.collectionSerial,
            fact.beneficiary,
            fact.tokenDataHash,
            fact.mintCommitment
        );
        core.completePreparedMintFromManager(
            tokenId, fact.initialRecipient, operationId, fact.mintCommitment
        );
        emit PreparedMintCompleted(
            schemaVersion,
            fact.operationId,
            fact.tokenId,
            fact.collectionId,
            fact.operationRoot,
            fact.initialRecipient
        );
    }

    function _tokenExecutionFact(
        IStreamMintManager.MintBatch calldata batch,
        uint256 tokenIndex,
        bytes32 operationRoot,
        bytes32 operationId,
        uint256 tokenId,
        bytes32 tokenDataHash
    ) private pure returns (TokenExecutionFact memory fact) {
        fact.operationId = operationId;
        fact.tokenId = tokenId;
        fact.operationRoot = operationRoot;
        fact.collectionId = batch.collectionId;
        fact.phaseId = batch.phaseId;
        fact.tokenIndex = tokenIndex;
        fact.initialRecipient = batch.initialRecipients[tokenIndex];
        fact.beneficiary = batch.beneficiaries[tokenIndex];
        fact.tokenDataHash = tokenDataHash;
        fact.mintCommitment = batch.mintCommitments[tokenIndex];
    }
}

smart-contracts/domains/mint/StreamMintG.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../vendor/openzeppelin/IERC165.sol";
import "../../interfaces/stream/mint/IStreamMintGate.sol";
import "../../interfaces/stream/mint/IStreamMintManager.sol";
import "../../interfaces/stream/mint/compatibility/IStreamMintModuleRegistry.sol";
import "../../interfaces/stream/modules/IStreamModuleRegistry.sol";
import "./StreamMintOperationIdentity.sol";

/// @notice Closed-world gate configuration and request validation for StreamMintManager.
/// @dev Linked so complete gate validation does not make the manager undeployable.
library StreamMintGateValidator {
    uint256 private constant GATE_ERC165_PROBE_GAS = 30_000;
    uint256 private constant MAX_GATE_NULLIFIERS = 16;
    bytes32 public constant MINT_GATE_MODULE_TYPE = keccak256("6529STREAM_MINT_GATE_V1");

    /// @notice Accepts the canonical registry and the historical mint-registry fixture surface.
    function isSupportedRegistry(IERC165 registry) external view returns (bool) {
        return address(registry).code.length != 0 && _supports(registry, type(IERC165).interfaceId)
            && !_supports(registry, 0xffffffff)
            && (_supports(registry, type(IStreamModuleRegistry).interfaceId)
                || _supports(registry, type(IStreamMintModuleRegistry).interfaceId));
    }

    struct GateCall {
        address gate;
        uint32 gasLimit;
        address executor;
        uint256 collectionId;
        bytes32 phaseId;
        address payer;
        address authorizer;
        address[] initialRecipients;
        address[] beneficiaries;
        bytes32 contextHash;
        bytes32 policyHash;
        bytes gateData;
    }

    function validateConfiguration(
        IStreamMintManager.MintGateConfig calldata gateConfig,
        IERC165 moduleRegistry
    ) external view returns (IStreamMintManager.MintGateConfig memory) {
        if (gateConfig.gate == address(0)) {
            if (
                gateConfig.gateConfigHash != bytes32(0) || gateConfig.gateCodehash != bytes32(0)
                    || gateConfig.gateMetadataHash != bytes32(0)
                    || gateConfig.gateSemanticVersion != 0 || gateConfig.gateGasLimit != 0
            ) {
                revert IStreamMintManager.InvalidMintGate(gateConfig.gate);
            }
            return gateConfig;
        }
        if (gateConfig.gateConfigHash == bytes32(0)) {
            revert IStreamMintManager.InvalidMintGate(gateConfig.gate);
        }

        IStreamMintModuleRegistry.MintModuleInfo memory info =
            _requireActiveGateInfo(moduleRegistry, gateConfig.gate);
        bytes32 actualCodehash = gateConfig.gate.codehash;
        if (gateConfig.gateCodehash != bytes32(0) && gateConfig.gateCodehash != actualCodehash) {
            revert IStreamMintManager.MintGateCodehashChanged(
                gateConfig.gate, gateConfig.gateCodehash, actualCodehash
            );
        }
        if (
            gateConfig.gateMetadataHash != bytes32(0)
                && gateConfig.gateMetadataHash != info.metadataHash
        ) {
            revert IStreamMintManager.InvalidMintGate(gateConfig.gate);
        }
        if (
            gateConfig.gateSemanticVersion != 0
                && gateConfig.gateSemanticVersion != info.semanticVersion
        ) {
            revert IStreamMintManager.InvalidMintGate(gateConfig.gate);
        }
        if (gateConfig.gateGasLimit != 0 && gateConfig.gateGasLimit != info.gasLimit) {
            revert IStreamMintManager.InvalidMintGate(gateConfig.gate);
        }

        return IStreamMintManager.MintGateConfig({
            gate: gateConfig.gate,
            gateConfigHash: gateConfig.gateConfigHash,
            gateCodehash: actualCodehash,
            gateMetadataHash: info.metadataHash,
            gateSemanticVersion: info.semanticVersion,
            gateGasLimit: info.gasLimit
        });
    }

    function validateAuthorization(
        IStreamMintManager.MintBatch calldata batch,
        bytes calldata gateData,
        uint256 quantity,
        bytes32 boundPolicyHash,
        IStreamMintManager.MintGateConfig memory gateConfig,
        IERC165 moduleRegistry,
        address executor
    ) external view returns (StreamMintOperationIdentity.MintAuthorization memory) {
        if (batch.authorizationId == bytes32(0)) {
            revert IStreamMintManager.MintAuthorizationRequired(batch.collectionId, batch.phaseId);
        }
        if (gateConfig.gate == address(0)) {
            if (batch.authorizer != address(0)) {
                revert IStreamMintManager.MintInvalidAuthorizerKind(
                    uint8(IStreamMintManager.AuthorizerKind.NONE), batch.authorizer
                );
            }
            return StreamMintOperationIdentity.MintAuthorization({
                authorizationId: batch.authorizationId,
                nullifiers: new bytes32[](0),
                authorizer: address(0),
                authorizerKind: IStreamMintManager.AuthorizerKind.NONE,
                maxQuantity: 0,
                gateHash: bytes32(0)
            });
        }

        _requireGateStillActive(moduleRegistry, gateConfig);
        IStreamMintGate.GateResult memory result =
            _callGate(batch, gateData, boundPolicyHash, gateConfig, executor);
        if (result.nullifiers.length > MAX_GATE_NULLIFIERS) {
            revert IStreamMintManager.MintGateNullifierCountExceeded(
                result.nullifiers.length, MAX_GATE_NULLIFIERS
            );
        }
        _canonicalizeNullifiers(result.nullifiers);
        if (result.maxQuantity != 0 && quantity > result.maxQuantity) {
            revert IStreamMintManager.MintGateQuantityExceeded(quantity, result.maxQuantity);
        }
        if (result.gateHash == bytes32(0)) {
            revert IStreamMintManager.MintGateHashRequired(gateConfig.gate);
        }
        if (result.authorizer != batch.authorizer) {
            revert IStreamMintManager.MintGateAuthorizerMismatch(
                batch.authorizer, result.authorizer
            );
        }
        _requireAuthorizerKind(result.authorizerKind, result.authorizer, executor);
        if (result.authorizationId != batch.authorizationId) {
            revert IStreamMintManager.MintGateAuthorizationMismatch(
                batch.authorizationId, result.authorizationId
            );
        }
        return StreamMintOperationIdentity.MintAuthorization({
            authorizationId: result.authorizationId,
            nullifiers: result.nullifiers,
            authorizer: result.authorizer,
            authorizerKind: IStreamMintManager.AuthorizerKind(result.authorizerKind),
            maxQuantity: result.maxQuantity,
            gateHash: result.gateHash
        });
    }

    function _callGate(
        IStreamMintManager.MintBatch calldata batch,
        bytes calldata gateData,
        bytes32 boundPolicyHash,
        IStreamMintManager.MintGateConfig memory gateConfig,
        address executor
    ) private view returns (IStreamMintGate.GateResult memory) {
        // Every GateCall field is assigned below before any field is read or encoded.
        // slither-disable-next-line uninitialized-local
        GateCall memory gateCall;
        gateCall.gate = gateConfig.gate;
        gateCall.gasLimit = gateConfig.gateGasLimit;
        gateCall.executor = executor;
        gateCall.collectionId = batch.collectionId;
        gateCall.phaseId = batch.phaseId;
        gateCall.payer = batch.payer;
        gateCall.authorizer = batch.authorizer;
        gateCall.initialRecipients = batch.initialRecipients;
        gateCall.beneficiaries = batch.beneficiaries;
        gateCall.contextHash = batch.contextHash;
        gateCall.policyHash = boundPolicyHash;
        gateCall.gateData = gateData;

        bytes memory payload = abi.encodeWithSelector(
            IStreamMintGate.validateMint.selector,
            address(this),
            gateCall.executor,
            gateCall.collectionId,
            gateCall.phaseId,
            gateCall.payer,
            gateCall.authorizer,
            gateCall.initialRecipients,
            gateCall.beneficiaries,
            gateCall.contextHash,
            gateCall.policyHash,
            gateCall.gateData
        );
        (bool ok, bytes memory returndata) =
            gateCall.gate.staticcall{ gas: gateCall.gasLimit }(payload);
        if (!ok) {
            revert IStreamMintManager.MintGateValidationFailed(gateCall.gate);
        }
        return abi.decode(returndata, (IStreamMintGate.GateResult));
    }

    function _requireAuthorizerKind(uint8 kind, address authorizer, address executor) private pure {
        if (kind > uint8(IStreamMintManager.AuthorizerKind.CALLER_ADAPTER)) {
            revert IStreamMintManager.MintInvalidAuthorizerKind(kind, authorizer);
        }
        IStreamMintManager.AuthorizerKind authorizerKind = IStreamMintManager.AuthorizerKind(kind);
        if (
            (authorizerKind == IStreamMintManager.AuthorizerKind.NONE && authorizer != address(0))
                || (authorizerKind != IStreamMintManager.AuthorizerKind.NONE
                    && authorizer == address(0))
                || (authorizerKind == IStreamMintManager.AuthorizerKind.CALLER_ADAPTER
                    && authorizer != executor)
        ) {
            revert IStreamMintManager.MintInvalidAuthorizerKind(kind, authorizer);
        }
    }

    function _canonicalizeNullifiers(bytes32[] memory nullifiers) private pure {
        for (uint256 i = 0; i < nullifiers.length; i++) {
            bytes32 value = nullifiers[i];
            if (value == bytes32(0)) {
                revert IStreamMintManager.MintGateNullifiersUnsupported(value);
            }
            uint256 j = i;
            while (j != 0 && uint256(nullifiers[j - 1]) > uint256(value)) {
                nullifiers[j] = nullifiers[j - 1];
                j--;
            }
            if (j != 0 && nullifiers[j - 1] == value) {
                revert IStreamMintManager.MintGateNullifiersUnsupported(value);
            }
            nullifiers[j] = value;
        }
    }

    function _requireGateStillActive(
        IERC165 moduleRegistry,
        IStreamMintManager.MintGateConfig memory gateConfig
    ) private view {
        IStreamMintModuleRegistry.MintModuleInfo memory info =
            _requireActiveGateInfo(moduleRegistry, gateConfig.gate);
        bytes32 actualCodehash = gateConfig.gate.codehash;
        if (actualCodehash != gateConfig.gateCodehash || actualCodehash != info.codehash) {
            revert IStreamMintManager.MintGateCodehashChanged(
                gateConfig.gate, gateConfig.gateCodehash, actualCodehash
            );
        }
        if (
            info.metadataHash != gateConfig.gateMetadataHash
                || info.semanticVersion != gateConfig.gateSemanticVersion
                || info.gasLimit != gateConfig.gateGasLimit
        ) {
            revert IStreamMintManager.MintGateNotActive(gateConfig.gate);
        }
    }

    function _requireActiveGateInfo(IERC165 moduleRegistry, address gate)
        private
        view
        returns (IStreamMintModuleRegistry.MintModuleInfo memory info)
    {
        if (_supports(moduleRegistry, type(IStreamModuleRegistry).interfaceId)) {
            return _canonicalGateInfo(IStreamModuleRegistry(address(moduleRegistry)), gate);
        }
        try IStreamMintModuleRegistry(address(moduleRegistry)).moduleInfo(gate) returns (
            IStreamMintModuleRegistry.MintModuleInfo memory moduleInfo
        ) {
            info = moduleInfo;
        } catch {
            revert IStreamMintManager.MintGateNotActive(gate);
        }
        if (
            info.status != IStreamMintModuleRegistry.ModuleStatus.ACTIVE
                || info.interfaceId != type(IStreamMintGate).interfaceId || info.gasLimit == 0
                || gate.code.length == 0 || info.codehash != gate.codehash
                || !_gateAdvertisesInterface(gate)
        ) {
            revert IStreamMintManager.MintGateNotActive(gate);
        }
    }

    function _canonicalGateInfo(IStreamModuleRegistry registry, address gate)
        private
        view
        returns (IStreamMintModuleRegistry.MintModuleInfo memory info)
    {
        StreamModuleRecord memory record = registry.moduleRecord(gate);
        if (
            record.status != ModuleRegistryStatus.ACTIVE
                || record.moduleType != MINT_GATE_MODULE_TYPE
                || record.interfaceId != type(IStreamMintGate).interfaceId
                || record.moduleGasLimit == 0 || record.moduleVersion == bytes32(0)
                || record.moduleManifestHash == bytes32(0) || record.revision == 0
                || gate.code.length == 0 || record.runtimeCodeHash != gate.codehash
                || !_gateAdvertisesInterface(gate)
        ) revert IStreamMintManager.MintGateNotActive(gate);
        // Preserve the existing phase ABI without truncating the canonical bytes32 version.
        // Both full commitments are pinned into the phase's metadata-identity field.
        info = IStreamMintModuleRegistry.MintModuleInfo({
            status: IStreamMintModuleRegistry.ModuleStatus.ACTIVE,
            interfaceId: record.interfaceId,
            semanticVersion: 0,
            codehash: record.runtimeCodeHash,
            metadataHash: keccak256(abi.encode(record.moduleVersion, record.moduleManifestHash)),
            gasLimit: record.moduleGasLimit
        });
    }

    function _supports(IERC165 target, bytes4 interfaceId) private view returns (bool) {
        try target.supportsInterface{ gas: GATE_ERC165_PROBE_GAS }(interfaceId) returns (
            bool supported
        ) {
            return supported;
        } catch {
            return false;
        }
    }

    function _gateAdvertisesInterface(address gate) private view returns (bool) {
        try IERC165(gate).supportsInterface{ gas: GATE_ERC165_PROBE_GAS }(
            type(IStreamMintGate).interfaceId
        ) returns (
            bool supported
        ) {
            return supported;
        } catch {
            return false;
        }
    }
}

