// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./IStreamGovernanceExecutor.sol";

/// @notice One ordinary governance batch in an atomically sealed genesis plan.
struct GenesisBatch {
    uint8 actionClass;
    GovernanceCall[] calls;
    bytes[] callDatas;
}

/// @notice One-time deployment initialization; ordinary governance keeps its delays.
interface IStreamGenesisInitializer {
    error GenesisPlanAlreadyCommitted();
    error InvalidGenesisPlan();
    error GenesisPlanHashMismatch(bytes32 expected, bytes32 actual);
    error GenesisAlreadyInitialized();
    error GenesisDidNotSeal();
    error GenesisPreparationAlreadyBound();

    event GenesisPlanCommitted(bytes32 indexed planHash, address indexed authority);
    event GenesisInitialized(bytes32 indexed planHash, uint256 batchCount);
    event GenesisPrepared(bytes32 indexed planHash);

    function genesisPlanHash() external view returns (bytes32);
    function genesisInitialized() external view returns (bool);
    function commitGenesisPlan(bytes32 planHash) external;
    /// @notice Hash the exact ABI argument bytes for the corresponding initializer
    ///         call, domain-separated by this chain and Executor. Use the same
    ///         encoding for hashing and initialization (including any trailing bytes).
    function hashGenesisPlan(
        SystemManifestBootstrapBinding calldata binding,
        GenesisBatch[] calldata batches
    ) external view returns (bytes32);
    function initializeGenesis(
        SystemManifestBootstrapBinding calldata binding,
        GenesisBatch[] calldata batches
    ) external;

    /// @notice Optionally bind the exact committed governance catalog/lifecycle
    ///         in a separate transaction before atomic product setup and sealing.
    /// @dev Uses the identical complete plan encoding. Preparation is durable;
    ///      failed initialization leaves it available for an exact-plan retry.
    ///      No ordinary pre-seal actions may run after the plan is committed.
    function prepareGenesis(
        SystemManifestBootstrapBinding calldata binding,
        GenesisBatch[] calldata batches
    ) external;
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamGovernanceTypes.sol";

/// @notice Governance-authorized control-plane changes and one-way bootstrap operations.
/// @dev Caller ABI for the same Executor address. Discovery continues to use
///      IStreamGovernanceExecutor; this caller subset is not a new ERC165 claim.
interface IStreamGovernanceAdmin {
    /// @notice Enables or disables a proposer through a direction-checked Executor self-call.
    function registerProposer(address account, bool enabled) external;

    /// @notice Enables or disables a canceller through a direction-checked Executor self-call.
    function registerCanceller(address account, bool enabled) external;

    /// @notice Changes native-transfer receiver eligibility; catalog admission is still required.
    function setApprovedNativeReceiver(address receiver, bool approved) external;

    /// @notice Changes whether an exact target selector is an admitted tightening operation.
    function setTighteningCall(address target, bytes4 selector, bool tightening) external;

    /// @notice Registers or removes the terminal-freeze classification of a target selector.
    function registerFreezeSelector(address target, bytes4 selector, bool freeze) external;

    /// @notice Replaces the governance root with a contract matching the expected runtime hash.
    function rotateGovernanceRoot(address newRoot, bytes32 expectedCodeHash) external;

    /// @notice Registers an exact target selector requiring an atomic manifest publication tail.
    function registerSystemManifestTailTrigger(
        address triggerTarget,
        bytes4 triggerSelector,
        uint8 allowedActionClassMask
    ) external;

    /// @notice Binds the one-way genesis authority, inventory, action policy, and manifest commitments.
    function bindSystemManifestBootstrap(SystemManifestBootstrapBinding calldata binding) external;

    /// @notice Permanently seals the bound bootstrap after validating its live manifest state.
    function sealSystemManifestBootstrap() external;
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./IStreamGovernanceExecutor.sol";

/// @notice Delayed, append-only extensions of the exact-target governance catalog.
/// @dev The genesis catalog is revision zero. Existing entries cannot be edited
///      or removed. An extension invalidates actions scheduled under older roots.
interface IStreamGovernanceCatalog {
    error GovernanceCatalogRevisionMismatch(uint64 expected, uint64 actual);
    error GovernanceCatalogDuplicateEntry(bytes32 key);
    error GovernanceCatalogExtensionSize(uint256 additions, uint256 total);
    error GovernanceCatalogExtensionComposition();

    event GovernanceActionPolicyExtended(
        uint64 indexed revision,
        bytes32 indexed oldCatalogHash,
        bytes32 indexed newCatalogHash,
        uint256 oldEntryCount,
        uint256 newEntryCount
    );

    /// @notice Append 1–64 entries, with a total catalog limit of 1,024.
    /// @dev Entries sort by keccak256(abi.encode(actionClass,target,selector)).
    ///      Requires a sealed Executor and an ordinary root-proposed class-3
    ///      batch consisting exactly of this call then manifest publication.
    function extendGovernanceActionPolicy(
        uint64 expectedRevision,
        bytes32 expectedOldCatalogHash,
        bytes32 expectedNewCatalogHash,
